const e=[{id:"gn-consonants",title:"자음 (Consonants) — Ten Core Shapes",mentalModel:"Think of consonants as MOUTH BLUEPRINTS. Each shape is a rough sketch of the part of your mouth that makes the sound. ㄱ looks like the back of the throat closing (a bent shape, like the back of your tongue pressing up). ㄴ looks like the tongue tip touching the roof of the mouth. ㅁ is a closed mouth (a box). ㅂ adds lips opening from that box. ㅅ is two lines like teeth. Once you see the blueprint, the sound is no longer random — it is a diagram.",formation:"Consonant placed at the top-left of a syllable block (onset position) or at the bottom (coda position, called 받침)",examples:[{ko:"가 / 고 / 구",romanization:"ga / go / gu",en:"ㄱ with different vowels",note:"ㄱ makes a 'g/k' sound — the shape curves like the back of the throat closing. Same consonant, different vowels produce different syllables"},{ko:"나 / 노 / 누",romanization:"na / no / nu",en:"ㄴ with different vowels",note:"ㄴ = 'n' — the shape shows the tongue tip pressed to the ridge behind the upper teeth; this is exactly the mouth position for 'n'"},{ko:"마 / 모 / 무",romanization:"ma / mo / mu",en:"ㅁ with different vowels",note:"ㅁ = 'm' — literally a box representing a closed mouth; lips close for 'm', which is what the box shape shows"},{ko:"바 / 보 / 부",romanization:"ba / bo / bu",en:"ㅂ with different vowels",note:"ㅂ = 'b/p' — the box (ㅁ) opens at the top as lips part; the two top strokes represent the lips opening"},{ko:"아 / 오 / 우",romanization:"a / o / u",en:"ㅇ as a silent placeholder — no consonant sound",note:"ㅇ in the onset (top) position is silent — it is a zero-sound placeholder so the syllable block can be built. When ㅇ appears at the bottom (받침), it makes an 'ng' sound"}],contrastPairs:[{a:{ko:"다 (ㄷ)",en:"da — 'd' made with the tongue flat against the ridge"},b:{ko:"나 (ㄴ)",en:"na — 'n' also made with the tongue at the same ridge"},explanation:"ㄷ and ㄴ look similar and use the same part of the mouth. The difference: ㄴ lets air flow through the nose (nasal), while ㄷ blocks and releases air through the mouth (stop). ㄴ has a curved foot shape; ㄷ adds a top horizontal line, making it 'heavier' — visually and phonetically."},{a:{ko:"사 (ㅅ)",en:"sa — soft 's' between vowels"},b:{ko:"자 (ㅈ)",en:"ja — 'j' / 'ch' sound, more pressure"},explanation:"Both ㅅ and ㅈ involve the front of the mouth. ㅅ (two lines like teeth) is a light 's/sh' shape. ㅈ adds a horizontal base, increasing the pressure to produce 'j'. More strokes in Hangul often means more mouth pressure for the sound."}],englishSpeakerPitfall:{wrong:"Reading 이 as 'ee' (as in 'see') — exactly like English",right:"이 is close to English 'ee' but shorter and unrounded — and only approximately. The real fix is to listen to a native speaker and imitate, not to map to English sounds.",explanation:"English speakers instinctively reach for their own vowel sounds when they see romanization. But Korean 이 is not English 'ee', Korean 으 has no English equivalent at all, and Korean ㄹ is not 'r' or 'l'. Romanization is a temporary scaffold — use it to check yourself, but learn the actual sounds by ear. The earlier you stop reading romanization as English, the faster your pronunciation improves."},exceptions:["ㄹ is romanized as 'r' between vowels (바람 = baram) and as 'l' at the end of a syllable (달 = dal), but it is neither the English 'r' nor 'l' — it is a single Korean sound that you learn by ear","ㅇ is silent at the start of a syllable but pronounced 'ng' at the bottom (받침): 강 = gang, 방 = bang","Some consonants sound different depending on their position in the word — this is called consonant assimilation and you will learn it naturally as your listening improves"]},{id:"gn-vowels",title:"모음 (Vowels) — Lines, Dots, and Direction",mentalModel:"Think of vowels as a COMPASS ROSE. Every basic Korean vowel is built from three strokes: a vertical line (|), a horizontal line (—), and a short tick that points like a compass needle. The tick's direction tells you the sound. When the tick points RIGHT from a vertical line → ㅏ (open 'a'). When it points LEFT → ㅓ (deeper 'uh'). Tick ABOVE a horizontal line → ㅗ ('o'). Tick BELOW → ㅜ ('oo'). No tick on horizontal → ㅡ (flat 'eu'). Vertical line alone → ㅣ ('ee'). Once you see the compass, you never forget which way the vowel sounds.",formation:"Tall vowels (ㅏ ㅓ ㅣ ㅐ ㅔ) sit to the RIGHT of the consonant. Wide vowels (ㅗ ㅜ ㅡ) sit BELOW the consonant. Combined vowels are built by merging two basic vowels.",examples:[{ko:"아 / 어",romanization:"a / eo",en:"ㅏ vs ㅓ — both tall vowels beside the consonant",note:"ㅏ: tick points RIGHT — mouth open, sound comes forward. ㅓ: tick points LEFT — sound pulls back in the throat. The tick is the only difference on the page and in your mouth."},{ko:"오 / 우",romanization:"o / u",en:"ㅗ vs ㅜ — both wide vowels below the consonant",note:"ㅗ: tick points UP from the horizontal line — lips round and rise. ㅜ: tick points DOWN — lips round and drop. The compass direction = the lip movement direction."},{ko:"으 / 이",romanization:"eu / i",en:"ㅡ vs ㅣ — no tick needed",note:"ㅡ: just the horizontal bar — the mouth is flat and neutral, no rounding. ㅣ: just the vertical bar — teeth close, sound is 'ee'. These are the simplest vowel shapes."},{ko:"애 / 에",romanization:"ae / e",en:"Combined vowels — ㅏ+ㅣ and ㅓ+ㅣ",note:"ㅐ (ㅏ+ㅣ) and ㅔ (ㅓ+ㅣ) look similar and in modern Korean are often pronounced identically as a mid-front 'e' sound. Beginners can treat them the same."},{ko:"와 / 워 / 위",romanization:"wa / wo / wi",en:"Compound vowels starting with ㅗ/ㅜ",note:"ㅗ+ㅏ = ㅘ (wa), ㅜ+ㅓ = ㅝ (wo/weo), ㅜ+ㅣ = ㅟ (wi). These compound vowels are built by stacking two base vowels — you can decode them by recognizing the parts"}],contrastPairs:[{a:{ko:"보 (ㅗ)",en:"bo — tall 'o', lips rounded, sound rises"},b:{ko:"부 (ㅜ)",en:"bu — deep 'oo', lips rounded, sound drops"},explanation:"Same consonant ㅂ, different vowels. ㅗ sits with its tick pointing UP — the vowel shape tells you the sound moves upward/forward in the mouth. ㅜ has its tick pointing DOWN — the sound descends to a deeper 'oo'. The visual and physical direction match."},{a:{ko:"하 (ㅏ)",en:"ha — open 'a', mouth opens wide"},b:{ko:"허 (ㅓ)",en:"heo — 'uh', sound pulls back"},explanation:"ㅏ and ㅓ look almost the same but the tick faces opposite directions. ㅏ faces right (toward open space) → mouth opens. ㅓ faces left (inward) → the sound retreats to the back of the mouth. This is not coincidence — King Sejong's design mapped physical articulation to visual direction."}],englishSpeakerPitfall:{wrong:"Pronouncing 으 (ㅡ) as 'oo' or 'u' based on romanization 'eu'",right:"으 has no English equivalent — it is a central unrounded vowel. Keep your lips flat (no rounding) and the tongue in the middle of the mouth.",explanation:"The romanization 'eu' looks like the French 'eu' or English 'uh', so beginners round their lips. But 으 is made with flat, unrounded lips — the opposite of 'oo'. To train this sound: say 'ee' (이) and keep your lips in exactly that flat position, then move your tongue back. The sound you get is 으. Practice 이 then 으 back and forth."},exceptions:["ㅢ (의) is technically ㅡ+ㅣ but in natural speech it often sounds like just 이 (ee) or 에 (e) depending on position: 의사 = 'uisa' (doctor) but the particle 의 usually sounds like 에","Vowel length (long vs. short) existed in classical Korean but modern Seoul Korean has largely lost it — beginners can ignore vowel length completely","ㅙ (ㅗ+ㅐ) and ㅞ (ㅜ+ㅔ) are different from ㅘ [wa] and ㅝ [wo]. In much modern Seoul speech ㅙ and ㅞ may sound close to each other (and ㅚ may also be pronounced like ㅞ), so learn them from complete words rather than matching them to ㅘ/ㅝ"]}],o=[{title:"N은/는 — topic marker",func:'은/는 marks the topic of a sentence — the thing you single out to talk about ("as for ___"). It is the backbone of introductions and of saying what something is.',formTable:[{when:"Noun ends in a consonant (받침)",add:"은",ex:"이름 → 이름은 · 선생님 → 선생님은"},{when:"Noun ends in a vowel",add:"는",ex:"저 → 저는 · 어머니 → 어머니는"}],examples:[{ko:"저는 마이클이에요.",romanization:"jeoneun maikeurieyo.",en:"I'm Michael.",note:"Introducing yourself — 저 ends in a vowel, so 는."},{ko:"이름은 뭐예요?",romanization:"ireumeun mwoyeyo?",en:"What's your name?",note:"The topic is 'the name' — 이름 ends in a consonant, so 은."},{ko:"오늘은 바빠요.",romanization:"oneureun bappayo.",en:"Today I'm busy.",note:"Spotlighting 오늘 hints at a contrast — other days may be different."},{ko:"친구는 한국 사람이에요.",romanization:"chinguneun hanguk saramieyo.",en:"My friend is Korean.",note:"친구 ends in a vowel → 는. Everyday topic, everyday words."}],keyPoint:{label:"은/는 also hints at a contrast",body:"Besides naming the topic, 은/는 often quietly sets one thing against others. 저는 학생이에요 = 'as for me, I'm a student' (someone else might not be). 오늘은 바빠요 = 'today I'm busy' (other days, maybe not). You don't have to force this nuance — just notice that spotlighting something with 은/는 can imply a comparison."},pronunciation:"이름은 is pronounced [이르믄]: the final ㅁ links into the next vowel (linking, 연음).",drill:{instruction:"Say it about yourself — follow the model.",model:"저는 (마이클)이에요. → 저는 (학생)이에요. → 저는 (미국 사람)이에요.",items:["저는 ______이에요.","제 이름은 ______이에요.","오늘은 ______."]},englishSpeakerPitfall:{wrong:"나는 이름 마이클이에요.",right:"저는 마이클이에요.",explanation:`Don't translate "my name" word for word. 저는 ___이에요 already means "as for me, I'm ___," so there is no separate word for "name" here. Also use 저 (polite I), not 나 (casual), with people you have just met.`}},{title:'N이에요/예요 — polite "to be"',func:`이에요/예요 is the polite present tense of 이다 ("to be"). Attach it to a noun to say what something is: 저는 학생이에요 — "I'm a student."`,formTable:[{when:"Noun ends in a consonant (받침)",add:"이에요",ex:"학생 → 학생이에요 · 선생님 → 선생님이에요"},{when:"Noun ends in a vowel",add:"예요",ex:"의사 → 의사예요 · 하나 → 하나예요"}],examples:[{ko:"저는 학생이에요.",romanization:"jeoneun haksaengieyo.",en:"I'm a student.",note:"학생 ends in a consonant → 이에요."},{ko:"저는 하나예요.",romanization:"jeoneun hanayeyo.",en:"I'm Hana.",note:"하나 ends in a vowel → 예요."},{ko:"이분은 선생님이에요.",romanization:"ibuneun seonsaengnimieyo.",en:"This person is a teacher.",note:"It works for other people too — 이분 = 'this person' (polite)."},{ko:"이건 물이에요.",romanization:"igeon murieyo.",en:"This is water.",note:"물 ends in a consonant → 이에요."}],keyPoint:{label:"Polite vs formal, and the negative",body:`이에요/예요 is the everyday polite form — use it in class, with new acquaintances, and in shops. 입니다 (저는 학생입니다) is more formal: presentations, business, announcements. Both are correct, but 이에요/예요 is the natural default in conversation. To say what something is NOT, use N이/가 아니에요: 저는 학생이 아니에요 ("I'm not a student").`},pronunciation:"학생이에요 is pronounced [학쌩이에요]: ㄱ followed by ㅅ tightens the ㅅ to a tense [ㅆ].",drill:{instruction:"Introduce three people — follow the model.",model:"저는 (학생)이에요. → 이분은 (선생님)이에요. → 친구는 (의사)예요.",items:["저는 ______이에요/예요.","이분은 ______이에요/예요.","제 친구는 ______이에요/예요."]},englishSpeakerPitfall:{wrong:"저는 학생예요.",right:"저는 학생이에요.",explanation:"A consonant ending needs 이에요. 학생 ends in ㅇ (a 받침), so 학생예요 is wrong. Feel the final sound: a consonant takes 이에요, a vowel takes 예요."}}],n=[{title:'N이에요/예요 — the polite copula ("is/am/are")',func:'N이에요/예요 turns a noun into a polite statement of identity: "X is a/an N." It is the everyday spoken way to say what someone or something is. The negative — "X is not an N" — is N이/가 아니에요.',formTable:[{when:"Noun ends in a consonant (받침)",add:"이에요",ex:"학생 → 학생이에요 · 집 → 집이에요"},{when:"Noun ends in a vowel",add:"예요",ex:"친구 → 친구예요 · 의자 → 의자예요"},{when:'Negative: "is not N" (받침 noun)',add:"이 아니에요",ex:"학생 → 학생이 아니에요"},{when:'Negative: "is not N" (vowel noun)',add:"가 아니에요",ex:"친구 → 친구가 아니에요"}],examples:[{ko:"저는 학생이에요.",romanization:"jeo-neun hak-saeng-i-e-yo.",en:"I'm a student.",note:"학생 ends in a consonant (받침 ㅇ) → 이에요."},{ko:"이건 물이에요.",romanization:"i-geon mu-ri-e-yo.",en:"This is water.",note:"물 ends in a consonant (ㄹ) → 이에요; spoken [무리에요] by linking. 이건 = 이것은 (this) shortened."},{ko:"이분은 제 친구예요.",romanization:"i-bu-neun je chin-gu-ye-yo.",en:"This (person) is my friend.",note:"친구 ends in a vowel → 예요, not 이에요."},{ko:"여기는 학교가 아니에요.",romanization:"yeo-gi-neun hak-gyo-ga a-ni-e-yo.",en:"This place isn't a school.",note:"Negative of a vowel noun: 학교 + 가 아니에요. You attach 이/가 (never 이에요/예요) to the noun before 아니에요."}],keyPoint:{label:"이에요/예요 vs 입니다",body:'Both mean "is." 이에요/예요 is the polite-conversational 해요체 you use in everyday talk. 입니다 is the formal 합니다체 used in announcements, presentations, the news, and the military. 입니다 attaches the same way regardless of 받침 — 학생입니다, 친구입니다 (no 이에요/예요 split). They mean the same thing; you choose by setting. This chapter uses 이에요/예요; 입니다 gets its own chapter.'},pronunciation:"After a 받침 noun, 이에요 links onto the consonant: 물이에요 is pronounced [무리에요] and 집이 아니에요 is [지비 아니에요] (연음 — the final consonant slides onto the following vowel).",drill:{instruction:"Say what each thing is — follow the model, choosing 이에요 or 예요.",model:"(학생) → 학생이에요. / (친구) → 친구예요.",items:["(물) → ______","(가방) → ______","(의자) → ______"]},englishSpeakerPitfall:{wrong:"친구이에요 / 학생예요",right:"친구예요 / 학생이에요",explanation:`English has one form, "is," for everything, so learners pick 이에요 or 예요 at random. In Korean the choice is automatic and depends only on the noun's last sound: 받침 → 이에요, vowel → 예요. Check the noun's ending first, then attach the matching form.`}},{title:"N은/는 — the topic marker",func:'은/는 attaches to a noun to mark it as the topic — the thing you single out to talk about, roughly "as for ___." It is the backbone of introductions (저는…) and of stating what something is, and it can also signal a contrast between two things.',formTable:[{when:"Noun ends in a consonant (받침)",add:"은",ex:"집 → 집은 · 선생님 → 선생님은"},{when:"Noun ends in a vowel",add:"는",ex:"저 → 저는 · 친구 → 친구는"}],examples:[{ko:"저는 한국어 학생이에요.",romanization:"jeo-neun han-gu-geo hak-saeng-i-e-yo.",en:"I'm a Korean(-language) student.",note:"저 ends in a vowel → 는. The standard self-introduction frame."},{ko:"이 책은 한국어 책이에요.",romanization:"i chae-geun han-gu-geo chae-gi-e-yo.",en:"This book is a Korean book.",note:"책 ends in a consonant → 은; spoken [채근] by linking."},{ko:"선생님은 한국 사람이에요.",romanization:"seon-saeng-ni-meun han-guk sa-ra-mi-e-yo.",en:"The teacher is Korean.",note:"선생님 ends in a consonant → 은; spoken [선생니믄]. 은/는 raises 선생님 as the topic we're describing."},{ko:"저는 학생이에요. 친구는 의사예요.",romanization:"jeo-neun hak-saeng-i-e-yo. chin-gu-neun ui-sa-ye-yo.",en:"I'm a student. My friend is a doctor.",note:"Two 는 set up a contrast — me vs. my friend — another core job of 은/는."}],keyPoint:{label:"Topic, not subject — 은/는 vs 이/가",body:'은/는 marks the topic ("as for X, …") and often carries a quiet comparison; 이/가 marks the grammatical subject and points to new or specific information (누가 왔어요? — 친구가 왔어요). For now, use 은/는 for introductions and for saying what something is, and use 이/가 when answering "who/what?" The full 은/는 vs 이/가 distinction has its own chapter.'},pronunciation:"After a 받침 noun, 은 links onto the consonant: 책은 is pronounced [채근] and 집은 is [지븐] (연음).",drill:{instruction:"Introduce each person — follow the model, choosing 은 or 는.",model:"(저 / 학생) → 저는 학생이에요. / (친구 / 의사) → 친구는 의사예요.",items:["(저 / 한국어 학생) → ______","(이분 / 제 친구) → ______","(선생님 / 한국 사람) → ______"]},englishSpeakerPitfall:{wrong:"저는도 학생이에요.",right:"저도 학생이에요.",explanation:`English keeps the subject the same whether you add "too" or not ("I'm a student" / "I'm a student too"). In Korean, 도 ("also") replaces 은/는 rather than stacking onto it. Drop the 는 and say 저도 — never 저는도.`}}],t=[{title:"있어요/없어요 — there is / isn't, have / don't have",func:`있어요 says that something exists or is present ("there is"), and also that you have it ("I have ___"). 없어요 is its opposite — "there isn't" / "I don't have ___." One pair of verbs covers both existence and possession, so it's one of the most useful things to learn early.`,formTable:[{when:"Something exists / is present",add:"있어요",ex:"친구 → 친구가 있어요 · 책 → 책이 있어요"},{when:"Something doesn't exist / you don't have it",add:"없어요",ex:"시간 → 시간이 없어요 · 돈 → 돈이 없어요"},{when:"Asking 'is there…?' / 'do you have…?'",add:"있어요? / 없어요?",ex:"시간 있어요? · 물 없어요?"}],examples:[{ko:"물이 있어요.",romanization:"muri isseoyo.",en:"There is water. / I have water.",note:"The thing that exists takes 이/가; 물 ends in a consonant → 이."},{ko:"친구가 없어요.",romanization:"chinguga eopseoyo.",en:"I don't have any friends here. / There's no friend.",note:"친구 ends in a vowel → 가. 없어요 is the negative of 있어요."},{ko:"시간 있어요?",romanization:"sigan isseoyo?",en:"Do you have time?",note:"In everyday speech the 이/가 is usually dropped — 시간(이) 있어요?"},{ko:"집에 책이 많이 있어요.",romanization:"jibe chaegi mani isseoyo.",en:"There are a lot of books at home.",note:"집에 = 'at home' (location, 에); the thing that exists, 책, still takes 이/가."}],keyPoint:{label:"있어요 (exists / have) ≠ 이에요/예요 (is / equals)",body:`이에요/예요 says what something IS — its identity: 저는 학생이에요 = "I'm a student." 있어요/없어요 says something EXISTS, or that you HAVE it: 학생이 있어요 = "There's a student." English uses "there is" for both ideas, so beginners grab the wrong one. Quick test: if you can swap in "have" or "there is/exists," use 있어요; if you mean "X equals Y," use 이에요/예요. (The deeper rules of 이에요/예요 are in chapter 03.)`},pronunciation:"있어요 is pronounced [이써요]: the 받침 ㅆ carries over onto the next vowel (linking, 연음).",drill:{instruction:"Say it about your own life — fill in a noun and keep the 이/가.",model:"물이 있어요. → 시간이 있어요. → 돈이 없어요.",items:["______이/가 있어요.","______이/가 없어요.","한국어 책이 ______. (있어요 / 없어요)"]},englishSpeakerPitfall:{wrong:'저는 친구예요. (meaning "I have a friend.")',right:"친구가 있어요.",explanation:'예요/이에요 means "to be (equal something)," so 저는 친구예요 says "I AM a friend," not "I have a friend." To say you have something, use 있어요: 친구가 있어요. Korean has no separate verb "to have" — possession is just existence with 있어요/없어요.'}},{title:"N이/가 — the subject particle",func:`이/가 marks the grammatical subject — the doer, or the thing that exists — especially when it's new information or the specific answer to a question. It's the natural partner of 있어요/없어요 (친구가 있어요) and the marker for "who/what" questions and their answers.`,formTable:[{when:"Noun ends in a consonant (받침)",add:"이",ex:"책 → 책이 · 물 → 물이"},{when:"Noun ends in a vowel",add:"가",ex:"친구 → 친구가 · 학교 → 학교가"},{when:"Irregular forms with 가",add:"제가 / 내가 / 누가",ex:"저 → 제가 (not 저가) · 나 → 내가 · 누구 → 누가"}],examples:[{ko:"친구가 와요.",romanization:"chinguga wayo.",en:"A friend is coming.",note:"친구 ends in a vowel → 가. Something new arriving on the scene takes 이/가."},{ko:"물이 없어요.",romanization:"muri eopseoyo.",en:"There's no water.",note:"물 ends in a consonant → 이. With 있어요/없어요 the existing thing takes 이/가."},{ko:"누가 학생이에요?",romanization:"nuga haksaengieyo?",en:"Who is a student?",note:"누구 + 가 contracts to 누가. 'Who?' questions take 이/가, not 은/는."},{ko:"제가 한국 사람이에요.",romanization:"jega hanguk saramieyo.",en:"I'm Korean. (answering 'who?')",note:"저 + 가 is the irregular 제가, never 저가. Used to pin down 'who.'"}],keyPoint:{label:"이/가 (subject / new) vs 은/는 (topic / known)",body:`This is the contrast that confuses every learner. 은/는 sets the topic — "as for ___" — known information you want to comment on (저는 학생이에요). 이/가 spotlights the subject as NEW or SPECIFIC — it points and says "this one." The clearest test is a question: 누가 왔어요? ("Who came?") asks for new info, so the answer 친구가 왔어요 takes 이/가 — that's the new piece. Once it's established you can switch to 는: 친구가 왔어요. 그 친구는 미국 사람이에요. Note too that 있어요/없어요 almost always pairs with 이/가. (The full 은/는 vs 이/가 story is its own chapter — here just learn that answers to who/what questions and existence both take 이/가.)`},pronunciation:"책이 is pronounced [채기]: the 받침 ㄱ carries onto the next vowel (linking, 연음).",drill:{instruction:"Answer the 'who/what' question — the answer is new info, so use 이/가.",model:"누가 와요? → 친구가 와요. / 뭐가 있어요? → 물이 있어요.",items:["누가 학생이에요? → ______이/가 학생이에요.","뭐가 없어요? → ______이/가 없어요.","누가 한국어를 해요? → ______ 한국어를 해요. (answer with 저 → 제가)"]},englishSpeakerPitfall:{wrong:"저가 한국 사람이에요.",right:"제가 한국 사람이에요.",explanation:'When 이/가 follows 저 ("I"), the form is the irregular 제가 — never 저가. The same happens with 나 → 내가 and 누구 → 누가. Beginners regularize to 저가 because the rule says "vowel + 가," but these three pronouns are fixed exceptions you just memorize.'}}],a=[{title:"N을/를 — the object particle",func:"을/를 marks the object of a sentence — the thing the action happens to (what you eat, drink, read, watch). It attaches to the noun that receives the verb's action, so it is the partner of every action verb you learn.",formTable:[{when:"Noun ends in a consonant (받침)",add:"을",ex:"밥 → 밥을 · 책 → 책을 · 물 → 물을"},{when:"Noun ends in a vowel (no 받침)",add:"를",ex:"우유 → 우유를 · 커피 → 커피를 · 친구 → 친구를"}],examples:[{ko:"밥을 먹어요.",romanization:"bab-eul meogeoyo.",en:"I eat (a meal of) rice.",note:"밥 ends in a consonant (ㅂ 받침) → 을. 밥 is the object of 먹다."},{ko:"물을 마셔요.",romanization:"mul-eul masyeoyo.",en:"I drink water.",note:"물 ends in ㄹ 받침 (a consonant) → 을, not 를."},{ko:"책을 봐요.",romanization:"chaeg-eul bwayo.",en:"I read a book.",note:"책 ends in ㄱ 받침 → 을. 보다 here means 'read / look at'."},{ko:"친구를 만나요.",romanization:"chingu-reul mannayo.",en:"I meet a friend.",note:"친구 ends in a vowel (ㅜ), no 받침 → 를. 만나다 takes its object with 을/를, not 와/과."}],keyPoint:{label:"Object 을/를 vs subject 이/가",body:"을/를 marks WHAT receives the action (the object); 이/가 marks WHO does it (the subject). In 친구가 밥을 먹어요 (A friend eats), 친구 is the doer → 가, and 밥 is the thing eaten → 을. Don't swap them. In casual speech Koreans often drop 을/를 (밥 먹어요), but learn to add it correctly first — the dropping comes naturally later.",when:"",add:"",ex:""},pronunciation:"밥을 is pronounced [바블]: the final ㅂ links into the following vowel (linking, 연음). Likewise 책을 → [채글], 한국어를 → [한구거를].",drill:{instruction:"Add the right object particle and say the full sentence — follow the model.",model:"(물) 마셔요. → 물을 마셔요. · (커피) 마셔요. → 커피를 마셔요.",items:["(밥) 먹어요. → ______","(책) 봐요. → ______","(친구) 만나요. → ______","(한국어) 공부해요. → ______"]},englishSpeakerPitfall:{wrong:"저는 밥 먹어요 treated as the 'correct, complete' textbook form",right:"저는 밥을 먹어요.",explanation:"English has no object particle, so learners forget 을/를 and treat the bare noun as finished. The neutral, fully-formed sentence keeps the particle; dropping it is a casual-speech shortcut, not the default you should write."}},{title:"안 + verb — the short negative",func:"안 makes a verb negative — it means 'do not / does not'. You put 안 directly in front of the verb to say you don't do the action (안 먹어요 = I don't eat).",formTable:[{when:"Ordinary action verb",add:"안 + verb",ex:"먹어요 → 안 먹어요 · 봐요 → 안 봐요 · 마셔요 → 안 마셔요"},{when:"하다 verb (noun + 하다)",add:"안 goes between the noun and 하다",ex:"공부해요 → 공부 안 해요 · 운동해요 → 운동 안 해요"}],examples:[{ko:"저는 밥을 안 먹어요.",romanization:"jeoneun bab-eul an meogeoyo.",en:"I don't eat (the meal).",note:"안 sits right before the verb 먹어요. The object 밥을 keeps its normal place."},{ko:"물을 안 마셔요.",romanization:"mul-eul an masyeoyo.",en:"I don't drink water.",note:"Simple verb → just 안 + 마셔요."},{ko:"친구가 책을 안 봐요.",romanization:"chinguga chaeg-eul an bwayo.",en:"My friend doesn't read books.",note:"안 negates the action 보다, not the object 책을."},{ko:"오늘은 한국어를 공부 안 해요.",romanization:"oneureun hangugeo-reul gongbu an haeyo.",en:"Today I don't study Korean.",note:"With a 하다 verb, 안 splits in: 공부 안 해요, NOT 안 공부해요."}],keyPoint:{label:"안 (choose not to) vs 못 (can't) — preview",body:"안 means you simply don't / choose not to do something (안 먹어요 = I don't eat it). 못 means you're unable to even though you might want to (못 먹어요 = I can't eat it). Both go in front of the verb, but the meaning differs: 안 = won't / don't, 못 = can't. You'll practice 못 in its own chapter — for now just remember 안 is the everyday negative.",when:"",add:"",ex:""},pronunciation:"안 + verb does not fuse: the ㄴ of 안 stays crisp and there is no tensing on the verb (안 봐요 = [안봐요], not [안뽜요]). Keep them as two clear beats.",drill:{instruction:"Make each sentence negative with 안 — follow the model. Watch the 하다 verb.",model:"밥을 먹어요. → 밥을 안 먹어요. · 공부해요. → 공부 안 해요.",items:["물을 마셔요. → ______","책을 봐요. → ______","친구를 만나요. → ______","한국어를 공부해요. → ______"]},englishSpeakerPitfall:{wrong:"오늘은 한국어를 안 공부해요.",right:"오늘은 한국어를 공부 안 해요.",explanation:"English puts 'not' before the whole verb, so learners say 안 공부해요. But 공부하다 is noun(공부) + 하다, and 안 must slip between them: 공부 안 해요. This split only happens with 하다 verbs; ordinary verbs take 안 straight in front (안 먹어요)."}},{title:"자연스럽게 말하기 — How Korean actually sounds",func:"Korean squeezes its most common words the moment people speak, and those short forms are what fill KakaoTalk, subtitles, and everyday conversation. 저는 becomes 전, 것이 becomes 게, 무엇을 becomes 뭘. The meaning stays the same and so does the respect level — what shifts is how formal you sound, so these belong to speech rather than to a business email. You have just learned 은/는 and 을/를, so you can now see exactly what is being squeezed together.",formTable:[{when:"나는 / 저는 (topic)",add:"전 / 난",ex:`전 학생이에요. ("I'm a student.") — 난 is the same squeeze on 나는, but this app sticks to 저/전.`},{when:"너는 (topic) — read only",add:"넌",ex:`넌 어디 가? ("Where are you going?") — 반말. Read it, don't say it: use 전 + 해요체 instead.`},{when:"것이 / 것을 / 것은",add:"게 / 걸 / 건",ex:`먹을 게 없어요. ("There's nothing to eat.") · 이걸 주세요. ("Give me this one.") · 이건 뭐예요? ("What's this?")`},{when:"무엇을 / 무엇이",add:"뭘 / 뭐가",ex:`뭘 먹을까요? ("What shall we eat?") · 뭐가 맛있어요? ("What's tasty?") — 무엇 shrinks to 뭐 first, then 뭐+를 → 뭘; 뭐가 takes 가 because 뭐 ends in a vowel.`},{when:"것 같아요 (speech only)",add:"거 같아요",ex:`좋은 거 같아요. ("I think it's good.") — but write 좋은 것 같습니다 in an email or a report.`},{when:"이것 / 그것 / 저것",add:"이거 / 그거 / 저거",ex:'이거 주세요. ("This one, please.")'},{when:"-지요",add:"-죠",ex:`맛있죠? ("It's tasty, right?")`}],examples:[{ko:"전 커피를 마셔요.",romanization:"jeon keopi-reul masyeoyo.",en:"I drink coffee.",note:"저는 → 전. The topic marker 는 collapses onto 저. Still 해요체, still polite — 전 is not more casual than 저는."},{ko:"뭘 봐요?",romanization:"mwol bwayo?",en:"What are you watching?",note:"무엇을 → 뭘. In everyday conversation 뭘 (or 뭐) is the norm, even when you're being polite. 무엇을 isn't dead — it's just formal: you'll hear it from news anchors and in set service phrases like 무엇을 도와드릴까요?"},{ko:"이거 진짜 맛있는 거 같아요.",romanization:"igeo jinjja masinneun geo gatayo.",en:"I think this is really tasty.",note:"이것 → 이거, 것 같아요 → 거 같아요. Two contractions in one polite sentence — this is ordinary adult speech, not slang."},{ko:"오늘 좀 춥죠?",romanization:"chupjo.",en:"It's a bit cold today, isn't it?",note:"-지요 → -죠. The full -지요 sounds stiff in conversation; -죠 is what you actually hear."}],keyPoint:{label:"Shorter spelling, same politeness — but not the same formality",body:"A contraction changes the spelling, not the meaning and not the level of respect: 전 학생이에요 and 저는 학생이에요 are equally polite, and 이거 주세요 is no ruder than 이것을 주세요. What it does change is how FORMAL you sound. Short forms are speech; the full forms are for writing and for formal rooms — a job interview, a presentation, a business email, an exam. Say 거 같아요 to a friend or a coworker, but write 것 같습니다 in that email. And one warning: none of this rescues 넌. 너 is a 반말 word by itself, so 넌 stays 반말 even with -요 on the end. Politeness lives in the ending (-요, -습니다) and in which words you pick — never in how many syllables they have.",when:"",add:"",ex:""},pronunciation:"These short forms are the spoken sound written down — but watch the actual route. In speech 것 becomes 거, and only then do the particles fuse onto it: 거 + 이 → 게, 거 + 를 → 걸, 거 + 는 → 건. (Don't be fooled by the full forms: 것을 is pronounced [거슬], not [거를].) 뭘 takes the same route: 무엇 shrinks to 뭐 [무어 → 뭐], and then 뭐 + 를 → 뭘. And -지요 squeezes into one syllable as -죠, which is pronounced [조] — there is no 'y' glide in it, and after a 받침 it tightens: 춥죠 = [춥쪼].",drill:{instruction:"Say each sentence the way you would actually say it out loud — contract what can be contracted. Follow the model.",model:"저는 학생이에요. → 전 학생이에요. · 이것이 좋아요. → 이게 좋아요. · 그렇지요? → 그렇죠?",items:["저는 한국어를 공부해요. → ______","그것 좀 주세요. → ______","먹을 것이 없어요. → ______","오늘 바쁘지요? → ______"]},englishSpeakerPitfall:{wrong:"Avoiding 전 / 거 같아요 / 이거 because they look like slang or 반말",right:"전 학생이에요. · 좋은 거 같아요. · 이거 주세요.",explanation:`English contractions ("I'm", "gonna") really do drop the register, so learners assume Korean works the same way and stick to 저는 / 것 같아요 / 이것 to stay polite. It backfires: in conversation the full forms sound like a textbook being read aloud. Politeness in Korean lives in the ending (-요, -습니다), not in the length of the word. What shortness does signal is informality — so let 전 and 거 같아요 do the talking, and keep 저는 and 것 같습니다 for interviews, emails, and essays.`}}],s=[{title:"N에 — where you go, when it happens, where it is",func:'에 attaches to a noun to mark a destination (with 가다/오다), a point in time ("at/on"), or the place where someone or something simply exists (with 있다/없다). One way to keep it straight: 에 is for going there, being there, or when — never for an action you actually do at a place.',formTable:[{when:"Destination (with 가다/오다)",add:"에 가다 / 에 오다",ex:"학교 → 학교에 가요 · 집 → 집에 와요"},{when:"Where something is (with 있다/없다)",add:"에 있다 / 에 없다",ex:"집 → 집에 있어요 · 학교 → 학교에 없어요"},{when:"A point in time (clock time, day, date)",add:"에",ex:"세 시 → 세 시에 · 월요일 → 월요일에"},{when:"Time words that take NO 에",add:"(no 에)",ex:"오늘 · 어제 · 내일 · 지금 (오늘에 ✗)"}],examples:[{ko:"저는 학교에 가요.",romanization:"jeo-neun hak-gyo-e ga-yo.",en:"I go to school.",note:"에 marks 학교 as where I'm headed — the destination of 가다."},{ko:"친구가 집에 있어요.",romanization:"chin-gu-ga ji-be i-sseo-yo.",en:"My friend is at home.",note:"With 있다, 에 marks where someone simply is. 집에 sounds like [지베]."},{ko:"세 시에 친구를 만나요.",romanization:"se si-e chin-gu-reul man-na-yo.",en:"I meet a friend at three.",note:'에 on a clock time means "at" — 세 시에 = at 3:00.'},{ko:"오늘 집에 없어요.",romanization:"o-neul ji-be eop-seo-yo.",en:"I'm not home today.",note:"집에 takes 에, but 오늘 takes none — today/tomorrow/now never use it."}],keyPoint:{label:"에 vs 에서 — being there vs doing there",body:`Use 에 for where something IS or where you're GOING (있다/없다/가다/오다): 집에 있어요 (I'm at home), 학교에 가요 (I go to school). Use 에서 for where you DO something (먹다/공부하다/일하다 …): 집에서 밥을 먹어요 (I eat at home). Quick test: 있다/없다/가다/오다 → 에; any "doing" verb → 에서. The 에서 note below drills the full contrast.`},pronunciation:"After a 받침 noun, 에 slides onto the final consonant (연음): 집에 → [지베]. After a vowel there's nothing to link, so 학교에 stays [학꾜에] (and note 학교 itself is [학꾜]).",drill:{instruction:"Say where each person goes or is, adding 에 — follow the model.",model:"(학교 / 가다) → 학교에 가요. · (집 / 있다) → 집에 있어요.",items:["(집 / 가다) → ______","(학교 / 있다) → ______","(친구 집 / 없다) → ______"]},englishSpeakerPitfall:{wrong:"오늘에 학교에 가요.",right:"오늘 학교에 가요.",explanation:'Because of "at three / on Monday," learners stick 에 onto every time word. But 에 only goes on clock times, days, and dates (세 시에, 월요일에) — the words 오늘 (today), 어제 (yesterday), 내일 (tomorrow), and 지금 (now) never take it. Just memorize that short list.'}},{title:'N에서 — where you do something, and "from"',func:`에서 attaches to a place noun to mark where an action happens ("at/in"): 집에서 밥을 먹어요 (I eat at home). The same 에서 also marks a starting point — where something comes "from": 한국에서 왔어요 (I'm from Korea). Same particle, two jobs: where you do something, and where it starts from.`,formTable:[{when:'Where an action happens (with "doing" verbs)',add:"에서",ex:"집 → 집에서 먹어요 · 학교 → 학교에서 공부해요"},{when:'Starting point: "from" (with 오다)',add:"에서",ex:"한국 → 한국에서 왔어요 · 집 → 집에서 나와요"},{when:"Spoken short form (어디/여기/거기 + 에서)",add:"서",ex:"어디에서 → 어디서 · 여기에서 → 여기서"},{when:"Same form after 받침 or vowel",add:"에서",ex:"집 → 집에서 · 학교 → 학교에서"}],examples:[{ko:"집에서 밥을 먹어요.",romanization:"ji-be-seo ba-beul meo-geo-yo.",en:"I eat at home.",note:"먹다 is something you do, so the place takes 에서, not 에. Sounds like [지베서]."},{ko:"학교에서 한국어를 공부해요.",romanization:"hak-gyo-e-seo han-gu-geo-reul gong-bu-hae-yo.",en:"I study Korean at school.",note:"공부하다 is an action → 에서. Compare 학교에 가요 (going there)."},{ko:"저는 한국에서 왔어요.",romanization:"jeo-neun han-gu-ge-seo wa-sseo-yo.",en:"I'm from Korea.",note:'Here 에서 = "from," the starting point of 오다. Sounds like [한구게서].'},{ko:"친구를 어디서 만나요?",romanization:"chin-gu-reul eo-di-seo man-na-yo?",en:"Where do you meet your friend?",note:"만나다 is an action → 에서; 어디에서 shortens to 어디서 in everyday speech."}],keyPoint:{label:"에서 vs 에 — the action test",body:`Both sit on a place noun, but the verb decides which. 에서 + a "doing" verb = where you DO something: 도서관에서 책을 읽어요 (I read at the library). 에 + 있다/없다/가다/오다 = where you ARE or GO: 도서관에 있어요 (I'm at the library), 도서관에 가요 (I go to the library). Lock in the pair: 학교에 가요 (go to school) vs 학교에서 공부해요 (study at school).`},pronunciation:"After a 받침 noun, 에서 slides onto the final consonant (연음): 집에서 → [지베서], 한국에서 → [한구게서]. After a vowel there's nothing to link, so 학교에서 stays [학꾜에서].",drill:{instruction:"Say where each action happens, adding 에서 — follow the model.",model:"(집 / 밥을 먹다) → 집에서 밥을 먹어요. · (학교 / 공부하다) → 학교에서 공부해요.",items:["(집 / 영화를 보다) → ______","(학교 / 친구를 만나다) → ______","(도서관 / 책을 읽다) → ______"]},englishSpeakerPitfall:{wrong:"학교에 한국어를 공부해요.",right:"학교에서 한국어를 공부해요.",explanation:`English uses one word, "at," for both "I'm at school" and "I study at school," so learners grab 에 for both. Korean splits them: 에 is only for existence and destination (있다/없다/가다/오다), while anything you DO at a place needs 에서. If there's a real verb of doing — eating, studying, meeting, watching — use 에서.`}}],i=[{title:"도 vs 만 — also / too vs only",func:'도 means "also / too" and adds this noun to others; 만 means "only" and shuts out everything else. Both attach straight to a noun and take the place of the topic/subject/object marker (은/는/이/가/을/를) instead of sitting on top of it.',formTable:[{when:"Any noun (받침 or not) + 도",add:"+ 도",ex:"저 → 저도, 물 → 물도, 친구 → 친구도"},{when:"Any noun (받침 or not) + 만",add:"+ 만",ex:"물 → 물만, 밥 → 밥만, 학생 → 학생만"},{when:"Replaces 은/는/이/가 (never 저는도 / 친구가만)",add:"drop the marker, add 도/만",ex:"저는 → 저도 (NOT 저는도), 친구가 → 친구만"},{when:"Replaces 을/를 too",add:"drop 을/를, add 도/만",ex:"밥을 → 밥도 / 밥만, 책을 → 책도 / 책만"}],examples:[{ko:"저도 학생이에요.",romanization:"jeo-do hak-saeng-i-e-yo.",en:"I'm a student too.",note:'도 takes the place of 는 in 저는 — "me too," on top of the other students.'},{ko:"물만 주세요.",romanization:"mul-man ju-se-yo.",en:"Just water, please.",note:"만 = water and nothing else; super common when you're ordering."},{ko:"친구도 같이 가요.",romanization:"chin-gu-do ga-chi ga-yo.",en:"My friend is coming too.",note:"도 adds 친구 to the people already going; it replaces 가 in 친구가."},{ko:"저는 밥만 먹어요.",romanization:"jeo-neun bam-man meo-geo-yo.",en:"I only eat rice.",note:"만 stands in for the object marker 을 in 밥을 — rice and nothing else. (밥만 sounds like [밤만].)"}],keyPoint:{label:"도 vs 만",body:'도 includes (this AND the rest); 만 excludes (this and NOTHING else). Quick test: if "too" fits, use 도; if "just / nothing but" fits, use 만. Either way you drop 은/는/이/가/을/를 first — 저도, never 저는도; 밥만, never 밥을만.'},pronunciation:"만 after a 받침 nasalizes the consonant before it: 밥만 sounds like [밤만] (ㅂ → ㅁ before ㅁ).",drill:{instruction:"Add 도 (also) or 만 (only) to match the English. Drop any 은/는/이/가/을/를 first.",model:"저는 학생이에요. (also) → 저도 학생이에요.",items:["물을 주세요. (only) → ____ 주세요.","친구가 가요. (also) → ____ 가요.","저는 한국어를 공부해요. (only) → 저는 ____ 공부해요."]},englishSpeakerPitfall:{wrong:"저는도 학생이에요. / 밥을만 먹어요.",right:"저도 학생이에요. / 밥만 먹어요.",explanation:'In English you keep the subject and just bolt on "too," so learners want to hold onto 는/을 and add 도/만 after it. In Korean, 도/만 replace 은/는/이/가/을/를 — strip the old marker off completely, then add 도 or 만.'}},{title:"(으)로 — by / with, and which way",func:`(으)로 marks how you do something — the tool, language, payment method, or transport ("by / with / in") — and also the direction you head ("toward / to"). You'll reach for it constantly when paying and ordering.`,formTable:[{when:"Noun ends in a vowel",add:"+ 로",ex:"카드 → 카드로, 버스 → 버스로, 한국어 → 한국어로"},{when:"Noun ends in a 받침 (consonant)",add:"+ 으로",ex:"손 → 손으로, 젓가락 → 젓가락으로, 현금 → 현금으로"},{when:"Noun ends in ㄹ 받침 (special case)",add:"+ 로 (not 으로)",ex:"지하철 → 지하철로, 연필 → 연필로"},{when:'Direction "toward / to"',add:"+ (으)로",ex:"집 → 집으로, 학교 → 학교로, 이쪽 → 이쪽으로"}],examples:[{ko:"카드로 계산할게요.",romanization:"ka-deu-ro gye-san-hal-ge-yo.",en:"I'll pay by card.",note:"카드 ends in a vowel → 로. The exact thing you say at the register."},{ko:"한국어로 말해 주세요.",romanization:"han-gu-geo-ro mal-hae ju-se-yo.",en:"Please speak in Korean.",note:"한국어 ends in a vowel → 로; here 로 marks the language you're using."},{ko:"젓가락으로 먹어요.",romanization:"jeot-ga-ra-geu-ro meo-geo-yo.",en:"I eat with chopsticks.",note:"젓가락 ends in 받침 ㄱ → 으로; marks the tool you use."},{ko:"집으로 가요.",romanization:"ji-beu-ro ga-yo.",en:"I'm heading home.",note:"집 ends in 받침 ㅂ → 으로; here 로 marks direction, not a means."}],keyPoint:{label:"(으)로 vs 에 (direction)",body:`For where you're going, 에 marks the destination you arrive at (집에 가요 = go home), while (으)로 stresses the direction you head (집으로 가요 = head toward home) — at this level either is fine for "go home." Mostly you'll use the "by / with" sense: 카드로, 현금으로, 한국어로. Just watch the ㄹ rule — 지하철로, not 지하철으로.`,add:"",ex:"",when:""},pronunciation:"으로 after a 받침 pulls the consonant into 으: 손으로 sounds like [소느로], 집으로 like [지브로].",drill:{instruction:"Add 로 or 으로. Check whether the noun ends in a vowel, a 받침, or ㄹ.",model:"카드 (pay) → 카드로 계산해요.",items:["현금 (cash, pay) → ____ 계산해요.","숟가락 (spoon, eat) → ____ 먹어요.","지하철 (subway, go) → ____ 가요."]},englishSpeakerPitfall:{wrong:"지하철으로 가요. / 카드으로 계산해요.",right:"지하철로 가요. / 카드로 계산해요.",explanation:"Learners stretch the 받침 → 으로 rule too far. Vowel-final nouns just take 로 (카드로), and ㄹ-final words are a special case that also take plain 로, not 으로 (지하철로, 연필로). Only non-ㄹ 받침 nouns get 으로."}}],r=[{title:'-고 싶어요 — saying what you want to do ("I want to…")',func:"Add -고 싶어요 to a verb stem to say what you want to do. It's for your own wants; talking about what someone else wants uses -고 싶어 하다, which comes in a later chapter.",formTable:[{when:"Verb stem ends in a vowel",add:"stem + 고 싶어요",ex:"가다 → 가고 싶어요 (want to go)"},{when:"Verb stem ends in a consonant (받침)",add:"stem + 고 싶어요 (no change)",ex:"먹다 → 먹고 싶어요 (want to eat)"},{when:"Past and negative go on 싶다, not the main verb",add:"…고 싶었어요 (wanted to) / …고 싶지 않아요 (don't want to)",ex:"보다 → 보고 싶었어요 / 보고 싶지 않아요"}],examples:[{ko:"저는 물을 마시고 싶어요.",romanization:"jeoneun mureul masigo sipeoyo.",en:"I want to drink water.",note:"마시다 ends in a vowel → 마시고 싶어요. The object keeps 을/를 (물을)."},{ko:"오늘 친구를 만나고 싶어요.",romanization:"oneul chingureul mannago sipeoyo.",en:"I want to meet a friend today.",note:"만나다 → 만나고 싶어요. It's your own wish, so plain -고 싶어요 is right."},{ko:"집에서 영화를 보고 싶어요.",romanization:"jibeseo yeonghwareul bogo sipeoyo.",en:"I want to watch a movie at home.",note:"보다 → 보고 싶어요. The place where you do something takes 에서 (집에서)."},{ko:"한국어를 더 공부하고 싶었어요.",romanization:"hangugeoreul deo gongbuhago sipeosseoyo.",en:"I wanted to study Korean more.",note:"Past tense goes on 싶다 (싶었어요), never on 공부하다."}],keyPoint:{label:"Keep 을/를 on the thing you want",body:"With -고 싶어요 the thing you want is still the object, so use 을/를: 밥을 먹고 싶어요 (I want to eat). You'll also hear 밥이 먹고 싶어요 in casual speech, but 밥을 먹고 싶어요 is the safe, standard choice for now."},pronunciation:"싶어요 links across the boundary and sounds like [시퍼요]; 먹고 tenses the ㄱ, so 먹고 싶어요 sounds like [먹꼬 시퍼요].",drill:{instruction:'Turn each verb into an "I want to…" sentence with -고 싶어요.',model:"자다 → 자고 싶어요. (I want to sleep.)",items:["쉬다 → ____ (I want to rest.)","책을 읽다 → ____ (I want to read a book.)","집에 가다 → ____ (I want to go home.)"]},englishSpeakerPitfall:{wrong:"저는 행복하고 싶어요.",right:"저는 행복해지고 싶어요. / 행복하면 좋겠어요.",explanation:'"I want to be happy" tempts you to stick -고 싶어요 on 행복하다. But -고 싶어요 only goes on action verbs, not on adjectives (descriptive verbs). For a state, use 행복해지다 (become happy) or the wish pattern -으면 좋겠다.'}},{title:"-(으)ㄹ 수 있어요 / 없어요 — can and can't",func:`Add -(으)ㄹ 수 있어요 to a verb stem for "can / be able to," and -(으)ㄹ 수 없어요 for "can't." Putting 못 right before the verb is a shorter, more everyday way to say "can't."`,formTable:[{when:"Stem ends in a vowel",add:"stem + ㄹ 수 있어요/없어요",ex:"가다 → 갈 수 있어요 (can go) / 갈 수 없어요 (can't go)"},{when:"Stem ends in a consonant (받침)",add:"stem + 을 수 있어요/없어요",ex:"먹다 → 먹을 수 있어요 (can eat) / 먹을 수 없어요 (can't eat)"},{when:"Stem already ends in ㄹ",add:"stem + 수 있어요 (that ㄹ is the ending, add nothing)",ex:"만들다 → 만들 수 있어요 (can make)"},{when:`Using 못 for "can't"`,add:"못 + verb",ex:"먹다 → 못 먹어요 (can't eat) / 가다 → 못 가요 (can't go)"}],examples:[{ko:"저는 한국어를 조금 할 수 있어요.",romanization:"jeoneun hangugeoreul jogeum hal su isseoyo.",en:"I can speak a little Korean.",note:"하다 ends in a vowel → 할 수 있어요."},{ko:"오늘은 시간이 없어서 못 가요.",romanization:"oneureun sigani eopseoseo mot gayo.",en:"I can't go today because I don't have time.",note:`못 + 가요 is the short, natural way to say "can't" about one situation.`},{ko:"이 책은 너무 어려워서 읽을 수 없어요.",romanization:"i chaegeun neomu eoryeowoseo ilgeul su eopseoyo.",en:"This book is too hard, so I can't read it.",note:"읽다 ends in a consonant → 읽을 수 없어요."},{ko:"저는 김치를 만들 수 있어요.",romanization:"jeoneun gimchireul mandeul su isseoyo.",en:"I can make kimchi.",note:"만들다 already ends in ㄹ, so add nothing → 만들 수 있어요."}],keyPoint:{label:"못 (can't) vs 안 (don't / won't)",body:`Both sit right before the verb but mean different things. 못 = can't — you're unable, even if you'd like to (시간이 없어서 못 자요, I can't sleep because I have no time). 안 = a choice not to (피곤하지만 안 자요, I'm tired but I'm not going to sleep). So "can't eat" is 못 먹어요; "don't eat (by choice)" is 안 먹어요.`},pronunciation:"수 있어요 links to [수 이써요]; 못 changes before the next sound — 못 가요 sounds like [몯까요] and 못 먹어요 like [몬머거요].",drill:{instruction:`Make a "can" sentence with -(으)ㄹ 수 있어요, then a "can't" sentence with 못.`,model:"가다 → 갈 수 있어요. / 못 가요.",items:["먹다 → ____ / ____ (can eat / can't eat)","읽다 → ____ / ____ (can read / can't read)","오다 → ____ / ____ (can come / can't come)"]},englishSpeakerPitfall:{wrong:"저는 수영을 안 할 수 있어요.",right:"저는 수영을 못 해요. / 수영을 할 수 없어요.",explanation:`For "I can't swim," learners try to negate 할 수 있어요 by adding 안. Korean doesn't do that — switch the whole phrase to 없어요 (할 수 없어요), or more naturally say 못 해요. Save 안 for choosing not to do something.`}}],h=[{title:"V아/어 주세요 vs V아/어도 돼요? — Asking Someone to DO vs Asking IF You May",func:"Use V아/어 주세요 to politely ask someone to DO something for you ('please do X'). Use V아/어도 돼요? to ask whether YOU are allowed to do something ('is it okay if I do X?'). One asks the listener to act; the other asks the listener for permission.",formTable:[{when:"Stem's last vowel is ㅏ or ㅗ (bright)",add:"stem + 아 주세요 / 아도 돼요?",ex:"받다 → 받아 주세요 (please take it) · 앉다 → 앉아도 돼요? (may I sit?)"},{when:"Stem's last vowel is anything else (dark)",add:"stem + 어 주세요 / 어도 돼요?",ex:"읽다 → 읽어 주세요 (please read it) · 먹다 → 먹어도 돼요? (may I eat?)"},{when:"하다 verbs",add:"하 → 해 + 주세요 / 도 돼요?",ex:"말하다 → 말해 주세요 (please say it) · 전화하다 → 전화해도 돼요? (may I call?)"},{when:"Stem ends in ㅡ (the ㅡ drops)",add:"ㅡ → 어/아 form, then attach",ex:"쓰다 → 써 주세요 (please write it) · 끄다 → 꺼도 돼요? (may I turn it off?)"}],examples:[{ko:"물 좀 주세요.",romanization:"mul jom juseyo.",en:"Some water, please.",note:"주세요 attaches straight to a NOUN (물) to ask for the thing itself — no 아/어 needed. 좀 softens it, like 'a little.'"},{ko:"천천히 말해 주세요.",romanization:"cheoncheonhi malhae juseyo.",en:"Please speak slowly (for me).",note:"말하다 → 말해 + 주세요. The 아/어 주세요 form asks the listener to do the action for your benefit."},{ko:"여기 앉아도 돼요?",romanization:"yeogi anjado dwaeyo?",en:"Is it okay if I sit here?",note:"앉다 has ㅏ, so 앉아 + 도 돼요? You're asking permission for yourself, not asking them to do anything."},{ko:"사진 찍어도 돼요?",romanization:"sajin jjigeodo dwaeyo?",en:"Can I take a photo?",note:"찍다 has ㅣ (dark), so 찍어 + 도 돼요? Said with rising intonation, it's a real permission question."}],keyPoint:{label:"주세요 + noun vs 아/어 주세요 + verb",body:"주세요 alone follows a NOUN to ask for the thing: 물 주세요 (water, please), 메뉴 주세요 (the menu, please). To ask someone to DO an action, the verb must take its 아/어 form first: 도와주세요 (please help), 기다려 주세요 (please wait). Beginners often stick a plain dictionary verb in front of 주세요 (돕다 주세요 is wrong; 도와주세요 is right) — change the verb to its 아/어 form first."},pronunciation:"돼 is one syllable with a single [dwae] glide. 돼요 has two syllables, 돼-요 [dwae-yo] — keep 돼 together, then give 요 its own light beat.",drill:{instruction:"Decide if it's a REQUEST (아/어 주세요) or asking PERMISSION (아/어도 돼요?), then complete the sentence.",model:"창문을 (열다) → REQUEST: 창문을 열어 주세요. / PERMISSION: 창문을 열어도 돼요?",items:["이름을 (쓰다) → REQUEST: 이름을 ___ 주세요. (Please write your name → 써)","지금 (가다) → PERMISSION: 지금 ___ 돼요? (May I go now? → 가도)","문을 (닫다) → REQUEST: 문을 ___ 주세요. (Please close the door → 닫아)"]},englishSpeakerPitfall:{wrong:"여기 앉아 주세요? (when you mean 'May I sit here?')",right:"여기 앉아도 돼요?",explanation:"English uses 'can/may' for both 'please do this' and 'may I do this,' so learners mix the two Korean forms. 앉아 주세요 means 'please sit (for me)' — you're telling THEM to sit. To ask permission for yourself, add 도 돼요?: 앉아도 돼요? Remember: 아/어 주세요 = you act; 아/어도 돼요? = I'm allowed."}},{title:"V지 마세요 & V아/어야 돼요 — Telling Someone Not To, and Saying You Have To",func:"Use V지 마세요 to politely tell someone NOT to do something ('please don't do X'). Use V아/어야 돼요 to say something must be done ('have to do X'). Together they cover both sides of a rule: what's not allowed and what's required.",formTable:[{when:"Prohibition: any verb stem",add:"stem + 지 마세요",ex:"들어가다 → 들어가지 마세요 (don't go in) · 먹다 → 먹지 마세요 (don't eat it)"},{when:"Have to: stem vowel ㅏ/ㅗ",add:"stem + 아야 돼요",ex:"가다 → 가야 돼요 (have to go) · 자다 → 자야 돼요 (have to sleep)"},{when:"Have to: other stem vowels",add:"stem + 어야 돼요",ex:"먹다 → 먹어야 돼요 (have to eat) · 기다리다 → 기다려야 돼요 (have to wait)"},{when:"하다 verbs (have to)",add:"하 → 해 + 야 돼요",ex:"공부하다 → 공부해야 돼요 (have to study) · 일하다 → 일해야 돼요 (have to work)"}],examples:[{ko:"여기에서 담배를 피우지 마세요.",romanization:"yeogieseo dambaereul piuji maseyo.",en:"Please don't smoke here.",note:"피우다 → 피우 + 지 마세요. 지 마세요 attaches straight to the stem — no vowel harmony for prohibition."},{ko:"사진을 찍지 마세요.",romanization:"sajineul jjikji maseyo.",en:"Please don't take photos.",note:"찍다 → 찍 + 지 마세요. A common sign you'll see; the form is the same no matter the final consonant."},{ko:"내일 일찍 일어나야 돼요.",romanization:"naeil iljjik ireonaya dwaeyo.",en:"I have to get up early tomorrow.",note:"일어나다 ends in ㅏ → 일어나 + 야 돼요. 아/어야 돼요 and 아/어야 해요 mean the same thing; 돼요 is more common in everyday speech."},{ko:"약을 먹어야 돼요.",romanization:"yageul meogeoya dwaeyo.",en:"I have to take the medicine.",note:"먹다 (dark vowel) → 먹어 + 야 돼요. In Korean you 'eat' (먹다) medicine, not 'take' it."}],keyPoint:{label:"지 마세요 (don't!) vs 안 + verb (doesn't/isn't)",body:"지 마세요 is a COMMAND telling someone NOT to do something: 뛰지 마세요 (don't run). It is not how you say YOU don't do something — for that, use 안: 저는 안 뛰어요 (I don't run). So 지 마세요 is only for telling other people what not to do."},pronunciation:"In 먹어야 the ㄱ links into the next vowel, so it flows as [meo-geo-ya], one smooth piece rather than 먹+어야.",drill:{instruction:"Turn each cue into either a PROHIBITION (지 마세요) or a 'have to' (아/어야 돼요) as marked.",model:"(뛰다) PROHIBITION → 뛰지 마세요. / (자다) HAVE TO → 자야 돼요.",items:["(들어가다) PROHIBITION → 여기에 ___ . (Please don't go in here → 들어가지 마세요)","(공부하다) HAVE TO → 시험이 있어서 ___ . (I have to study because there's a test → 공부해야 돼요)","(기다리다) HAVE TO → 친구를 ___ . (I have to wait for my friend → 기다려야 돼요)"]},englishSpeakerPitfall:{wrong:"먹지 않으세요 (when you mean 'please don't eat it')",right:"먹지 마세요",explanation:"Learners build prohibition from the negative 지 않다 ('does not'), getting 먹지 않으세요, which sounds like an odd statement, not a command. Negative commands ('don't') use the special verb 말다: 먹지 마세요. Keep 안 먹어요 / 먹지 않아요 ('I don't eat it') for plain negatives, and 지 마세요 for telling someone not to do it."}}],l=[{title:"N부터 / N까지 — from … to … (ranges in time and space)",func:'부터 marks where a range starts and 까지 marks where it ends — "from A to B." They work for time (아홉 시부터 여섯 시까지, from 9 to 6) and for place (집부터 학교까지, from home to school), and each can appear alone too (부터 = "starting from," 까지 = "up until / by").',formTable:[{when:"Start point of a range (attaches to any noun)",add:"부터",ex:"아침 → 아침부터 · 한 시 → 한 시부터"},{when:"End point of a range (attaches to any noun)",add:"까지",ex:"저녁 → 저녁까지 · 여섯 시 → 여섯 시까지"},{when:"Place: from here to there",add:"부터 … 까지",ex:"집 → 집부터 · 학교 → 학교까지"},{when:'까지 used alone = a deadline, "by"',add:"까지",ex:"내일 → 내일까지 · 다섯 시 → 다섯 시까지"}],examples:[{ko:"아홉 시부터 여섯 시까지 일해요.",romanization:"a-hop si-bu-teo yeo-seot si-kka-ji il-hae-yo.",en:"I work from nine to six.",note:"Classic time range: 부터 on the start time, 까지 on the end time."},{ko:"집부터 학교까지 멀어요.",romanization:"jip-bu-teo hak-gyo-kka-ji meo-reo-yo.",en:"It's far from home to school.",note:"Place range with 부터…까지. You'll also often hear 집에서 학교까지 — see the key point below."},{ko:"몇 시부터 영화를 봐요?",romanization:"myeot si-bu-teo yeong-hwa-reul bwa-yo?",en:"From what time is the movie?",note:"부터 used alone to ask just the starting time."},{ko:"내일까지 책을 읽어요.",romanization:"nae-il-kka-ji chae-geul il-geo-yo.",en:"I'll read the book by tomorrow.",note:'까지 alone = a deadline, "by tomorrow."'}],keyPoint:{label:'부터 vs 에서 (both can mean "from")',body:`For a starting point you measure a stretch from — especially time — use 부터: 아침부터 (from morning). For a physical place you set out from, native speakers usually say 에서: 집에서 학교까지 (from home to school). So time ranges lean on 부터…까지, while place ranges usually use 에서…까지. You'll still hear 집부터 학교까지, so it's not wrong — just know that 에서…까지 is the more common "place-to-place" frame. The full location particle 에서 gets its own chapter; for now just remember: time → 부터, place → often 에서, and 까지 marks the end either way.`},pronunciation:"까지 starts with the tense consonant ㄲ, so keep it crisp — [kka-ji], not a soft [ga-ji]. After a 받침 like ㅂ/ㄱ/ㄷ, 부터 tenses a little: 집부터 sounds like [집뿌터].",drill:{instruction:'Make a "from … to …" sentence with 부터 and 까지, following the model.',model:"(아침 / 저녁) → 아침부터 저녁까지 일해요.",items:["(한 시 / 세 시) → ______ 한국어를 공부해요.","(여기 / 집) → ______ 걸어요.","(월요일 / 금요일) → ______ 학교에 가요."]},englishSpeakerPitfall:{wrong:"아홉 시까지 여섯 시부터 일해요. / 집까지 학교부터 멀어요.",right:"아홉 시부터 여섯 시까지 일해요. / 집부터 학교까지 멀어요.",explanation:'English says "from … to …," and learners often reach for 까지 first or swap the two particles. Tie each particle to its meaning, not to word order: 부터 always sits on the START point and 까지 always sits on the END point.'}},{title:"V아/어 주세요 — asking someone to do something for you",func:'V아/어 주세요 is the polite way to ask someone to do something for you: "please (do) … (for me)." Take the verb stem, add 아/어 by vowel harmony, then attach 주세요. It powers the survival phrases you need in class and out on the street — 다시 말해 주세요 (please say it again), 천천히 말해 주세요 (please speak slowly).',formTable:[{when:"Stem's last vowel is ㅏ or ㅗ (bright)",add:"아 주세요",ex:"받다 → 받아 주세요 · 보다 → 봐 주세요"},{when:"Stem's last vowel is anything else (not ㅏ/ㅗ)",add:"어 주세요",ex:"읽다 → 읽어 주세요 · 만들다 → 만들어 주세요"},{when:"하다 verbs",add:"해 주세요",ex:"말하다 → 말해 주세요 · 일하다 → 일해 주세요"},{when:"With a 'help me' adverb (다시, 천천히)",add:"adverb + V아/어 주세요",ex:"다시 → 다시 말해 주세요 · 천천히 → 천천히 써 주세요"}],examples:[{ko:"다시 말해 주세요.",romanization:"da-si mal-hae ju-se-yo.",en:"Please say that again.",note:`말하다 is a 하다 verb → 말해. With 다시 ("again") it's the #1 classroom phrase.`},{ko:"천천히 말해 주세요.",romanization:"cheon-cheon-hi mal-hae ju-se-yo.",en:"Please speak slowly.",note:'천천히 ("slowly") + 말해 주세요 — use it when someone talks too fast for you.'},{ko:"물 좀 주세요.",romanization:"mul jom ju-se-yo.",en:"Please give me some water.",note:'With a plain noun, use 주세요 directly (no 아/어). 좀 softens it to "please / if you would."'},{ko:"이 책을 읽어 주세요.",romanization:"i chae-geul il-geo ju-se-yo.",en:"Please read this book (to me).",note:`읽다's last vowel isn't ㅏ/ㅗ → 읽어 주세요. The 주세요 adds the "for me" nuance.`}],keyPoint:{label:"V아/어 주세요 vs N 주세요",body:`Plain 주세요 (from 주다, "to give") means "please give me ___" and attaches straight to a noun: 물 주세요, 책 주세요. But when you want someone to DO something for you, a bare noun won't carry it — you put the verb in the 아/어 form first: 책을 읽어 주세요 (please read the book for me). So: a thing you want handed over → N 주세요; an action you want done → V아/어 주세요. The deeper 주다 "do-it-for-me" grammar comes later; for now treat V아/어 주세요 as one fixed request phrase.`},pronunciation:"In 말해 주세요 the ㄹ links into 해 — [마래 주세요]. In 읽어 주세요 the hidden ㄱ of 읽 carries onto 어 — [일거 주세요]. Keep 주세요 light and even, don't stress it.",drill:{instruction:"Turn each verb into a polite request with V아/어 주세요, following the model.",model:"(말하다 + 다시) → 다시 말해 주세요.",items:["(보다 + 다시) → ______","(말하다 + 천천히) → ______","(쓰다) → 이름을 ______ (쓰다 drops 으: 써 주세요)"]},englishSpeakerPitfall:{wrong:'다시 말하 주세요 / 천천히 말하세요 (meaning "please say it again for me")',right:"다시 말해 주세요 / 천천히 말해 주세요",explanation:`Two traps. First, you have to conjugate to the 아/어 form before 주세요 — it's 말해 주세요, never the bare stem 말하 주세요. Second, plain 말하세요 is a polite command ("speak") with no "for me" warmth; adding 주세요 turns the order into a real request — exactly what you want when asking a teacher or a stranger for help.`}}],d=[{title:"-아서/어서 — because / so (reason and result)",func:"Use -아서/어서 to link a reason to its result in one sentence: the first clause is the cause, the second is what follows from it. It's the everyday way to say 'because' or 'so' when two ideas are naturally connected.",formTable:[{when:"Verb/Adj stem with ㅏ or ㅗ as last vowel",add:"-아서",ex:"가다 → 가서, 좋다 → 좋아서"},{when:"Stem with any other last vowel",add:"-어서",ex:"먹다 → 먹어서, 읽다 → 읽어서"},{when:"하다 verbs/adjectives",add:"해서",ex:"공부하다 → 공부해서, 피곤하다 → 피곤해서"},{when:"이다 (to be): after 받침 / after vowel",add:"-이라서 / -라서",ex:"학생이다 → 학생이라서, 친구다 → 친구라서"}],examples:[{ko:"배가 고파서 밥을 먹었어요.",romanization:"bae-ga go-pa-seo bap-eul meo-geo-sseo-yo.",en:"I was hungry, so I ate.",note:"고프다 (ㅡ drops) → 고파서; the reason (hungry) leads to the result (ate)."},{ko:"시간이 없어서 영화를 못 봤어요.",romanization:"si-ga-ni eop-seo-seo yeong-hwa-reul mot bwa-sseo-yo.",en:"I didn't have time, so I couldn't see the movie.",note:"없다 → 없어서; the past tense sits only on the last verb (봤어요), never on -어서."},{ko:"친구를 만나서 정말 반가웠어요.",romanization:"chin-gu-reul man-na-seo jeong-mal ban-ga-wo-sseo-yo.",en:"I met my friend, so I was really glad.",note:"만나다 → 만나서; with -아서/어서, meeting comes first and the good feeling follows from it."},{ko:"한국어가 어려워서 매일 공부해요.",romanization:"han-gu-geo-ga eo-ryeo-wo-seo mae-il gong-bu-hae-yo.",en:"Korean is hard, so I study every day.",note:"어렵다 (ㅂ irregular → 워) → 어려워서; an adjective gives the reason for an ongoing action."}],keyPoint:{label:"-아서/어서 vs -(으)니까",body:"Both mean 'because,' but you can't end an -아서/어서 sentence with a command or a suggestion. For 'Let's…' or 'Please…,' switch to -(으)니까: 피곤하니까 쉬세요 (You're tired, so rest), not 피곤해서 쉬세요. Also, -아서/어서 never carries past tense itself — say 늦어서 미안해요, not 늦었어서. The full -(으)니까 contrast comes later; for now just remember these two limits."},pronunciation:"In 좋아서 the ㅎ is silent and the sounds link smoothly: [조아서]. Same with 많아서 → [마나서].",drill:{instruction:"Combine each pair into one sentence using -아서/어서.",model:"비가 오다 / 집에 있었어요 → 비가 와서 집에 있었어요. (It rained, so I stayed home.)",items:["머리가 아프다 / 학교에 안 갔어요 →","돈이 없다 / 책을 못 샀어요 →","날씨가 좋다 / 기분이 좋아요 →"]},englishSpeakerPitfall:{wrong:"늦었어서 미안해요.",right:"늦어서 미안해요.",explanation:"English puts 'was' in the reason clause ('because I WAS late'), so learners add 었 before -어서. In Korean the tense lives only on the final verb; -아서/어서 always attaches to the plain stem, no matter when it happened."}},{title:"-고 / -(으)면 / -(으)ㄹ게요 — and, if/when, I'll (a promise)",func:"Three small connectors for joining ideas: -고 lists or sequences two clauses ('and'), -(으)면 sets up a condition ('if/when'), and -(으)ㄹ게요 makes a promise about what the speaker will do.",formTable:[{when:"-고: any verb/adj stem (nothing changes)",add:"-고",ex:"먹다 → 먹고, 좋다 → 좋고"},{when:"-(으)면 after stem WITH 받침",add:"-으면",ex:"먹다 → 먹으면, 읽다 → 읽으면"},{when:"-(으)면 after stem WITHOUT 받침 (or ㄹ 받침)",add:"-면",ex:"가다 → 가면, 만들다 → 만들면"},{when:"-(으)ㄹ게요 after stem WITH 받침",add:"-을게요",ex:"먹다 → 먹을게요, 읽다 → 읽을게요"},{when:"-(으)ㄹ게요 after stem WITHOUT 받침 (or ㄹ)",add:"-ㄹ게요",ex:"가다 → 갈게요, 만들다 → 만들게요"}],examples:[{ko:"밥을 먹고 학교에 가요.",romanization:"bap-eul meok-go hak-gyo-e ga-yo.",en:"I eat and (then) go to school.",note:"먹다 → 먹고; here -고 links two actions in order, 'do A and then B.'"},{ko:"시간이 있으면 영화를 봐요.",romanization:"si-ga-ni i-sseu-myeon yeong-hwa-reul bwa-yo.",en:"If/when I have time, I watch a movie.",note:"있다 (받침) → 있으면; -(으)면 states the condition before the result."},{ko:"집에 가면 전화할게요.",romanization:"ji-be ga-myeon jeon-hwa-hal-ge-yo.",en:"When I get home, I'll call you.",note:"가다 (no 받침) → 가면; 하다 → 할게요, a promise the speaker makes to the listener."},{ko:"제가 물 사 올게요.",romanization:"je-ga mul sa ol-ge-yo.",en:"I'll go get the water (for us).",note:"오다 → 올게요; -(으)ㄹ게요 is first-person only — the speaker is committing to do it."}],keyPoint:{label:"-(으)ㄹ게요 vs -(으)ㄹ 거예요",body:"-(으)ㄹ게요 is a promise made to whoever's listening — used only with 'I/we': 제가 할게요 (I'll do it, count on me). -(으)ㄹ 거예요 is a neutral prediction or plan and can take any subject: 내일 비가 올 거예요 (It'll rain tomorrow). You can't say 비가 올게요 — rain can't make a promise. The deeper future grammar comes later; for now, promise vs. prediction is the key split."},pronunciation:"-(으)ㄹ게요 is spelled with ㄱ but pronounced tense: 갈게요 → [갈께요], 먹을게요 → [머글께요].",drill:{instruction:"Fill each blank with -고, -(으)면, or -(으)ㄹ게요 as the meaning requires.",model:"손을 씻___ 밥을 먹어요. → 손을 씻고 밥을 먹어요. (I wash my hands and eat.)",items:["내일 날씨가 좋___ 공원에 가요. (if it's nice) →","제가 나중에 다시 전화___. (I'll call again) →","책을 읽___ 자요. (read and then sleep) →"]},englishSpeakerPitfall:{wrong:"내일 비가 올게요.",right:"내일 비가 올 거예요.",explanation:"English uses 'will' for both promises and predictions, so learners reach for -(으)ㄹ게요 everywhere. But -(으)ㄹ게요 is a personal promise and needs an 'I/we' subject who can actually commit. For forecasts or anything in the third person, use -(으)ㄹ 거예요 instead."}}],u=[{title:"-는 것 같다 — soft opinions and impressions",func:"Use -는 것 같다 to say 'it seems / I think / probably' instead of stating something as a flat fact. It softens your opinion so you sound less blunt and more polite, even when you're fairly sure.",formTable:[{when:"Action verb, present (happening now)",add:"verb stem + 는 것 같다",ex:"오다 → 오는 것 같다 (seems to be coming); 먹다 → 먹는 것 같다"},{when:"Adjective, present (vowel-ending stem)",add:"stem + ㄴ 것 같다",ex:"비싸다 → 비싼 것 같다 (seems expensive); 크다 → 큰 것 같다"},{when:"Adjective, present (받침-ending stem)",add:"stem + 은 것 같다",ex:"작다 → 작은 것 같다 (seems small); 좋다 → 좋은 것 같다"},{when:"Verb, past",add:"stem + (으)ㄴ 것 같다",ex:"가다 → 간 것 같다 (seems to have gone); 먹다 → 먹은 것 같다"},{when:"Future / guess",add:"stem + (으)ㄹ 것 같다",ex:"오다 → 올 것 같다 (will probably come); 없다 → 없을 것 같다"},{when:"Noun",add:"noun + 인 것 같다",ex:"학생 → 학생인 것 같다 (seems to be a student)"}],examples:[{ko:"지금 밖에 비가 오는 것 같아요.",romanization:"jigeum bakke biga oneun geot gatayo.",en:"It seems to be raining outside right now.",note:"Action verb, present: 오는 것 같다, because the rain is happening now."},{ko:"이 책은 좀 어려운 것 같아요.",romanization:"i chaegeun jom eoryeoun geot gatayo.",en:"This book seems a bit hard.",note:"Adjective 어렵다 (받침, ㅂ-irregular) → 어려운 것 같다; softer than just 어려워요."},{ko:"친구가 벌써 집에 간 것 같아요.",romanization:"chinguga beolsseo jibe gan geot gatayo.",en:"It seems my friend already went home.",note:"Past guess: 가다 → 간 것 같다 for something that already happened."},{ko:"내일은 시간이 없을 것 같아요.",romanization:"naeireun sigani eopseul geot gatayo.",en:"I probably won't have time tomorrow.",note:"Future/guess: 없다 → 없을 것 같다; a gentle, indirect way to say no."}],keyPoint:{label:"present 는 것 같다 vs future 을 것 같다",body:"Use -는 것 같다 for something you can sense right now (비가 오는 것 같아요 — I can hear/see it). Use -(으)ㄹ 것 같다 for a guess about the future or when you have no direct evidence yet (비가 올 것 같아요 — the sky looks like it). For the past, use -(으)ㄴ 것 같다 (간 것 같아요). Don't worry about every irregular form yet — just get the present/past/future split right."},pronunciation:"것 같다 sounds like [걷 깓따]: 것 ends in a [t], which tenses the next ㄱ so 같 comes out as [깓]. In casual speech it often blurs to [거 같아요].",drill:{instruction:"Soften each blunt statement into a -는 것 같다 impression. Watch the tense.",model:"이 영화 재미있어요. → 이 영화 재미있는 것 같아요.",items:["그 식당 비싸요. → ____ (adjective, present)","친구가 아까 밥을 먹었어요. → ____ (past guess)","내일 날씨가 추워요. → ____ (future guess)"]},englishSpeakerPitfall:{wrong:"나는 이 책이 어려운 것 같다고 생각해요.",right:"이 책은 어려운 것 같아요.",explanation:"English speakers tack a separate '나는 ~ 생각해요' (I think) onto -는 것 같다, but -는 것 같다 already means 'I think / it seems,' so you'd be saying it twice. Also, 것 같다 changes with tense (present 어려운, past 어려웠던, future 어려울) — English 'seems' stays the same, Korean doesn't."}},{title:"-잖아(요) vs -거든(요) — shared info vs new info",func:"Both end a sentence to give a reason or background, but they point in opposite directions. -잖아(요) reminds the listener of something you BOTH already know ('you know...', 'remember?'). -거든(요) gives information that's NEW to the listener, often the reason behind what you just said.",formTable:[{when:"-잖아요 after a verb/adjective stem (present)",add:"stem + 잖아요",ex:"있다 → 있잖아요; 바쁘다 → 바쁘잖아요 (you know I'm busy)"},{when:"-잖아요 after past",add:"stem + 았/었/했 + 잖아요",ex:"가다 → 갔잖아요 (we did go, remember); 먹다 → 먹었잖아요"},{when:"-잖아요 after a noun",add:"noun + (이)잖아요",ex:"학생 → 학생이잖아요; 친구 → 친구잖아요"},{when:"-거든요 after a verb/adjective stem (present)",add:"stem + 거든요",ex:"바쁘다 → 바쁘거든요 (the thing is, I'm busy); 좋다 → 좋거든요"},{when:"-거든요 after past",add:"stem + 았/었/했 + 거든요",ex:"가다 → 갔거든요 (the thing is, I went); 먹다 → 먹었거든요"},{when:"-거든요 after a noun",add:"noun + (이)거든요",ex:"학생 → 학생이거든요; 친구 → 친구거든요"}],examples:[{ko:"빨리 가요. 우리 시간 없잖아요.",romanization:"ppalli gayo. uri sigan eopjanayo.",en:"Let's hurry. We don't have time, you know.",note:"-잖아요: the listener already knows time is short; you're reminding them."},{ko:"어제 그 영화 같이 봤잖아요. 진짜 재미있었어요.",romanization:"eoje geu yeonghwa gachi bwatjanayo. jinjja jaemiisseosseoyo.",en:"We watched that movie together yesterday, remember? It was really fun.",note:"-잖아요 over a shared memory ('remember?')."},{ko:"A: 왜 안 와요? B: 지금 일이 많거든요.",romanization:"A: wae an wayo? B: jigeum iri mankeodeunyo.",en:"A: Why aren't you coming? B: The thing is, I've got a lot of work right now.",note:"-거든요: B's workload is NEW info that answers A's question."},{ko:"요즘 한국어를 공부해요. 다음 달에 한국에 가거든요.",romanization:"yojeum hangugeoreul gongbuhaeyo. daeum dare hanguge gageodeunyo.",en:"I'm studying Korean these days. It's because I'm going to Korea next month.",note:"-거든요 gives the new reason behind the first sentence."}],keyPoint:{label:"-잖아요 (you know) vs -거든요 (the thing is)",body:"Ask yourself: does the listener already know this? If YES, use -잖아요 ('you know...', 'remember?'). If NO and you're telling them for the first time, use -거든요 ('the thing is...', 'because...'). Using -잖아요 for brand-new info can sound like you're scolding them for not already knowing."},pronunciation:"-잖아요 is pronounced [자나요]: 잖 has a silent ㅎ in its 받침, so it just links smoothly into 아요. -거든요 is simply [거든뇨], with the final 요 tucked on — no special change.",drill:{instruction:"Choose -잖아요 (shared knowledge) or -거든요 (new info) and finish the sentence.",model:"(reminding a friend you both know it's closed today) 오늘 문 닫았잖아요.",items:["(reminding: we both know she's busy) 민수 씨한테 부탁하지 마세요. 그 사람 요즘 ____ .","(new reason why you can't eat it) 저는 그거 안 먹어요. 제가 채식주의자____ .","(reminding: we already paid) 또 돈 내요? 우리 아까 ____ ."]},englishSpeakerPitfall:{wrong:"저 지금 못 가요. 일이 많잖아요.",right:"저 지금 못 가요. 일이 많거든요.",explanation:"English uses one phrase, 'because / you see,' for both situations, so learners reach for -잖아요 every time. But if the listener doesn't already know your reason, -잖아요 wrongly implies 'as you obviously know,' which sounds blaming. For information you're sharing for the first time, you need -거든요."}}],m=[{title:"-(ㄴ/는)다고 하다 — Reporting What Someone Said",func:'Use this to report what someone said: "He says/said that …". Put the original verb or adjective into its plain (해라체) form and add -고 하다. It works for both "says" and "said" — 했어요 makes it past.',formTable:[{when:"Action verb, stem ends in a vowel",add:"-ㄴ다고 하다",ex:"가다 → 간다고 하다 (says he goes)"},{when:"Action verb, stem ends in a consonant (받침)",add:"-는다고 하다",ex:"먹다 → 먹는다고 하다 (says he eats)"},{when:"Adjective (descriptive verb)",add:"-다고 하다",ex:"바쁘다 → 바쁘다고 하다 / 좋다 → 좋다고 하다"},{when:"이다 (noun + be)",add:"-(이)라고 하다",ex:"학생이다 → 학생이라고 하다 / 친구다 → 친구라고 하다"},{when:"Past tense (any verb/adj)",add:"-았/었다고 하다",ex:"먹었다 → 먹었다고 하다 / 갔다 → 갔다고 하다"}],examples:[{ko:"친구가 내일 학교에 간다고 했어요.",romanization:"chin-gu-ga nae-il hak-gyo-e gan-da-go hae-sseo-yo.",en:"My friend said she's going to school tomorrow.",note:"가다 is a vowel-stem action verb, so it takes -ㄴ다고."},{ko:"동생이 지금 밥 먹는다고 해요.",romanization:"dong-saeng-i ji-geum bap meong-neun-da-go hae-yo.",en:"My little brother says he's eating now.",note:"먹다 has 받침, so the action-verb form is -는다고. 밥 먹다 ('eat a meal') is the everyday way to say it."},{ko:"친구가 요즘 너무 바쁘다고 했어요.",romanization:"chin-gu-ga yo-jeum neo-mu ba-ppeu-da-go hae-sseo-yo.",en:"My friend said she's really busy these days.",note:"바쁘다 is an adjective, so it stays -다고 (no ㄴ/는)."},{ko:"그 사람이 한국어 선생님이라고 했어요.",romanization:"geu sa-ra-mi han-gu-geo seon-saeng-ni-mi-ra-go hae-sseo-yo.",en:"He said he's a Korean teacher.",note:"With a noun + 이다 you use -이라고, not -다고."}],keyPoint:{label:"Adjectives keep -다고; action verbs split into -ㄴ다고 / -는다고",body:"This is the one spot learners mix up. Action verbs (먹다, 가다) become 먹는다고/간다고, but adjectives (좋다, 바쁘다) and 있다/없다 just take -다고: 좋다고, 바쁘다고, 재미있다고. So 'It's fun' → 재미있다고 했어요, never 재미있는다고. (Why 있다 acts like an adjective here comes later — for now, just memorize 있다고.)"},pronunciation:"In 먹는다고, the ㄱ before ㄴ nasalizes: [멍는다고]. 간다고 is said smoothly with no pause before 고.",drill:{instruction:'Report each sentence using -(ㄴ/는)다고 했어요 ("He/She said …"). Watch whether the word is an action verb or an adjective.',model:'친구: "나 집에 가." → 친구가 집에 간다고 했어요.',items:['동생: "나 책 읽어." → 동생이 책을 ____ 했어요.','친구: "날씨가 좋아." → 친구가 날씨가 ____ 했어요.','선생님: "이건 한국 영화예요." → 선생님이 이건 한국 영화 ____ 했어요.']},englishSpeakerPitfall:{wrong:"친구가 바쁘는다고 했어요. / 그 사람이 학생다고 했어요.",right:"친구가 바쁘다고 했어요. / 그 사람이 학생이라고 했어요.",explanation:"English uses one pattern ('says that…') for everything, so learners over-apply -는다고. But -ㄴ다/-는다 belongs ONLY to action verbs. Adjectives take plain -다고 (바쁘다고), and nouns take -(이)라고 (학생이라고). Match the form to the word type, not to English."}},{title:"-냐고 하다 — Reporting a Question",func:`Use this to report a question someone asked: "He asked whether/what …". Change the original question's ending to the plain question form -냐 and add -고 하다 — though in real speech people usually say 물어보다 ('ask') instead of 하다.`,formTable:[{when:"Action verb",add:"-냐고 하다 / 물어보다",ex:"가다 → 가냐고 / 먹다 → 먹냐고"},{when:"Adjective (descriptive verb)",add:"-냐고 하다 / 물어보다",ex:"바쁘다 → 바쁘냐고 / 좋다 → 좋냐고"},{when:"이다 (noun + be)",add:"-(이)냐고 하다",ex:"학생이다 → 학생이냐고 / 친구다 → 친구냐고"},{when:"있다/없다",add:"-냐고 하다",ex:"있다 → 있냐고 / 없다 → 없냐고"},{when:"Past tense (any verb/adj)",add:"-았/었냐고 하다",ex:"먹었다 → 먹었냐고 / 갔다 → 갔냐고"}],examples:[{ko:"친구가 내일 시간 있냐고 물어봤어요.",romanization:"chin-gu-ga nae-il si-gan in-nya-go mu-reo-bwa-sseo-yo.",en:"My friend asked if I had time tomorrow.",note:"있다 → 있냐고; 물어봤어요 is the natural everyday verb for 'asked'."},{ko:"동생이 밥 먹었냐고 했어요.",romanization:"dong-saeng-i bap meo-geon-nya-go hae-sseo-yo.",en:"My little brother asked whether I'd eaten.",note:"Past question: 먹었다 → 먹었냐고."},{ko:"친구가 그 영화 재미있냐고 물어봤어요.",romanization:"chin-gu-ga geu yeong-hwa jae-mi-in-nya-go mu-reo-bwa-sseo-yo.",en:"My friend asked whether that movie is fun.",note:"The adjective 재미있다 also just takes -냐고 in everyday speech."},{ko:"선생님이 누가 학생이냐고 물어봤어요.",romanization:"seon-saeng-ni-mi nu-ga hak-saeng-i-nya-go mu-reo-bwa-sseo-yo.",en:"The teacher asked who the student was.",note:"Noun + 이다 → 이냐고; the question word 누가 just stays in place."}],keyPoint:{label:"Statement -다고 vs. question -냐고",body:"Both report someone's words, but the ending tells you which: a reported statement ends in -다고 (간다고 했어요 = 'said he's going'), and a reported question ends in -냐고 (가냐고 했어요 = 'asked if he's going'). Yes/no and wh-questions use the same -냐고; the question word (언제, 누가, 뭐) just stays inside the clause."},pronunciation:"있냐고 and 먹었냐고 nasalize across the boundary: [인냐고], [머건냐고] — the ㅆ/ㄱ before ㄴ becomes [ㄴ].",drill:{instruction:'Report each question using -냐고 물어봤어요 ("… asked if/what …"). Keep any question word in place.',model:'친구: "시간 있어?" → 친구가 시간 있냐고 물어봤어요.',items:['동생: "지금 어디야?" → 동생이 지금 ____ 물어봤어요.','친구: "이 책 재미있어?" → 친구가 이 책 ____ 물어봤어요.','선생님: "숙제 했어요?" → 선생님이 숙제 ____ 물어봤어요.']},englishSpeakerPitfall:{wrong:"친구가 시간 있다고 물어봤어요.",right:"친구가 시간 있냐고 물어봤어요.",explanation:"English reports statements and questions almost the same way ('said that…' / 'asked if…'), so learners reuse -다고 for questions too. But a reported QUESTION must end in -냐고: 가냐고 / 있냐고 / 먹었냐고. If the original had a question mark, use -냐고, not -다고."}}],c=[{title:"-기로 하다 — deciding / agreeing to do something",func:"Use -기로 하다 to say you've decided or agreed to do something. The verb stem + 기로 names the action and 하다 marks the act of deciding. It's usually in the past (-기로 했어요) because the decision is already made.",formTable:[{when:"Any verb (받침 or no 받침)",add:"verb stem + 기로 하다 (no harmony, no stem change)",ex:"가다 → 가기로 하다, 먹다 → 먹기로 하다"},{when:"Reporting a decision you've made (most common)",add:"verb stem + 기로 했어요",ex:"운동하다 → 운동하기로 했어요, 읽다 → 읽기로 했어요"},{when:"Agreeing with someone",add:"…하고 + verb stem + 기로 했어요",ex:"친구하고 만나기로 했어요"},{when:"Deciding NOT to do something",add:"안 + verb + 기로 하다 / verb + 지 않기로 하다",ex:"안 먹기로 했어요, 먹지 않기로 했어요"}],examples:[{ko:"내일부터 매일 운동하기로 했어요.",romanization:"naeil-buteo maeil undonghagiro haesseoyo.",en:"I've decided to exercise every day from tomorrow.",note:"Past 했어요 because the decision is already settled."},{ko:"친구하고 주말에 영화 보기로 했어요.",romanization:"chinguhago jumare yeonghwa bogiro haesseoyo.",en:"My friend and I decided to watch a movie this weekend.",note:"With 친구하고 it sounds like a mutual plan, not a solo one."},{ko:"오늘부터 커피 안 마시기로 했어요.",romanization:"oneul-buteo keopi an masigiro haesseoyo.",en:"I've decided not to drink coffee from today.",note:"안 goes right before the verb for a 'decide not to' meaning."},{ko:"우리 내년에 같이 한국어 공부하기로 해요.",romanization:"uri naenyeone gachi hangugeo gongbuhagiro haeyo.",en:"Let's make a deal to study Korean together next year.",note:"Present 해요 turns it into a proposal rather than a report."}],keyPoint:{label:"-기로 했어요 vs -(으)ㄹ 거예요",body:"Both point to the future, but -기로 했어요 reports a decision that's now fixed ('I've decided to…'), while -(으)ㄹ 거예요 just states a plan or guess ('I'm going to…'). Use -기로 하다 when the point is that a choice was made — a promise to yourself or a deal with someone. (How the 했어요 past ending works is covered separately.)"},pronunciation:"",drill:{instruction:"Turn each plan into a decision using -기로 했어요.",model:"매일 운동하다 → 매일 운동하기로 했어요.",items:["일찍 자다 → ___","친구를 만나다 → ___","담배를 안 피우다 → ___"]},englishSpeakerPitfall:{wrong:"운동하는 것을 결정했어요.",right:"운동하기로 했어요.",explanation:"English speakers turn 'decided to' into 결정하다 plus a noun clause, which sounds heavy for everyday plans. Korean packs 'decide to do X' into the set phrase -기로 하다; keep 결정하다 for big, formal decisions."}},{title:`-(으)ㄹ까 봐 — doing something because you're worried ("in case / afraid that")`,func:"Use -(으)ㄹ까 봐 to give the worried 'what if' that's behind an action. It means 'because I'm afraid that…' or 'in case…', and the main clause says what you do to head that off.",formTable:[{when:"Verb/adjective stem ends in a vowel",add:"stem + ㄹ까 봐",ex:"자다 → 잘까 봐, 오다 → 올까 봐"},{when:"Verb/adjective stem ends in 받침",add:"stem + 을까 봐",ex:"늦다 → 늦을까 봐, 먹다 → 먹을까 봐"},{when:"ㄹ-final stem (drop ㄹ first)",add:"drop ㄹ, then + ㄹ까 봐",ex:"멀다 → 멀까 봐, 힘들다 → 힘들까 봐"},{when:"Worry about something that already happened",add:"past stem 았/었 + 을까 봐",ex:"갔다 → 갔을까 봐, 잊었다 → 잊었을까 봐"}],examples:[{ko:"비가 올까 봐 우산을 가져왔어요.",romanization:"biga olkka bwa usaneul gajyeowasseoyo.",en:"I brought an umbrella in case it rains.",note:"올까 봐 is the feared event; the main clause is the precaution."},{ko:"학교에 늦을까 봐 일찍 나왔어요.",romanization:"hakgyoe neujeulkka bwa iljjik nawasseoyo.",en:"I left early because I was afraid I'd be late for school.",note:"받침 stem 늦- takes 을까 봐."},{ko:"친구가 배고플까 봐 밥을 준비했어요.",romanization:"chinguga baegopeulkka bwa babeul junbihaesseoyo.",en:"I made some food in case my friend is hungry.",note:"The one you're worried about (친구) can be someone other than you."},{ko:"시험에서 틀릴까 봐 책을 다시 봤어요.",romanization:"siheomeseo teullilkka bwa chaegeul dasi bwasseoyo.",en:"I went over the book again because I was afraid I'd get things wrong on the test.",note:"틀리다 ('get wrong') ends in a vowel, so it takes ㄹ까 봐."}],keyPoint:{label:"-(으)ㄹ까 봐 vs -(으)니까",body:"Both give reasons, but -(으)니까 states a plain fact ('because it's raining'), while -(으)ㄹ까 봐 gives a worried 'what if' that hasn't happened ('in case it rains'). Use -(으)ㄹ까 봐 only when the reason is something you're afraid of or want to prevent, and don't put a command or suggestion in the main clause."},pronunciation:"-(으)ㄹ까 tenses the 까: 올까 sounds like [올까], 늦을까 like [느즐까] — the 까 is always a hard, tense sound.",drill:{instruction:"Add the worried reason with -(으)ㄹ까 봐.",model:"(비가 오다) 우산을 가져왔어요 → 비가 올까 봐 우산을 가져왔어요.",items:["(늦다) 택시를 탔어요 → ___","(친구가 못 먹다) 밥을 많이 만들었어요 → ___","(시험이 어렵다) 공부를 많이 했어요 → ___"]},englishSpeakerPitfall:{wrong:"비가 올까 봐 우산을 가져오세요.",right:"비가 올까 봐 우산을 가져왔어요.",explanation:"English 'in case it rains, bring an umbrella' makes you want to add a command, but -(으)ㄹ까 봐 can't be followed by an order or suggestion. The main clause has to say what someone actually does or did, not what they should do."}},{title:"-게 되다 — how something ended up happening (not by your own choice)",func:"Use -게 되다 to show a situation came about through circumstances rather than your own decision. It's the difference between 'I do X' and 'it ended up that I do X', usually because of outside events or other people.",formTable:[{when:"Any verb (받침 or no 받침)",add:"verb stem + 게 되다 (no stem change)",ex:"가다 → 가게 되다, 먹다 → 먹게 되다"},{when:"Saying how it turned out (most common)",add:"verb stem + 게 됐어요",ex:"살다 → 살게 됐어요, 알다 → 알게 됐어요"},{when:"A change that's now true",add:"verb stem + 게 됐어요 / 되었어요",ex:"잘하다 → 잘하게 됐어요"},{when:"Future: it'll end up that way",add:"verb stem + 게 될 거예요",ex:"만나다 → 만나게 될 거예요"}],examples:[{ko:"일 때문에 부산에서 살게 됐어요.",romanization:"il ttaemune busaneseo salge dwaesseoyo.",en:"I ended up living in Busan because of work.",note:"되다 shows the move came from circumstances, not free choice."},{ko:"한국 친구를 만나서 한국어를 잘하게 됐어요.",romanization:"hanguk chingureul mannaseo hangugeoreul jalhage dwaesseoyo.",en:"After I made a Korean friend, I got good at Korean.",note:"A gradual change in ability — a natural result, not a decision."},{ko:"그 영화를 우연히 보게 됐어요.",romanization:"geu yeonghwareul ujeonhi boge dwaesseoyo.",en:"I happened to end up watching that movie.",note:"우연히 ('by chance') goes well with 게 되다 for unplanned things."},{ko:"이제 그 이유를 알게 됐어요.",romanization:"ije geu iyureul alge dwaesseoyo.",en:"Now I've come to understand why.",note:"ㄹ-stem 알다 keeps its ㄹ before 게: 알게 됐어요."}],keyPoint:{label:"-게 되다 vs plain past",body:"Plain past (살았어요 'I lived') just states the fact. -게 됐어요 ('I ended up living') adds that it happened through circumstances or other people, not purely by your own plan. Reach for -게 되다 when you want to sound modest about a result or play down your own role in it."},pronunciation:"",drill:{instruction:"Say how it turned out using -게 됐어요.",model:"부산에서 살다 → 부산에서 살게 됐어요.",items:["그 사람을 좋아하다 → ___","한국 음식을 잘 먹다 → ___","그 사실을 알다 → ___"]},englishSpeakerPitfall:{wrong:"부산에서 살기로 됐어요. = exactly the same as 부산에서 살게 됐어요.",right:"부산에서 살게 됐어요. (circumstances led to it) / 부산에서 살기로 됐어요. (it was decided or arranged)",explanation:"Both forms are grammatical, but they frame the cause differently. -게 되다 presents a change or outcome that came about through circumstances. -기로 되다 presents a decision or arrangement, often one made jointly or by someone else. If YOU made the decision, 부산에서 살기로 했어요 is the clearest form."}}],g=[{title:"-는 척하다 — pretend / act like",func:"Use -는 척하다 to say someone pretends to do or be something — putting on an act that doesn't match reality. It marks behavior that's deliberately faked.",formTable:[{when:"Action verb, present (pretend to be doing now)",add:"-는 척하다",ex:"자다 → 자는 척하다 (pretend to be sleeping)"},{when:"Action verb, past (pretend to have done)",add:"-(으)ㄴ 척하다",ex:"먹다 → 먹은 척하다 / 보다 → 본 척하다"},{when:"Adjective (descriptive verb)",add:"-(으)ㄴ 척하다",ex:"괜찮다 → 괜찮은 척하다 / 아프다 → 아픈 척하다"},{when:"이다 (noun + be)",add:"-인 척하다",ex:"학생이다 → 학생인 척하다 (pretend to be a student)"}],examples:[{ko:"친구가 왔는데 자는 척했어요.",romanization:"chinguga wanneunde janeun cheokaesseoyo.",en:"My friend came over, but I pretended to be asleep.",note:"자다 is happening now → present -는 척하다."},{ko:"그 영화 안 봤는데 본 척했어요.",romanization:"geu yeonghwa an bwanneunde bon cheokaesseoyo.",en:"I hadn't seen that movie, but I pretended I had.",note:"보다 done before now → past -(으)ㄴ 척하다 (본)."},{ko:"사실 아픈데 괜찮은 척했어요.",romanization:"sasil apeunde gwaenchaneun cheokaesseoyo.",en:"I was actually sick, but I pretended I was fine.",note:"괜찮다 is an adjective → -(으)ㄴ 척하다 (괜찮은)."},{ko:"잘 모르면서 아는 척하지 마.",romanization:"jal moreumyeonseo aneun cheokaji ma.",en:"Don't act like you know when you don't.",note:"알다 is a ㄹ-verb, present sense → 아는 척 (ㄹ drops before -는)."}],keyPoint:{label:"-는 척하다 vs -(으)ㄴ 척하다",body:"The ending works just like a modifier (관형사형): an action happening now takes -는 (자는 척), a finished action takes -(으)ㄴ (먹은 척), and adjectives also take -(으)ㄴ (아픈 척). You can swap 척 for 체 with no change in meaning (자는 체하다), though 척 is more common in everyday speech."},pronunciation:"척했어요 sounds like [처캐써요] — ㄱ + ㅎ merge into the aspirated [ㅋ].",drill:{instruction:"Turn each cue into '(I) pretended to ~' using -는/-(으)ㄴ 척했어요.",model:"안 자다 / 자다 → 안 자는데 자는 척했어요.",items:["잘 모르다 / 알다 → 잘 모르는데 잘 ___ 척했어요.","안 먹다 / 먹다 → 밥을 안 먹었는데 ___ 척했어요.","아프다 / 괜찮다 → 아픈데 ___ 척했어요."]},englishSpeakerPitfall:{wrong:"괜찮는 척했어요.",right:"괜찮은 척했어요.",explanation:"English 'pretend to be fine' makes learners reach for -는, but 괜찮다 is an adjective, so it takes the adjective modifier -(으)ㄴ → 괜찮은 척. Only action verbs happening now take -는 척."}},{title:"-(으)ㄹ 뻔하다 — almost happened (a close call)",func:"Use -(으)ㄹ 뻔하다 to say something nearly happened but didn't — a near miss. It's almost always used in the past tense (-(으)ㄹ 뻔했어요) because the close call already happened.",formTable:[{when:"Verb stem ends in a vowel",add:"-ㄹ 뻔하다",ex:"넘어지다 → 넘어질 뻔하다 (almost fell)"},{when:"Verb stem ends in a consonant (받침)",add:"-을 뻔하다",ex:"죽다 → 죽을 뻔하다 / 늦다 → 늦을 뻔하다"},{when:"ㄹ-stem verb (ㄹ stays)",add:"-ㄹ 뻔하다",ex:"울다 → 울 뻔하다 (almost cried)"},{when:"Everyday use: always past tense",add:"-(으)ㄹ 뻔했다",ex:"잊어버리다 → 잊어버릴 뻔했어요 (I almost forgot)"}],examples:[{ko:"길에서 넘어질 뻔했어요.",romanization:"gireseo neomeojil ppeonhaesseoyo.",en:"I almost fell on the street.",note:"넘어지다 ends in a vowel → -ㄹ 뻔하다; past 뻔했어요."},{ko:"늦잠을 자서 학교에 늦을 뻔했어요.",romanization:"neutjameul jaseo hakgyoe neujeul ppeonhaesseoyo.",en:"I overslept and almost got to school late.",note:"늦다 ends in 받침 ㅈ → -을 뻔하다."},{ko:"그 얘기를 듣고 울 뻔했어요.",romanization:"geu yaegireul deutgo ul ppeonhaesseoyo.",en:"I almost cried when I heard that story.",note:"울다 is a ㄹ-stem; ㄹ stays before 뻔 → 울 뻔하다."},{ko:"물을 쏟아서 책이 젖을 뻔했어요.",romanization:"mureul ssodaseo chaegi jeojeul ppeonhaesseoyo.",en:"I spilled water and the book almost got wet.",note:"젖다 ends in 받침 → -을 뻔하다; the book didn't actually get wet."}],keyPoint:{label:"Always past tense, always 'didn't happen'",body:"-(으)ㄹ 뻔했다 means the event did NOT happen — it only came close. So 넘어질 뻔했어요 = 'I almost fell (but didn't).' Don't put the main verb in the past too: say 넘어질 뻔했어요, never 넘어졌을 뻔했어요."},pronunciation:"뻔했어요 sounds like [뻔해써요]; the opening ㅃ is a tense (fortis) sound — keep it hard, not a soft [ㅂ].",drill:{instruction:"Make a 'close call' sentence with -(으)ㄹ 뻔했어요.",model:"버스를 놓치다 → 버스를 놓칠 뻔했어요.",items:["약속을 잊어버리다 → 친구하고 약속을 ___ 뻔했어요.","물을 쏟다 → 컵을 건드려서 물을 ___ 뻔했어요.","넘어지다 → 계단에서 ___ 뻔했어요."]},englishSpeakerPitfall:{wrong:"넘어졌을 뻔했어요.",right:"넘어질 뻔했어요.",explanation:"English 'almost fell' is past, so learners put the main verb in the past too. But only 뻔하다 carries the past tense; the action verb stays in -(으)ㄹ form, because the fall never actually happened."}},{title:"-나 보다 / -(으)ㄴ가 보다 — guessing from evidence",func:"Use -나 보다 / -(으)ㄴ가 보다 to make a guess based on something you can see or hear, like English 'I guess...' or 'It seems...'. You're inferring about a situation rather than stating it as a fact.",formTable:[{when:"Action verb (present)",add:"-나 보다",ex:"오다 → 오나 보다 / 먹다 → 먹나 보다"},{when:"Any verb, past tense",add:"-았/었나 보다",ex:"가다 → 갔나 보다 / 자다 → 잤나 보다"},{when:"Adjective (descriptive verb)",add:"-(으)ㄴ가 보다",ex:"춥다 → 추운가 보다 / 바쁘다 → 바쁜가 보다"},{when:"이다 (noun + be)",add:"-인가 보다",ex:"학생이다 → 학생인가 보다 (guess: must be a student)"}],examples:[{ko:"사람들이 우산을 써요. 비가 오나 봐요.",romanization:"saramdeuri usaneul sseoyo. biga ona bwayo.",en:"People are using umbrellas. I guess it's raining.",note:"오다 is an action verb, present → -나 보다."},{ko:"친구가 전화를 안 받아요. 자나 봐요.",romanization:"chinguga jeonhwareul an badayo. jana bwayo.",en:"My friend isn't answering the phone. I guess they're sleeping.",note:"자다 action verb, present → 자나 봐요."},{ko:"불이 꺼져 있어요. 다들 집에 갔나 봐요.",romanization:"buri kkeojyeo isseoyo. dadeul jibe ganna bwayo.",en:"The lights are off. I guess everyone went home.",note:"Past inference → -았/었나 보다 (갔나)."},{ko:"다들 두꺼운 옷을 입었어요. 추운가 봐요.",romanization:"dadeul dukkeoun oseul ibeosseoyo. chuunga bwayo.",en:"Everyone's wearing thick clothes. I guess it's cold.",note:"춥다 is an adjective → -(으)ㄴ가 보다 (추운가, ㅂ-irregular)."}],keyPoint:{label:"-나 보다 vs -(으)ㄹ 것 같다",body:"-나 보다 means you're inferring from something you observed ('I see this, so I guess that'). -(으)ㄹ 것 같다 is a softer, more general guess or impression that needs no evidence. Use -나 보다 only when you're reasoning from a clue. (The fuller contrast lives in the conjecture chapter.)"},pronunciation:"봐요 sounds like [봐:요], a contraction of 보아요; keep it one syllable [bwa].",drill:{instruction:"Given the clue, finish the guess with -나 봐요 / -(으)ㄴ가 봐요.",model:"전화를 안 받아요. (자다) → 자나 봐요.",items:["음식이 금방 없어졌어요. (맛있다) → ___ 봐요.","친구가 계속 하품을 해요. (피곤하다) → ___ 봐요.","교실에 아무도 없어요. (수업이 끝나다) → 수업이 ___ 봐요."]},englishSpeakerPitfall:{wrong:"비가 오는가 봐요.",right:"비가 오나 봐요.",explanation:"Learners often attach -(으)ㄴ가 to everything, but action verbs (동사) in the present take -나 보다, while only adjectives and 이다 take -(으)ㄴ가 보다. So 오다 → 오나 봐요, but 춥다 → 추운가 봐요."}}],y=[{title:'-더니 — "and then (I noticed)…"',func:"Links two clauses where you personally saw or noticed situation X, and then Y followed — as a result or as a contrast. The first clause is something you observed (usually about someone or something else), not a plan of your own.",formTable:[{when:"After a verb or adjective stem",add:"-더니",ex:"먹다 → 먹더니 / 좋다 → 좋더니"},{when:"With a noun + 이다",add:"-(이)더니",ex:"학생이다 → 학생이더니 / 친구다 → 친구더니"},{when:"Your own past action → present result",add:"-았/었더니 (mostly with 나/저)",ex:"밥을 먹다 → 먹었더니 (배가 불러요)"}],examples:[{ko:"동생이 아까 울더니 지금은 자고 있어요.",romanization:"dongsaeng-i akka uldeoni jigeum-eun jago isseoyo.",en:"My little brother was crying a moment ago, and now he's sleeping.",note:"Plain -더니: I watched him cry, then a new state followed (contrast)."},{ko:"친구가 열심히 공부하더니 시험을 잘 봤어요.",romanization:"chingu-ga yeolsimhi gongbuhadeoni siheom-eul jal bwasseoyo.",en:"My friend studied hard, and (sure enough) did well on the test.",note:"X (effort I saw) leads to Y (result); the subject is someone else."},{ko:"아침에는 날씨가 좋더니 오후에 비가 왔어요.",romanization:"achim-eneun nalssi-ga jotdeoni ohu-e bi-ga wasseoyo.",en:"The weather was nice in the morning, and then it rained in the afternoon.",note:"-더니 with an adjective (좋다), showing a contrast between two times."},{ko:"밥을 많이 먹었더니 배가 너무 불러요.",romanization:"bap-eul mani meogeotdeoni bae-ga neomu bulleoyo.",en:"I ate a lot, so now I'm really full.",note:"-았/었더니 with a first-person subject: my own past action causing a present result."}],keyPoint:{label:"-더니 vs. -았/었더니",body:"Use plain -더니 when you noticed someone else's situation (친구가 공부하더니… = my friend studied, and then…). Use -았/었더니 when YOU did the action and report the result now (제가 먹었더니… = I ate, so now…). Why the past form attaches the way it does is a later topic — for now, just pair plain -더니 with 'someone else' and -았/었더니 with 'I'."},pronunciation:"좋더니 sounds like [조터니] — the ㅎ blends with the following ㄷ into an aspirated [ㅌ].",drill:{instruction:"Join the two facts into one sentence with -더니 (use -았/었더니 if the subject is 저/나).",model:"동생이 울다 / 지금 자다 → 동생이 울더니 지금 자요.",items:["친구가 열심히 운동하다 / 살이 빠지다 → ____","아침에 머리가 아프다 / 약을 먹고 괜찮아지다 → ____","제가 커피를 많이 마시다 / 잠이 안 오다 → ____ (use -았/었더니)"]},englishSpeakerPitfall:{wrong:"제가 학교에 가더니 친구를 만났어요.",right:"제가 학교에 갔더니 친구가 있었어요.",explanation:"English speakers stick plain -더니 onto their own actions like a simple 'and then.' But plain -더니 reports something you noticed about others; for your own finished action that leads to a result, you need the past form -았/었더니."}},{title:'-길래 — "since I saw…, I…"',func:"Gives the reason behind your own reaction or decision: because you noticed situation X, you did Y. The first clause is an outside trigger you observed; the second is your own spontaneous response.",formTable:[{when:"After a verb stem",add:"-길래",ex:"팔다 → 팔길래 / 보이다 → 보이길래"},{when:"After an adjective stem",add:"-길래",ex:"싸다 → 싸길래 / 맛있다 → 맛있길래"},{when:"After a noun + 이다",add:"-(이)길래",ex:"학생이다 → 학생이길래 / 친구다 → 친구(이)길래"}],examples:[{ko:"가게에서 과일이 싸길래 좀 많이 샀어요.",romanization:"gage-eseo gwail-i ssagillae jom mani sasseoyo.",en:"The fruit was cheap at the store, so I bought quite a lot.",note:"X (I noticed it was cheap) triggers my reaction Y (bought a lot)."},{ko:"친구가 배고파하길래 밥을 사 줬어요.",romanization:"chingu-ga baegopahagillae bap-eul sa jwosseoyo.",en:"My friend looked hungry, so I bought them a meal.",note:"The trigger is someone else's state; my reaction is the kind gesture."},{ko:"날씨가 좋길래 친구하고 산책했어요.",romanization:"nalssi-ga jotgillae chinguhago sanchaekaesseoyo.",en:"The weather was nice, so I went for a walk with a friend.",note:"-길래 with an adjective; the second clause must be the speaker's own action."},{ko:"책이 재미있길래 끝까지 다 읽었어요.",romanization:"chaeg-i jaemiitgillae kkeutkkaji da ilgeosseoyo.",en:"The book was fun, so I read it all the way to the end.",note:"Reason (the book was fun) → my resulting action (finished reading)."}],keyPoint:{label:"-길래 vs. -아서/-니까",body:"-아서 and -니까 give a plain reason for almost any clause, including requests and suggestions. -길래 is narrower: the reason is something you yourself noticed, and the result is your own (usually past) action — you can't say 비싸길래 사지 마세요. When telling someone else to do something, use -니까."},pronunciation:"맛있길래 sounds like [마싣낄래] — the ㄱ of 길 tenses to [ㄲ] after the preceding consonant.",drill:{instruction:"Make one sentence with -길래 (a reason you noticed + your own past reaction).",model:"과일이 싸다 / 많이 사다 → 과일이 싸길래 많이 샀어요.",items:["친구가 영화를 보고 싶어 하다 / 같이 가다 → ____","날씨가 덥다 / 아이스크림을 사다 → ____","길이 막히다 / 지하철을 타다 → ____"]},englishSpeakerPitfall:{wrong:"비가 오길래 우산을 가져가세요.",right:"비가 오니까 우산을 가져가세요.",explanation:"English 'since/because' works fine before a command, so learners attach -길래 to requests. But -길래 only leads into your own past action, never a command or suggestion. Switch to -니까 when you're telling someone else to do something."}},{title:'-는 바람에 — "because of (something unexpected)…"',func:"Gives a sudden, usually unwanted cause for a bad or unintended result. It signals that X threw things off and Y happened against your plans.",formTable:[{when:"After a verb stem",add:"-는 바람에",ex:"놓치다 → 놓치는 바람에 / 자다 → 자는 바람에"},{when:"Verb stem ending in ㄹ (ㄹ drops)",add:"-는 바람에",ex:"울다 → 우는 바람에 / 놀다 → 노는 바람에"},{when:"Adjectives — not used",add:"(use a verb instead)",ex:"비싸다 (X) → 값이 오르는 바람에 (O)"}],examples:[{ko:"늦잠을 자는 바람에 학교에 늦었어요.",romanization:"neutjam-eul janeun barame hakgyo-e neujeosseoyo.",en:"I overslept, so (unfortunately) I was late to school.",note:"Unexpected cause (oversleeping) → unwanted result (being late)."},{ko:"버스를 놓치는 바람에 약속에 늦었어요.",romanization:"beoseu-reul nochineun barame yaksok-e neujeosseoyo.",en:"I missed the bus, so I was late to meet up.",note:"Classic disruption pattern; the result is a setback."},{ko:"동생이 우는 바람에 잠을 못 잤어요.",romanization:"dongsaeng-i uneun barame jam-eul mot jasseoyo.",en:"My little brother kept crying, so I couldn't sleep.",note:"울다 → 우는: ㄹ drops before -는. The cause is someone else's action."},{ko:"비가 갑자기 오는 바람에 옷이 다 젖었어요.",romanization:"bi-ga gapjagi oneun barame os-i da jeojeosseoyo.",en:"It suddenly rained, so my clothes got all wet.",note:"갑자기 (suddenly) fits the 'unexpected disruption' feel of this form."}],keyPoint:{label:"-는 바람에 vs. -아서/-어서",body:"-아서/-어서 states a plain cause for any kind of result, good or bad. -는 바람에 is saved for an unexpected cause that leads to a bad or unplanned result, and the second clause is normally in the past tense. You wouldn't say 열심히 공부하는 바람에 시험을 잘 봤어요 — for a good result, use -아서/-어서."},pronunciation:"늦는 sounds like [는는] in fast speech — the ㅈ of 늦 becomes [ㄴ] before the ㄴ of 는.",drill:{instruction:"Join the two facts with -는 바람에 (unexpected cause → bad result, second clause in past tense).",model:"늦잠을 자다 / 학교에 늦다 → 늦잠을 자는 바람에 학교에 늦었어요.",items:["버스를 놓치다 / 회의에 늦다 → ____","휴대폰을 잃어버리다 / 친구한테 연락 못 하다 → ____","아이가 울다 / 통화를 못 하다 → ____"]},englishSpeakerPitfall:{wrong:"열심히 연습하는 바람에 시험에 합격했어요.",right:"열심히 연습한 덕분에 시험에 합격했어요.",explanation:"Learners use -는 바람에 for any cause, like a neutral 'because.' But -는 바람에 only fits an unexpected cause with a bad result. For a good result you brought about, use -아서/-어서 or -(은)ㄴ 덕분에 ('thanks to')."}},{title:"-(으)ㄹ수록 — the more …, the more …",func:'-(으)ㄹ수록 attaches to a verb or adjective stem to mean "the more X happens, the more Y." It links a rising cause to a rising result, and is often paired with 점점 ("more and more").',formTable:[{when:"Stem ends in a vowel",add:"-ㄹ수록",ex:"가다 → 갈수록 · 보다 → 볼수록"},{when:"Stem ends in a consonant (받침)",add:"-을수록",ex:"먹다 → 먹을수록 · 읽다 → 읽을수록"},{when:"Stem already ends in ㄹ",add:"+ 수록 (do not add 을 or another ㄹ)",ex:"살다 → 살수록 · 알다 → 알수록 · 길다 → 길수록"},{when:"Often doubled with the same verb + -(으)면",add:"V-(으)면 V-(으)ㄹ수록",ex:"보면 볼수록 · 알면 알수록"}],examples:[{ko:"한국어는 공부할수록 재미있어요.",romanization:"han-gu-geo-neun gong-bu-hal-su-rok jae-mi-i-sseo-yo.",en:"The more I study Korean, the more fun it is.",note:"공부하다 → 공부할수록 (vowel stem → ㄹ수록)."},{ko:"친구는 만날수록 좋아요.",romanization:"chin-gu-neun man-nal-su-rok jo-a-yo.",en:"The more I see my friend, the more I like them.",note:"만나다 → 만날수록."},{ko:"이 책은 읽을수록 어려워요.",romanization:"i chae-geun il-geul-su-rok eo-ryeo-wo-yo.",en:"The more I read this book, the harder it gets.",note:"읽다 → 읽을수록 (consonant stem → 을수록)."},{ko:"보면 볼수록 예뻐요.",romanization:"bo-myeon bol-su-rok ye-ppeo-yo.",en:"The more I look, the prettier it is.",note:"The doubled 보면 볼수록 frame is very common in speech."}],keyPoint:{label:"Pair it with 점점",body:'-(으)ㄹ수록 often comes with 점점 ("gradually, more and more") to stress the rising effect: 시간이 갈수록 점점 추워져요 ("as time goes on, it gets colder and colder"). The doubled V-(으)면 V-(으)ㄹ수록 form (알면 알수록) is a fixed, natural way to say "the more … the more."'},pronunciation:"읽을수록 is pronounced [일글쑤록]: the ㄱ links onto the following vowel and 수 tenses to [쑤].",drill:{instruction:'Make "the more …, the more …" sentences — follow the model.',model:"(공부하다 / 재미있다) → 공부할수록 재미있어요.",items:["(보다 / 예쁘다) → ______","(먹다 / 맛있다) → ______","(친구를 알다 / 좋다) → ______"]},englishSpeakerPitfall:{wrong:"공부하수록",right:"공부할수록",explanation:"Don't drop the (으)ㄹ. A vowel stem still needs the ㄹ (공부할수록), and a consonant stem needs 을 (먹을수록). It is never just stem + 수록."}},{title:"-기 위해서 — in order to / for the sake of",func:'-기 위해서 marks a purpose — the goal you do something for. Attach -기 위해서 to a verb stem ("in order to V"), or N을/를 위해서 to a noun ("for the sake of N"). The 서 is optional: 위해 = 위해서.',formTable:[{when:'Verb stem + 기 위해서 ("in order to V")',add:"-기 위해서",ex:"배우다 → 배우기 위해서 · 사다 → 사기 위해서"},{when:'Noun + 을/를 위해서 ("for N")',add:"을/를 위해서",ex:"건강 → 건강을 위해서 · 친구 → 친구를 위해서"},{when:"서 is optional",add:"위해 = 위해서",ex:"배우기 위해 / 배우기 위해서"}],examples:[{ko:"한국어를 배우기 위해서 한국에 왔어요.",romanization:"han-gu-geo-reul bae-u-gi wi-hae-seo han-gu-ge wa-sseo-yo.",en:"I came to Korea (in order) to learn Korean.",note:"배우다 → 배우기 위해서. The goal comes first, the action second."},{ko:"건강을 위해서 매일 운동해요.",romanization:"geon-gang-eul wi-hae-seo mae-il un-dong-hae-yo.",en:"I exercise every day for my health.",note:"Noun goal → 건강을 위해서."},{ko:"시험을 잘 보기 위해서 열심히 공부해요.",romanization:"si-heo-meul jal bo-gi wi-hae-seo yeol-sim-hi gong-bu-hae-yo.",en:"I study hard (in order) to do well on the exam.",note:"보다 → 보기 위해서."},{ko:"친구를 위해서 선물을 샀어요.",romanization:"chin-gu-reul wi-hae-seo seon-mu-reul sa-sseo-yo.",en:"I bought a gift for my friend.",note:'Noun + 를 위해서 = "for (the sake of)."'}],keyPoint:{label:"-기 위해서 vs -(으)러",body:'Both express purpose, but -(으)러 attaches only to a verb and only pairs with going/coming verbs (가다/오다): 밥 먹으러 가요 (I go to eat). -기 위해서 is broader — any verb, any main clause, and it can also take a noun goal (건강을 위해서). Use -(으)러 for "go/come to do," and -기 위해서 for any purpose.'},pronunciation:"",drill:{instruction:"State a purpose — follow the model.",model:"(한국어를 배우다 / 한국에 오다) → 한국어를 배우기 위해서 한국에 왔어요.",items:["(시험을 잘 보다 / 공부하다) → ______","(건강 / 운동하다) → ______","(친구 / 선물을 사다) → ______"]},englishSpeakerPitfall:{wrong:"배우 위해서",right:"배우기 위해서",explanation:"Don't forget the -기 that turns the verb into a noun-like form. It is verb-stem + 기 + 위해서 (배우기 위해서), never just verb + 위해서."}}],w=[{title:"V았/었어요 — the polite past tense",func:'Use V았/었어요 to say an action or state happened in the past. It is the polite, everyday way to answer questions like "What did you do yesterday?"',formTable:[{when:"Stem's last vowel is ㅏ or ㅗ",add:"-았어요",ex:"가다 → 갔어요, 보다 → 봤어요, 살다 → 살았어요"},{when:"Any other vowel (ㅓ, ㅜ, ㅣ, ㅡ, ㅔ …)",add:"-었어요",ex:"먹다 → 먹었어요, 마시다 → 마셨어요, 읽다 → 읽었어요"},{when:"하다 verbs",add:"하다 → 했어요",ex:"하다 → 했어요, 공부하다 → 공부했어요, 일하다 → 일했어요"}],examples:[{ko:"어제 친구를 만났어요.",romanization:"eoje chingu-reul mannasseoyo.",en:"I met a friend yesterday.",note:"만나다's stem 만나- ends in ㅏ, so -았 contracts: 만나 + 았 → 만났어요."},{ko:"아침에 밥을 먹었어요.",romanization:"achim-e bab-eul meogeosseoyo.",en:"I ate (a meal) in the morning.",note:"먹- has the vowel ㅓ, so it takes -었어요 (no contraction)."},{ko:"어제 집에서 한국어를 공부했어요.",romanization:"eoje jib-eseo hangugeo-reul gongbuhaesseoyo.",en:"I studied Korean at home yesterday.",note:"공부하다 is a 하다 verb, so 하다 → 했어요 → 공부했어요."},{ko:"주말에 영화를 봤어요.",romanization:"jumal-e yeonghwa-reul bwasseoyo.",en:"I watched a movie over the weekend.",note:"보다's stem 보- ends in ㅗ, so 보 + 았 → 봤어요."}],keyPoint:{label:"이다 → 였어요 / 이었어요",body:'The copula 이다 ("to be") has its own past form. After a vowel use 였어요 (친구이다 → 친구였어요), and after a final consonant use 이었어요 (학생이다 → 학생이었어요; 책이다 → 책이었어요). For now just memorize these two endings — the full ins and outs of 이다 come in its home chapter.'},pronunciation:"먹었어요 links across the boundary and sounds like [머거써요]; 했어요 sounds like [해써요] — the 어 is swallowed and the ㅆ is tense.",drill:{instruction:"Change each verb into the polite past form V았/었어요.",model:"마시다 (to drink) → 마셨어요",items:["읽다 (to read) → ____","오다 (to come) → ____","운동하다 (to exercise) → ____"]},englishSpeakerPitfall:{wrong:"어제 학교에 가요.",right:"어제 학교에 갔어요.",explanation:'English often leans on the time word ("yesterday") and leaves the verb in its plain form. In Korean the verb itself has to carry the past tense — adding 어제 (yesterday) does not make 가요 mean "went." You have to change 가요 to 갔어요.'}}],p=[{title:"V-(으)ㄹ 거예요 — saying what you'll do (plans, intentions, predictions)",func:`Use V-(으)ㄹ 거예요 to say what you plan or mean to do, or to guess what will happen. It's the everyday polite way to say "will" or "be going to" — perfect for weekend plans, what you'll eat, or what the weather will do.`,formTable:[{when:"Stem ends in a vowel",add:"stem + ㄹ 거예요",ex:"가다 → 갈 거예요, 보다 → 볼 거예요, 하다 → 할 거예요"},{when:"Stem ends in a consonant",add:"stem + 을 거예요",ex:"먹다 → 먹을 거예요, 읽다 → 읽을 거예요"},{when:"Stem already ends in ㄹ",add:"keep ㄹ, add 거예요 (don't add 을)",ex:"살다 → 살 거예요, 만들다 → 만들 거예요"}],examples:[{ko:"내일 친구를 만날 거예요.",romanization:"naeil chingureul mannal geoyeyo.",en:"I'm going to meet a friend tomorrow.",note:"만나다 ends in a vowel, so just add ㄹ 거예요. This is a plan."},{ko:"저녁에 집에서 밥 먹을 거예요.",romanization:"jeonyeoge jibeseo bap meogeul geoyeyo.",en:"I'm going to eat at home this evening.",note:"먹다 ends in a consonant, so add 을 거예요."},{ko:"주말에 영화 볼 거예요.",romanization:"jumare yeonghwa bol geoyeyo.",en:"I'm going to watch a movie this weekend.",note:"보다 → 볼 거예요. A simple plan with a friend-talk feel."},{ko:"내일은 비가 올 거예요.",romanization:"naeireun biga ol geoyeyo.",en:"It'll probably rain tomorrow.",note:"Here 오다 is a guess about the weather, not a personal plan — the same form covers both."}],keyPoint:{label:"거예요 (your plan) vs. 게요 (a promise to me)",body:"Both look to the future. -(으)ㄹ 거예요 just states your plan or a guess: 제가 할 거예요 (I plan to do it). -(으)ㄹ게요 is something you promise the listener right now: 제가 할게요 (I'll do it / I promise). Quick tell: weather and other people can take 거예요 (비가 올 거예요), but never 게요 — rain can't promise you anything. You'll practice 게요 more later; for now, default to 거예요 for plans and guesses."},pronunciation:"거예요 is said like [거에요]. The ㄹ before it makes the 거 tense, so 갈 거예요 sounds like [갈 꺼예요] and 먹을 거예요 like [머글 꺼예요].",drill:{instruction:"Turn each verb into a future-plan sentence with V-(으)ㄹ 거예요.",model:"보다 (영화를) → 영화를 볼 거예요.",items:["읽다 (책을) → ?","마시다 (물을) → ?","살다 (서울에서) → ?","듣다 (음악을) → ?"]},englishSpeakerPitfall:{wrong:"제가 갈 거 있어요. / 제가 갈게 거예요.",right:"제가 갈 거예요.",explanation:`Because "I'm going to go" feels like two verbs in English, learners try to bolt on an extra 있어요 or mix in 게. But -(으)ㄹ 거예요 is already a finished sentence ending. Just attach -(으)ㄹ 거예요 straight onto the stem — nothing comes after it.`}}],f=[{title:"Question words (누구, 뭐, 어디, 언제, 왜, 어떻게, 몇, 얼마)",func:"Question words ask for one missing piece of info — who, what, where, when, why, how, how many, how much. The big thing: in Korean the question word sits in the exact spot the answer would go. It does not jump to the front like English 'where' or 'what' does.",formTable:[{when:"who — 누구",add:"누구 + 가 → 누가 (subject); 누구 + 를 (object); 누구 + 예요",ex:"누가 와요? / 누구를 만나요? / 이 사람 누구예요?"},{when:"what — 뭐 (everyday)",add:"뭐 + 예요; 뭐 + 를 → 뭘 (object). 무엇 is the written form, rare in speech",ex:"이거 뭐예요? / 뭘 먹어요? / 뭐 해요?"},{when:"where — 어디",add:"어디 + 예요; 어디 + 에 (where you go / where something is); 어디 + 에서 (where you do something)",ex:"집이 어디예요? / 어디에 가요? / 어디에서 일해요?"},{when:"when / why / how — 언제, 왜, 어떻게",add:"no particle — they work like adverbs on their own",ex:"언제 와요? / 왜 안 와요? / 어떻게 가요?"},{when:"how many / how much — 몇 + counter, 얼마",add:"몇 + 개/명/시/살 …; 얼마 + 예요 (price)",ex:"몇 개예요? / 몇 시예요? / 이거 얼마예요?"}],examples:[{ko:"이 사람 누구예요?",romanization:"i saram nuguyeyo?",en:"Who is this person?",note:"누구 sits right where the answer goes: 제 친구예요 (It's my friend). Same slot, just swap the word."},{ko:"점심에 뭘 먹어요?",romanization:"jeomsime mwol meogeoyo?",en:"What do you eat for lunch?",note:"뭘 (뭐+를) stays in the object slot before the verb. Answer 밥을 먹어요 fills the very same slot."},{ko:"어디에서 일해요?",romanization:"eodieseo ilhaeyo?",en:"Where do you work?",note:"어디 takes 에서 because work happens there (an action). Answer 회사에서 일해요 keeps the same 에서."},{ko:"이거 얼마예요?",romanization:"igeo eolmayeyo?",en:"How much is this?",note:"얼마 is the normal word for asking a price. Answer 만 원이에요 drops right into the 얼마 spot."}],keyPoint:{label:"The question word stays where the answer goes",body:"English moves the question word up front: 'WHAT do you eat?' Korean leaves it in place, right before the verb: 뭐 먹어요? → 밥 먹어요. Look at the slot: 밥 먹어요 / 뭐 먹어요 — same spot, you just swap 밥 for 뭐. So think of the answer first, then drop the question word into its slot. (어디 still needs 에 or 에서 — that comes next.)"},pronunciation:"누구 + 가 squeezes down to 누가 (the 구 disappears, it doesn't just link). 뭐 + 를 squeezes to 뭘. 무엇을 links over the patchim and sounds like [무어슬].",drill:{instruction:"Turn each statement into a question. Swap the underlined answer for the matching question word and leave it in the same slot (keep the particle).",model:"친구를 만나요. → 누구를 만나요?",items:["학교에 가요. → ___에 가요?","물을 마셔요. → ___ 마셔요?","세 시에 와요. → ___ 와요?","회사에서 일해요. → ___에서 일해요?"]},englishSpeakerPitfall:{wrong:"먹어요 뭐? / 가요 어디?",right:"뭐 먹어요? / 어디 가요?",explanation:"From English, people want to swing the question word to the very front of the sentence (Where do you go?). In Korean it does not move up front and it never goes after the verb — it stays in the answer's slot, right before the verb. So it's 어디 가요?, not 가요 어디? and not 어디 가요 fronted away from its slot."}}],b=[{title:"Two number systems: native (하나·둘·셋) vs. Sino-Korean (일·이·삼)",func:"Korean has two full sets of numbers, and which one you use depends on what you're saying — not on which you like better. Native numbers count things, people, and the o'clock hour. Sino-Korean numbers handle money, minutes, dates, and phone numbers. The clock uses both at once: native for the hour, Sino for the minute.",formTable:[{when:"Counting things, people, or animals (with a counter)",add:"Native 하나·둘·셋·넷, but 1–4 shorten before a counter → 한·두·세·네",ex:"사과 한 개 (one apple), 친구 두 명 (two friends)"},{when:"Saying the o'clock hour (시)",add:"Native number + 시 (1–4 shorten here too)",ex:"세 시 (3 o'clock), 네 시 (4 o'clock)"},{when:"Minutes, money, dates, phone numbers",add:"Sino-Korean 일·이·삼·사",ex:"삼십 분 (30 minutes), 오천 원 (5,000 won)"},{when:"Age",add:"Native + 살 in daily talk; Sino + 세 on official forms",ex:"스무 살 (20 years old, everyday), 이십 세 (on forms)"}],examples:[{ko:"물 한 병 주세요.",romanization:"mul han byeong juseyo.",en:"One bottle of water, please.",note:"Counting a thing, so native — and 하나 shortens to 한 before the counter 병."},{ko:"지금 세 시 삼십 분이에요.",romanization:"jigeum se si samsip bun-ieyo.",en:"It's 3:30 now.",note:"The hour 시 takes native 세, but the minute 분 takes Sino 삼십 — both systems in one time."},{ko:"이 책 오천 원이에요.",romanization:"i chaek ocheon won-ieyo.",en:"This book is 5,000 won.",note:"Money is always Sino (오천), never 다섯천."},{ko:"우리 반에 학생이 열 명 있어요.",romanization:"uri ban-e haksaeng-i yeol myeong isseoyo.",en:"There are ten students in our class.",note:"Counting people with 명, so native 열 — and 열 keeps its shape; only 한·두·세·네 and 스무 change."}],keyPoint:{label:"The clock uses both systems",body:"The hour (시) is native: 한 시, 두 시, 세 시. The minute (분) is Sino: 일 분, 십 분, 삼십 분. So 3:20 is 세 시 이십 분 — native for the hour, Sino for the minute. If you can remember this one phrase, you've got the whole rule. (Which counter goes with which number is a later topic; for now just lock in hour vs. minute.)"},pronunciation:"여섯 개 sounds like [여섣 깨] and 일곱 시 like [일곱 씨] — the counter's first consonant tenses after the number's final consonant. Also remember the short forms before a counter: 하나→한, 둘→두, 셋→세, 넷→네, 스물→스무.",drill:{instruction:"Say each one out loud, picking the right number system and the right form before the counter.",model:"사과 3개 → 사과 세 개",items:["친구 2명 → ?","지금 1시 30분 → ?","커피 4,500원 → ?"]},englishSpeakerPitfall:{wrong:"지금 삼 시예요.",right:"지금 세 시예요.",explanation:"In English one set of numbers does everything, so it's tempting to grab the more familiar Sino 삼 for '3 o'clock.' But the hour is always native: 세 시. The flip side of the same habit is reaching for native 다섯 to say money (다섯천 원) instead of Sino 오천 원. Quick check before you speak: am I counting things or hours (native), or saying money, minutes, or a date (Sino)?"}}],k=[{title:"A-(으)ㄴ N — Adjectives describing a noun",func:"To put an adjective in front of a noun (a *pretty* bag, a *small* room), you can't use the plain dictionary form. You change the adjective into a modifying form with -(으)ㄴ and put it right before the noun.",formTable:[{when:"Adjective stem ends in a vowel",add:"+ ㄴ",ex:"예쁘다 → 예쁜 (가방)"},{when:"Adjective stem ends in a consonant",add:"+ 은",ex:"작다 → 작은 (집)"},{when:"ㄹ-final stem (drop the ㄹ)",add:"ㄹ drops, + ㄴ",ex:"길다 → 긴 (시간)"},{when:"있다/없다 type (맛있다, 재미있다)",add:"+ 는 (acts like a verb)",ex:"맛있다 → 맛있는 (밥)"}],examples:[{ko:"예쁜 가방이에요.",romanization:"yeppeun gabangieyo.",en:"It's a pretty bag.",note:"예쁘다 ends in a vowel, so just add ㄴ → 예쁜, right before 가방."},{ko:"작은 집에 살아요.",romanization:"jageun jibe sarayo.",en:"I live in a small house.",note:"작다 ends in a consonant, so add 은 → 작은. The adjective goes straight onto the noun — no 이/가."},{ko:"긴 시간 동안 기다렸어요.",romanization:"gin sigan dongan gidaryeosseoyo.",en:"I waited for a long time.",note:"길다 is a ㄹ-stem: the ㄹ drops and ㄴ is added → 긴, not 길은."},{ko:"맛있는 밥을 먹었어요.",romanization:"masinneun babeul meogeosseoyo.",en:"I ate a delicious meal.",note:"맛있다/맛없다 act like verbs, so they take 는, not 은 → 맛있는."}],keyPoint:{label:"예쁜 가방 vs 가방이 예뻐요",body:"Korean uses an adjective in two ways. Before a noun it has to become the modifier form (예쁜 가방 = 'a pretty bag'). At the end of a sentence it stays as the predicate (가방이 예뻐요 = 'The bag is pretty'). Same adjective, two jobs — don't put the plain 예뻐요 form in front of a noun."},pronunciation:"좋은 is said [조은] (joeun): the ㅎ drops out between vowels and the sound links straight into the next syllable. 작은 links the same way as [자근] (jageun).",drill:{instruction:"Turn the adjective in parentheses into the -(으)ㄴ modifier form and attach it to the noun.",model:"(크다) 가방 → 큰 가방",items:["(좋다) 친구 →","(예쁘다) 옷 →","(맛있다) 음식 →"]},englishSpeakerPitfall:{wrong:"비싸요 가방",right:"비싼 가방",explanation:"English leaves the adjective unchanged ('an expensive bag'), so learners reach for the sentence form 비싸요. But before a noun a Korean adjective needs the modifier ending: 비싸다 → 비싼 가방. The polite 비싸요 can only close a sentence (가방이 비싸요)."}},{title:"V-는 N — A present/habitual action describing a noun",func:"To describe a noun by an action happening now or done regularly (the person who is *eating*, the book I *read* these days), add -는 to the verb stem and put it before the noun. It works like an English 'who/that' clause ('the person who eats').",formTable:[{when:"Any verb stem (vowel- or consonant-final)",add:"+ 는",ex:"먹다 → 먹는 / 가다 → 가는 (사람)"},{when:"ㄹ-final stem (drop the ㄹ)",add:"ㄹ drops, + 는",ex:"살다 → 사는 (집)"},{when:"있다/없다",add:"+ 는",ex:"있다 → 있는 (시간)"}],examples:[{ko:"밥을 먹는 사람이 친구예요.",romanization:"babeul meongneun sarami chinguyeyo.",en:"The person eating is my friend.",note:"먹다 + 는 → 먹는. The whole chunk '밥을 먹는' describes 사람, and the object 밥을 stays inside it."},{ko:"제가 자주 가는 학교예요.",romanization:"jega jaju ganeun hakgyoyeyo.",en:"It's the school I go to often.",note:"가다 is a vowel stem; -는 still attaches → 가는, and 자주 ('often') gives it the habitual meaning."},{ko:"한국어를 공부하는 학생이에요.",romanization:"hangugeoreul gongbuhaneun haksaengieyo.",en:"He's a student who studies Korean.",note:"공부하다 → 공부하는; -는 marks an ongoing/habitual action describing 학생."},{ko:"지금 읽는 책이 재미있어요.",romanization:"jigeum ingneun chaegi jaemiisseoyo.",en:"The book I'm reading now is fun.",note:"읽다 + 는 → 읽는 [잉는]; 지금 ('now') makes the in-progress meaning clear."}],keyPoint:{label:"먹는 사람 vs 예쁜 사람",body:"Verbs and adjectives use different modifier endings in the present. A verb (an action) takes -는: 먹는 사람 ('the person who eats'). An adjective (a state) takes -(으)ㄴ: 예쁜 사람 ('a pretty person'). Just ask 'is this a doing-word or a describing-word?' to pick the ending."},pronunciation:"먹는 is said [멍는] (meongneun): a ㄱ before ㄴ turns into an [ㅇ] sound (nasal assimilation). 읽는 → [잉는] (ingneun) the same way.",drill:{instruction:"Make the verb into the present V-는 modifier and attach it to the noun.",model:"(먹다) 사람 → 먹는 사람",items:["(가다) 버스 →","(공부하다) 학생 →","(살다) 집 →"]},englishSpeakerPitfall:{wrong:"먹은 사람 (for 'the person who is eating')",right:"먹는 사람",explanation:"English 'eating' is one word, so learners mix up the endings. For an action happening now or regularly, use -는 (먹는 사람). Putting -(으)ㄴ on a verb (먹은) means a *finished* action ('the person who ate') — a different time."}},{title:"V-(으)ㄴ N — A finished (past) action describing a noun",func:"To describe a noun by an action that's already over (the movie I *saw* yesterday, the person who *came*), add -(으)ㄴ to the verb stem and put it before the noun. It marks the action as done — the past version of the 'who/that' clause.",formTable:[{when:"Verb stem ends in a vowel",add:"+ ㄴ",ex:"보다 → 본 (영화)"},{when:"Verb stem ends in a consonant",add:"+ 은",ex:"먹다 → 먹은 (밥)"},{when:"ㄹ-final stem (drop the ㄹ)",add:"ㄹ drops, + ㄴ",ex:"만들다 → 만든 (음식)"},{when:"ㄷ-irregular (받침 ㄷ → ㄹ)",add:"ㄷ → ㄹ, + 은",ex:"듣다 → 들은 (노래)"}],examples:[{ko:"어제 본 영화가 좋았어요.",romanization:"eoje bon yeonghwaga joasseoyo.",en:"The movie I saw yesterday was good.",note:"보다 is a vowel stem → 본; 어제 ('yesterday') shows it's finished, so we use -(으)ㄴ, not -는."},{ko:"아까 먹은 밥이 맛있었어요.",romanization:"akka meogeun babi masisseosseoyo.",en:"The meal I ate earlier was delicious.",note:"먹다 ends in a consonant → 먹은 [머근]; the meal is already eaten — a finished action."},{ko:"친구가 만든 음식이에요.",romanization:"chinguga mandeun eumsigieyo.",en:"It's the food my friend made.",note:"만들다 is a ㄹ-stem: drop the ㄹ, add ㄴ → 만든 (not 만들은)."},{ko:"어제 들은 노래를 또 들어요.",romanization:"eoje deureun noraereul tto deureoyo.",en:"I'm listening again to the song I heard yesterday.",note:"듣다 is a ㄷ-irregular: ㄷ becomes ㄹ before 은 → 들은 (not 듣은)."}],keyPoint:{label:"본 영화 vs 보는 영화",body:"On a verb, the ending sets the time. -(으)ㄴ = finished/past (어제 본 영화 = 'the movie I saw'). -는 = now or habitual (지금 보는 영화 = 'the movie I'm watching now'). Pick the ending by *when* the action happens compared to now."},pronunciation:"먹은 links as [머근] (meogeun) and 읽은 as [일근] (ilgeun): the final consonant slides into the next syllable. 만든 (from 만들다) is just [만든] (mandeun).",drill:{instruction:"Make the verb into the past V-(으)ㄴ modifier and attach it to the noun.",model:"(보다) 영화 → 본 영화",items:["(먹다) 밥 →","(만들다) 음식 →","(듣다) 노래 →"]},englishSpeakerPitfall:{wrong:"어제 봤은 영화 / 어제 보는 영화 (for 'the movie I saw yesterday')",right:"어제 본 영화",explanation:"Learners either glue the past -았/었- onto the modifier (봤은 ✗) or fall back on -는. Don't add -았/었- before the noun — the 'finished' meaning is already in -(으)ㄴ by itself: 보다 → 본 영화."}}],_=[{title:"N을/를 좋아해요 — I like N",func:'Use 좋아하다 to say you like something or someone. It is an action verb ("to like"), not the adjective 좋다 ("to be good"), so the thing you like is the object and takes 을/를, not 이/가.',formTable:[{when:"Noun ends in a consonant (받침)",add:"+ 을 좋아해요",ex:"음악 → 음악을 좋아해요"},{when:"Noun ends in a vowel",add:"+ 를 좋아해요",ex:"커피 → 커피를 좋아해요"},{when:"Casual speech (particle often dropped)",add:"drop 을/를",ex:"커피 좋아해요"}],examples:[{ko:"저는 커피를 좋아해요.",romanization:"jeo-neun keo-pi-reul jo-a-hae-yo.",en:"I like coffee.",note:"커피 ends in a vowel, so it takes 를."},{ko:"한국 음식을 좋아해요.",romanization:"han-guk eum-si-geul jo-a-hae-yo.",en:"I like Korean food.",note:"음식 ends in a 받침, so it takes 을."},{ko:"저는 한국어를 좋아해요.",romanization:"jeo-neun han-gu-geo-reul jo-a-hae-yo.",en:"I like Korean.",note:"좋아하다 takes the object with 을/를, never 이/가."},{ko:"매운 음식은 별로 안 좋아해요.",romanization:"mae-un eum-si-geun byeol-lo an jo-a-hae-yo.",en:"I don't really like spicy food.",note:`별로 안 softens it to "don't really like."`}],keyPoint:{label:"좋다 vs 좋아하다",body:'좋다 is an adjective and takes 이/가: 커피가 좋아요 ("coffee is good to me"). 좋아하다 is a verb and takes 을/를: 커피를 좋아해요. Both can translate as "I like coffee," but the particle follows the word you actually use. For now, just lock in 을/를 with 좋아해요.'},pronunciation:"좋아해요 sounds like [조아해요] — the ㅎ in 좋 drops before the vowel, so don't say [졷아해요].",drill:{instruction:"Say you like each thing with N을/를 좋아해요. Pick 을 or 를 by the last sound of the noun.",model:"음악 → 저는 음악을 좋아해요.",items:["커피 → 저는 ___ 좋아해요.","음식 → 저는 한국 ___ 좋아해요.","한국어 → 저는 ___ 좋아해요."]},englishSpeakerPitfall:{wrong:"저는 커피가 좋아해요.",right:"저는 커피를 좋아해요.",explanation:'English "I like X" pushes you toward the subject particle, but 좋아하다 is a verb that takes an object — use 을/를. The 가 version only works with the adjective 좋다 (커피가 좋아요).'}},{title:"N보다 더 — more than N",func:`Attach 보다 to the thing you're comparing against (the baseline) to mean "more than N." 더 ("more") usually comes right before the adjective or verb. 더 is optional, but adding it makes the comparison clear.`,formTable:[{when:"Baseline noun (what you compare against)",add:"+ 보다",ex:"차 → 차보다"},{when:"Add 더 before the adjective/verb",add:"N보다 + 더 + Adj/Verb",ex:"차보다 더 좋아요"},{when:'For "less," use 덜 instead of 더',add:"N보다 + 덜 + Adj",ex:"어제보다 덜 추워요"}],examples:[{ko:"저는 차보다 커피를 더 좋아해요.",romanization:"jeo-neun cha-bo-da keo-pi-reul deo jo-a-hae-yo.",en:"I like coffee more than tea.",note:'차 is the baseline ("than tea"); 커피 is the one I prefer.'},{ko:"오늘이 어제보다 더 추워요.",romanization:"o-neu-ri eo-je-bo-da deo chu-wo-yo.",en:"Today is colder than yesterday.",note:"보다 attaches to 어제, the thing being compared against."},{ko:"이 영화가 저 영화보다 더 재미있어요.",romanization:"i yeong-hwa-ga jeo yeong-hwa-bo-da deo jae-mi-i-sseo-yo.",en:"This movie is more fun than that one.",note:"보다 marks what this movie is compared against."},{ko:"버스가 지하철보다 더 느려요.",romanization:"beo-seu-ga ji-ha-cheol-bo-da deo neu-ryeo-yo.",en:"The bus is slower than the subway.",note:"The baseline (지하철) carries 보다, no matter the word order."}],keyPoint:{label:"보다 marks the baseline, not the winner",body:'In "A is more than B," 보다 goes on B — the thing you measure against — not on the one that wins: A이/가 B보다 더 ~. English speakers often want to put "than" on the smaller side, but in Korean 보다 always sits on the baseline noun. 더 is optional and just makes "more" explicit.'},pronunciation:"",drill:{instruction:"Make a comparison with N보다 더. Put 보다 on the baseline noun.",model:"차 / 커피 (좋아하다) → 저는 차보다 커피를 더 좋아해요.",items:["어제 / 오늘 (춥다) → 오늘이 ___ 더 추워요.","저 영화 / 이 영화 (재미있다) → 이 영화가 ___ 더 재미있어요.","지하철 / 버스 (느리다) → 버스가 ___ 더 느려요."]},englishSpeakerPitfall:{wrong:"저는 차보다 커피를 더 좋아해요. (said when you actually prefer tea)",right:"저는 커피보다 차를 더 좋아해요.",explanation:'Learners flip the nouns because English says "tea more than coffee." In Korean, 보다 sits on the baseline (the one you like less). If you like tea more, coffee is the baseline: 커피보다 차를 더.'}},{title:"N만큼 — as much as N / as Adj as N",func:`Attach 만큼 to a noun to mean "as much as N" or "to the same degree as N." It marks an equal level in a comparison, and the adjective or verb comes after it. It's very common in "not as ... as I expected" sentences with 생각.`,formTable:[{when:"Baseline noun (the level you match)",add:"+ 만큼",ex:"생각 → 생각만큼"},{when:"With an adjective (equal degree)",add:"N만큼 + Adj",ex:"라떼만큼 맛있어요"},{when:"Very common with a negative",add:"N만큼 + Adj/Verb + 안/-지 않다",ex:"생각만큼 안 비싸요"}],examples:[{ko:"이 카페 라떼만큼 맛있는 커피는 없어요.",romanization:"i ka-pe rat-te-man-keum ma-sin-neun keo-pi-neun eop-seo-yo.",en:"There's no coffee as tasty as this cafe's latte.",note:'라떼만큼 sets the level of "tasty."'},{ko:"생각만큼 비싸지 않아요.",romanization:"saeng-gang-man-keum bi-ssa-ji a-na-yo.",en:"It's not as expensive as I thought.",note:'생각만큼 is a super-common chunk for "as ... as expected."'},{ko:"오늘은 어제만큼 추워요.",romanization:"o-neu-reun eo-je-man-keum chu-wo-yo.",en:"Today is as cold as yesterday.",note:"만큼 attaches to 어제, the level being matched."},{ko:"저는 친구만큼 커피를 좋아해요.",romanization:"jeo-neun chin-gu-man-keum keo-pi-reul jo-a-hae-yo.",en:"I like coffee as much as my friend does.",note:"만큼 also works with verbs of degree like 좋아해요."}],keyPoint:{label:"만큼 (equal) vs 보다 (more)",body:'Use 보다 for "more than" — one side wins: 친구보다 잘해요 = better than my friend. Use 만큼 for "as much as" — the two are equal: 친구만큼 잘해요 = as well as my friend. Swapping them turns "the same" into "more," so keep them apart.'},pronunciation:"라떼만큼 is straightforward, but 책만큼 sounds like [챙만큼] — the ㄱ in 책 turns into [ㅇ] before the nasal ㅁ.",drill:{instruction:"Say two things are equal with N만큼. Put 만큼 on the baseline noun.",model:"친구 (커피를 좋아하다) → 저는 친구만큼 커피를 좋아해요.",items:["어제 (춥다) → 오늘은 ___ 추워요.","생각 (비싸다, negative) → ___ 비싸지 않아요.","라떼 (맛있다) → 이 커피는 ___ 맛있어요."]},englishSpeakerPitfall:{wrong:'저는 친구보다 커피를 좋아해요. (meaning "as much as," not "more than")',right:"저는 친구만큼 커피를 좋아해요.",explanation:'English "as much as" and "more than" feel close, but Korean splits them: 만큼 = same degree, 보다 = more. Use 만큼 when the two are equal, and save 보다 for when one really beats the other.'}}],v=[{title:"N(으)로 — by / toward / through (means, direction, route)",func:"N(으)로 marks how you travel (by bus, by subway), the direction you head (this way, toward home), or the path you go through (out that door). It points at the way you go, not the exact spot you end up.",formTable:[{when:"Noun ends in a consonant",add:"+ 으로",ex:"집 → 집으로 (toward home), 오른쪽 → 오른쪽으로 (to the right)"},{when:"Noun ends in a vowel",add:"+ 로",ex:"버스 → 버스로 (by bus), 학교 → 학교로 (toward school)"},{when:"Noun ends in ㄹ",add:"+ 로 (like a vowel)",ex:"지하철 → 지하철로 (by subway), 서울 → 서울로 (toward Seoul)"}],examples:[{ko:"저는 버스로 학교에 가요.",romanization:"jeo-neun beo-seu-ro hak-gyo-e ga-yo.",en:"I go to school by bus.",note:'버스 ends in a vowel, so just 로. This is the "by what transport" use.'},{ko:"이쪽으로 오세요.",romanization:"i-jjog-eu-ro o-se-yo.",en:"Come this way.",note:"이쪽 ends in a consonant, so 으로. Here 로 marks direction, not a means."},{ko:"지하철로 집에 가요.",romanization:"ji-ha-cheol-lo jib-e ga-yo.",en:"I go home by subway.",note:"지하철 ends in ㄹ, so it takes plain 로 (not 으로)."},{ko:"저 문으로 나가세요.",romanization:"jeo mun-eu-ro na-ga-se-yo.",en:"Go out through that door.",note:'문 ends in a consonant → 으로. This is the "path you go through" use.'}],keyPoint:{label:"-(으)로 vs -에 (direction vs the place you reach)",body:"-에 names the place you arrive at: 학교에 가요 = go to school (you end up there). -(으)로 names the direction you head or the way you go: 학교로 가요 = go toward / in the direction of school. Use -(으)로 when the point is which way, and -에 when the point is the place you reach."},pronunciation:"After a noun ending in ㄹ, just add 로 with no 으, and the two ㄹ sounds run together: 지하철 + 로 → [지하철로]. Don't say 지하철으로.",drill:{instruction:"Add the right form of -(으)로 to each noun and say the whole sentence out loud.",model:"택시 → 택시로 가요. (I go by taxi.)",items:["오른쪽 → ___ 가세요. (Go to the right.)","자전거 → ___ 와요. (Come by bike.)","이 길 → ___ 가세요. (Go this way / along this road.)"]},englishSpeakerPitfall:{wrong:"버스에 학교에 가요.",right:"버스로 학교에 가요.",explanation:'English says "by bus," and learners often grab -에 because they picture "on the bus." But the means of transport takes -(으)로, never -에. 버스에 would sound like "to the bus."'}},{title:"V-(으)러 가요/와요 — go/come to do something",func:`V-(으)러 tags onto an action verb to say why you're going or coming, and it's always followed by a movement verb like 가다, 오다, or 다니다. It answers "what did you go/come to do?"`,formTable:[{when:"Verb stem ends in a consonant",add:"+ 으러",ex:"먹다 → 먹으러 (가요), 찾다 → 찾으러 (가요)"},{when:"Verb stem ends in a vowel",add:"+ 러",ex:"보다 → 보러 (가요), 사다 → 사러 (가요)"},{when:"Verb stem ends in ㄹ",add:"+ 러 (like a vowel)",ex:"놀다 → 놀러 (가요), 만들다 → 만들러 (가요)"}],examples:[{ko:"점심을 먹으러 식당에 가요.",romanization:"jeom-sim-eul meog-eu-reo sik-dang-e ga-yo.",en:"I'm going to the restaurant to eat lunch.",note:"먹다 ends in a consonant → 먹으러. The thing you go to do comes first, then 가요."},{ko:"친구를 만나러 학교에 왔어요.",romanization:"chin-gu-reul man-na-reo hak-gyo-e wass-eo-yo.",en:"I came to school to meet a friend.",note:"만나다 ends in a vowel → 만나러. Here the movement verb is 오다 (왔어요)."},{ko:"책을 사러 서점에 가요.",romanization:"chaeg-eul sa-reo seo-jeom-e ga-yo.",en:"I'm going to the bookstore to buy a book.",note:"사다 ends in a vowel → 사러. The object 책을 stays with its own verb 사다."},{ko:"우리 집에 놀러 오세요.",romanization:"u-ri jib-e nol-leo o-se-yo.",en:"Come hang out at my place.",note:"놀다 ends in ㄹ → 놀러 (not 놀으러). A super common everyday invitation."}],keyPoint:{label:"-(으)러 vs -기 위해서 (going to do vs why in general)",body:"-(으)러 is only for the reason you go or come, so it has to be followed by a movement verb (가다/오다/다니다): 밥을 먹으러 가요. -기 위해서 gives the reason for any action: 살을 빼려고 운동해요 sounds more natural here, but the textbook pair is -기 위해서. The simple rule: if it's about going or coming somewhere to do something, use -(으)러 가요."},pronunciation:"After a stem ending in a consonant, the 으러 links right onto that consonant: 먹 + 으러 → [머그러]. No pause — the ㄱ slides into 으.",drill:{instruction:"Join the two verbs with -(으)러 and read the sentence aloud.",model:"영화를 보다 + 가다 → 영화를 보러 가요. (I'm going to watch a movie.)",items:["돈을 찾다 + 가다 → ___ (I'm going to get some money out.)","한국어를 배우다 + 다니다 → ___ (I go to class to learn Korean.)","사진을 찍다 + 가다 → ___ (I'm going to take some photos.)"]},englishSpeakerPitfall:{wrong:'공부하기 위해서 도서관에 가요. (when you just mean "go to study")',right:"공부하러 도서관에 가요.",explanation:`English "go to study" tempts learners into the heavier -기 위해서. When you're just going or coming somewhere to do something, the natural, level-right choice is -(으)러 가요. Keep -기 위해서 for reasons that aren't about going anywhere.`}}],j=[{title:"V-아/어 보다 — try doing V (give it a go)",func:`Add -아/어 보다 to a verb to mean "try doing something" — do it once and see how it goes. It's the warm, everyday way to nudge someone: "go ahead and try it."`,formTable:[{when:"Stem ends in ㅏ or ㅗ",add:"-아 보다",ex:"가다 → 가 보다 (try going), 오다 → 와 보다 (try coming)"},{when:"Stem ends in any other vowel",add:"-어 보다",ex:"먹다 → 먹어 보다 (try eating), 읽다 → 읽어 보다 (try reading)"},{when:"하- verb",add:"-여 보다 → 해 보다",ex:"하다 → 해 보다 (try doing), 공부하다 → 공부해 보다 (try studying)"}],examples:[{ko:"이 책 한번 읽어 보세요.",romanization:"i chaek hanbeon ilgeo boseyo.",en:"Try reading this book.",note:'한번 ("give it a try") goes hand in hand with -아/어 보다 to soften a suggestion.'},{ko:"이 음식 먹어 봤어요?",romanization:"i eumsik meogeo bwasseoyo?",en:"Have you tried this food?",note:'Past 봤어요 asks about experience — "have you ever tried it?"'},{ko:"한국 음식 만들어 보고 싶어요.",romanization:"hanguk eumsik mandeureo bogo sipeoyo.",en:"I want to try making Korean food.",note:"-아/어 보다 slots right into -고 싶다 when you want to give something a try."},{ko:"친구한테 한번 물어 보세요.",romanization:"chinguhante hanbeon mureo boseyo.",en:"Try asking your friend.",note:"묻다 is a ㄷ-irregular: 묻- → 물어, then + 보세요."}],keyPoint:{label:"V-아/어 보다 vs. plain V",body:'먹으세요 just says "eat it." 먹어 보세요 says "try it and see how it is" — it frames the action as something new to test out, which makes the suggestion feel friendlier and less pushy.'},pronunciation:"In 읽어 보세요, the ㄺ of 읽- links forward, so it sounds like [일거 보세요] — the ㄱ carries into the next syllable.",drill:{instruction:'Turn each verb into a friendly suggestion with -아/어 보세요 ("try ___-ing").',model:"입다 (to wear) → 입어 보세요. (Try it on.)",items:["가다 (to go) → ______","마시다 (to drink) → ______","공부하다 (to study) → ______"]},englishSpeakerPitfall:{wrong:"봐 보세요 is ungrammatical because 보다 appears twice.",right:"한번 봐 보세요. / 한번 보세요.",explanation:"봐 보세요 is grammatical: the first 보다 is the main verb 'look/watch,' and the second 보다 is the helper 'try and see.' Because the repetition can sound heavy, 한번 보세요 is often simpler, while 한번 봐 보세요 clearly emphasizes trying it for yourself."}},{title:"V-아/어 주세요 — please do V (for me)",func:"Add -아/어 주세요 to a verb to politely ask someone to do something for you. It's the normal, warm way to make a request — softer than a bare command.",formTable:[{when:"Stem ends in ㅏ or ㅗ",add:"-아 주세요",ex:"앉다 → 앉아 주세요 (please sit), 보다 → 봐 주세요 (please look)"},{when:"Stem ends in any other vowel",add:"-어 주세요",ex:"열다 → 열어 주세요 (please open), 기다리다 → 기다려 주세요 (please wait)"},{when:"하- verb",add:"-여 주세요 → 해 주세요",ex:"하다 → 해 주세요 (please do), 말하다 → 말해 주세요 (please tell me)"}],examples:[{ko:"물 좀 주세요.",romanization:"mul jom juseyo.",en:"Please give me some water.",note:'With 주다 itself you just say 주세요; 좀 ("a little") softens it.'},{ko:"문 좀 열어 주세요.",romanization:"mun jom yeoreo juseyo.",en:"Please open the door for me.",note:"열다 → 열어 + 주세요; 좀 makes it gentler."},{ko:"천천히 말해 주세요.",romanization:"cheoncheonhi malhae juseyo.",en:"Please speak slowly.",note:"하다 verb: 말하다 → 말해 주세요. A really useful one for learners."},{ko:"잠깐만 기다려 주세요.",romanization:"jamkkanman gidaryeo juseyo.",en:"Please wait a moment.",note:"기다리다 → 기다려 주세요; the waiting is for your sake, so 주다 fits."}],keyPoint:{label:"V-(으)세요 vs. V-아/어 주세요",body:`앉으세요 is a polite instruction aimed at what the listener does ("please sit"). 앉아 주세요 adds 주다 ("do it for me"), so it lands as a favor you'd be grateful for — exactly the feel of most polite English requests.`},pronunciation:"열어 주세요 links across the ㄹ → [여러 주세요]; the ㄹ of 열- slides into the next syllable.",drill:{instruction:'Make a polite request with -아/어 주세요 ("please ___ for me").',model:"보다 (to look) → 봐 주세요. (Please look.)",items:["읽다 (to read) → ______","쓰다 (to write) → ______","전화하다 (to call) → ______"]},englishSpeakerPitfall:{wrong:'기다리세요 (meaning "please wait for me")',right:"기다려 주세요",explanation:`English "please" can't tell apart a plain instruction from a favor. -(으)세요 on its own can sound like an order or a general direction; adding 주다 (기다려 주세요) marks the action as done for your benefit — which is what most polite English requests really mean.`}},{title:"V-(으)ㄹ까요? — shall we? / should I?",func:`Add -(으)ㄹ까요? to a verb to suggest doing something together ("shall we?") or to ask what the listener thinks about you doing it ("should I?"). It's the standard way to float a friendly idea.`,formTable:[{when:"Stem ends in a vowel",add:"-ㄹ까요?",ex:"가다 → 갈까요? (shall we go?), 마시다 → 마실까요? (shall we drink?)"},{when:"Stem ends in a consonant",add:"-을까요?",ex:"먹다 → 먹을까요? (shall we eat?), 앉다 → 앉을까요? (shall we sit?)"},{when:"Stem ends in ㄹ",add:"-까요? (the ㄹ stays, no 을)",ex:"놀다 → 놀까요? (shall we hang out?), 만들다 → 만들까요? (shall we make it?)"}],examples:[{ko:"우리 같이 밥 먹을까요?",romanization:"uri gachi bap meogeulkkayo?",en:"Shall we eat together?",note:'우리 같이 ("we, together") makes the group "shall we?" clear.'},{ko:"내일 영화 볼까요?",romanization:"naeil yeonghwa bolkkayo?",en:"Shall we watch a movie tomorrow?",note:"보다 ends in a vowel → 볼까요?; a casual invite to do something together."},{ko:"창문을 열까요?",romanization:"changmuneul yeolkkayo?",en:"Shall I open the window?",note:`열다 ends in ㄹ, so just add -까요? → 열까요?. Here it asks the listener's opinion: "should I?"`},{ko:"우리 어디에서 만날까요?",romanization:"uri eodieseo mannalkkayo?",en:"Where shall we meet?",note:"만나다 → 만날까요?; question words like 어디 fit right in."}],keyPoint:{label:"V-(으)ㄹ까요? vs. V-아/어요",body:`먹어요 states or mildly pushes ("(let's) eat"). 먹을까요? turns it into a real question that hands the decision to the listener — you propose, they answer. Reach for -(으)ㄹ까요? when you actually want their okay, not just to announce the plan.`},pronunciation:"The 까 is always tense (ㄲ): 먹을까요? sounds like [머글까요]. The ㄱ of 먹- links forward into 을.",drill:{instruction:'Turn each verb into a "shall we?" suggestion with -(으)ㄹ까요?.',model:"가다 (to go) → 갈까요? (Shall we go?)",items:["마시다 (to drink) → ______","앉다 (to sit) → ______","산책하다 (to take a walk) → ______"]},englishSpeakerPitfall:{wrong:"놀을까요? (adding 을 to a ㄹ-stem)",right:"놀까요?",explanation:"After seeing 먹다 → 먹을까요?, learners often glue 을 onto ㄹ-stems too. But ㄹ-stems already end in a vowel-like ㄹ that carries the sound, so you just add -까요?: 놀다 → 놀까요?, 만들다 → 만들까요?, 열다 → 열까요?. No extra 을."}},{title:`V-(으)ㅂ시다 — formal "let's" for groups`,func:"Use -(으)ㅂ시다 to suggest that a group do something in a formal or public setting. It sounds organized and official, so it fits meetings, announcements, campaigns, and speeches. For friends, use -자; for a softer suggestion, use -(으)ㄹ까요?",formTable:[{when:"Stem ends in a vowel",add:"-ㅂ시다",ex:"가다 → 갑시다 (let's go), 시작하다 → 시작합시다"},{when:"Stem ends in a consonant",add:"-읍시다",ex:"먹다 → 먹읍시다 (let's eat), 읽다 → 읽읍시다"},{when:"Stem ends in ㄹ",add:"drop ㄹ, then + ㅂ시다",ex:"만들다 → 만듭시다, 살다 → 삽시다"}],examples:[{ko:"회의를 시작합시다.",romanization:"hoeuireul sijakhapsida.",en:"Let's start the meeting.",note:"A natural meeting-room use: formal, clear, and group-directed."},{ko:"다음 역에서 내립시다.",romanization:"daeum yeogeseo naeripsida.",en:"Let's get off at the next station.",note:"Announcement-like and organized, not a casual friend-to-friend suggestion."},{ko:"다 같이 건배합시다.",romanization:"da gachi geonbaehapsida.",en:"Let's all make a toast.",note:"Works when someone leads a group at a dinner or event."},{ko:"우리 함께 규칙을 지킵시다.",romanization:"uri hamkke gyuchigeul jikipsida.",en:"Let's follow the rules together.",note:"Campaign or public-message tone; 함께 makes the group invitation explicit."}],keyPoint:{label:"-자 < -(으)ㄹ까요? < -(으)ㅂ시다",body:"가자 is casual and close. 갈까요? is softer because it asks the listener's opinion. 갑시다 is formal and group-leading — useful in meetings or public speech, but too stiff for close friends."},pronunciation:"In 시작합시다 and 건배합시다, the ㅂ before 시다 is held clearly, and 시다 is always pronounced tense, like [씨다] — 합시다 sounds like [합씨다] at any speed, though the spelling stays 합시다. Don't turn 합시다 into 하십니다 — that is a different ending.",drill:{instruction:"Change each verb into a formal group suggestion with -(으)ㅂ시다.",model:"가다 → 갑시다.",items:["시작하다 → ____","먹다 → ____","만들다 → ____"]},englishSpeakerPitfall:{wrong:"사장님, 같이 갑시다.",right:"사장님, 같이 가시겠어요? / 같이 가실까요?",explanation:`English "let's" can sound friendly upward, but -(으)ㅂ시다 can feel like you are leading or directing the other person. With a boss, teacher, or older person one-on-one, use a respectful question such as 가시겠어요? or 가실까요? instead.`}}],x=[{title:"A/V-지만 — but",func:'Use -지만 to join two clauses that go against each other, like English "but." The first clause says one thing, and the second says something that pushes the other way.',formTable:[{when:"Verb or adjective stem (consonant or vowel)",add:"-지만",ex:"먹다 → 먹지만, 비싸다 → 비싸지만, 가다 → 가지만"},{when:"Past tense",add:"-았/었/였- + 지만",ex:"먹다 → 먹었지만, 가다 → 갔지만, 공부하다 → 공부했지만"},{when:'Noun + 이다 ("is")',add:"이지만 (after consonant) / 지만 (after vowel)",ex:"학생 → 학생이지만, 친구 → 친구지만"}],examples:[{ko:"이 책은 재미있지만 너무 길어요.",romanization:"i chaegeun jaemiitjiman neomu gireoyo.",en:"This book is fun, but it's too long.",note:"재미있- takes -지만 right on the stem; both clauses are about the same book."},{ko:"한국어는 어렵지만 재미있어요.",romanization:"hangugeoneun eoryeopjiman jaemiisseoyo.",en:"Korean is hard, but it's fun.",note:"The classic shape: one downside, then one upside."},{ko:"밥은 먹었지만 아직 배고파요.",romanization:"babeun meogeotjiman ajik baegopayo.",en:"I ate, but I'm still hungry.",note:"Put the past tense on the first clause: 먹었- + 지만."},{ko:"제 친구는 학생이지만 일도 해요.",romanization:"je chinguneun haksaengijiman ildo haeyo.",en:"My friend is a student, but works too.",note:"After a noun ending in a consonant, use 이지만: 학생 + 이지만."}],keyPoint:{label:"-지만 vs. 하지만",body:"-지만 connects two clauses inside one sentence: 비싸지만 맛있어요. 하지만 is a separate word that starts a new sentence: 비싸요. 하지만 맛있어요. Same meaning, but don't drop 하지만 in the middle of a clause — that spot belongs to -지만."},pronunciation:"After a final ㄱ or ㅈ-type sound the next syllable tightens: 먹지만 sounds like [먹찌만], 좋지만 like [조치만]. The 지만 part is never the loud part of the word.",drill:{instruction:"Join the two ideas into one sentence with A/V-지만. Keep any past tense on the first clause.",model:"비싸다 / 사고 싶어요 → 비싸지만 사고 싶어요. (It's expensive, but I want to buy it.)",items:["시간이 없다 / 운동해요 → ____","영화를 봤다 / 기억이 안 나요 → ____","날씨가 춥다 / 괜찮아요 → ____"]},englishSpeakerPitfall:{wrong:"한국어는 어려워요지만 재미있어요.",right:"한국어는 어렵지만 재미있어요.",explanation:"-지만 goes on the plain stem (어렵-), not on the polite -아/어요 form. Drop the 요, attach -지만 to the stem, and let the politeness show up just once at the very end."}},{title:"A/V-(으)ㄴ/는데도 — even though, and still",func:'Use -(으)ㄴ/는데도 for "even though A, B anyway," where B is surprising given A. It points out that the result happened in spite of the first clause.',formTable:[{when:"Verb stem (present)",add:"-는데도",ex:"먹다 → 먹는데도, 오다 → 오는데도"},{when:"Adjective stem ending in a vowel",add:"-ㄴ데도",ex:"비싸다 → 비싼데도, 아프다 → 아픈데도"},{when:"Adjective stem ending in a consonant",add:"-은데도",ex:"좋다 → 좋은데도, 많다 → 많은데도"},{when:"Past tense (verb or adjective)",add:"-았/었/였- + 는데도",ex:"먹다 → 먹었는데도, 비싸다 → 비쌌는데도"}],examples:[{ko:"약을 먹었는데도 아직 아파요.",romanization:"yageul meogeonneundedo ajik apayo.",en:"Even though I took medicine, I'm still sick.",note:"먹었- + 는데도; the second clause is the surprising part."},{ko:"이 식당은 비싼데도 사람이 많아요.",romanization:"i sikdangeun bissandedo sarami manayo.",en:"Even though this restaurant is expensive, it's packed.",note:"Vowel-ending adjective 비싸- takes -ㄴ데도 → 비싼데도."},{ko:"매일 공부하는데도 한국어가 어려워요.",romanization:"maeil gongbuhaneundedo hangugeoga eoryeowoyo.",en:"Even though I study every day, Korean is hard.",note:"Present verb 공부하- takes -는데도, the normal verb shape."},{ko:"돈이 많은데도 잘 안 써요.",romanization:"doni maneundedo jal an sseoyo.",en:"Even though he has a lot of money, he barely spends it.",note:"Consonant-ending adjective 많- takes -은데도 → 많은데도."}],keyPoint:{label:"-(으)ㄴ/는데도 vs. -지만",body:`-지만 is a flat "but." -(으)ㄴ/는데도 adds "and still," with a sense of surprise that B happened anyway. 약을 먹었지만 아파요 just states two facts; 약을 먹었는데도 아파요 sounds more like "I took the medicine and I'm STILL sick."`},pronunciation:'Past forms nasalize: 먹었는데도 sounds like [머건는데도], 했는데도 like [핸는데도] — the ㅅ turns into an ㄴ sound before 는. The 도 at the end gets a small push for the "and still" feeling.',drill:{instruction:'Combine the two clauses with A/V-(으)ㄴ/는데도 for "even though A, B anyway." Watch verb vs. adjective endings.',model:"운동하다 / 살이 안 빠져요 → 운동하는데도 살이 안 빠져요. (Even though I work out, I don't lose weight.)",items:["밥을 많이 먹었다 / 배고파요 → ____","집이 가깝다 / 자주 늦어요 → ____","책을 샀다 / 안 읽어요 → ____"]},englishSpeakerPitfall:{wrong:"비싸는데도 사람이 많아요.",right:"비싼데도 사람이 많아요.",explanation:"Learners stick -는데도 on everything, but -는데도 is for verbs only. Adjectives take -(으)ㄴ데도: 비싸다 → 비싼데도, 좋다 → 좋은데도. Ask if the word is an action (verb → 는데도) or a description (adjective → ㄴ/은데도)."}},{title:"V-아/어도 — even if / even though",func:'Use -아/어도 for "even if" or "even though." It means that no matter how the first clause turns out, the second clause still holds.',formTable:[{when:"Stem with ㅏ or ㅗ as the last vowel",add:"-아도",ex:"가다 → 가도, 오다 → 와도, 보다 → 봐도"},{when:"Stem with any other vowel",add:"-어도",ex:"먹다 → 먹어도, 읽다 → 읽어도, 마시다 → 마셔도"},{when:"하다 verbs and adjectives",add:"해도",ex:"공부하다 → 공부해도, 피곤하다 → 피곤해도"},{when:"Adjective stem 없다/있다",add:"-어도",ex:"없다 → 없어도, 맛있다 → 맛있어도"}],examples:[{ko:"비가 와도 학교에 가요.",romanization:"biga wado hakgyoe gayo.",en:"Even if it rains, I go to school.",note:"오다 → 와도; the going happens no matter the rain."},{ko:"아무리 먹어도 배가 안 불러요.",romanization:"amuri meogeodo baega an bulleoyo.",en:"No matter how much I eat, I don't get full.",note:'아무리 ... -아/어도 is the set "no matter how much" frame.'},{ko:"피곤해도 운동을 해요.",romanization:"pigonhaedo undongeul haeyo.",en:"Even when I'm tired, I work out.",note:"하다 adjective 피곤하- → 피곤해도."},{ko:"시간이 없어도 밥은 먹어요.",romanization:"sigani eopseodo babeun meogeoyo.",en:"Even when I have no time, I still eat.",note:"없- + 어도 → 없어도; the first clause is the condition you push through."}],keyPoint:{label:"-아/어도 vs. -(으)ㄴ/는데도",body:'Both can come out as "even though" in English, but -아/어도 covers "even IF" — it works for things that may or may not happen (비가 와도 = even if it rains, real or not). -(으)ㄴ/는데도 is for a real fact happening right now (비가 오는데도 = even though it IS raining). Use -아/어도 for conditions, -는데도 for facts.'},pronunciation:"Watch the vowel squeeze: 오다 → 와도, 보다 → 봐도, 마시다 → 마셔도. The 도 stays quiet; the squeezed syllable carries the beat.",drill:{instruction:'Make a sentence with V-아/어도 for "even if / even though." Pick the right 아/어 vowel.',model:"바쁘다 / 친구를 만나요 → 바빠도 친구를 만나요. (Even if I'm busy, I meet my friend.)",items:["돈이 없다 / 행복해요 → ____","비가 오다 / 가요 → ____","많이 자다 / 피곤해요 → ____"]},englishSpeakerPitfall:{wrong:"비가 와서도 학교에 가요.",right:"비가 와도 학교에 가요.",explanation:`There's no 서 in this pattern — -아/어도 attaches straight to the 아/어 stem. And don't mix it up with -아/어서 ("because"): -아/어서 gives a reason, while -아/어도 gives a concession ("even if").`}}],I=[{title:"A/V-(으)ㄹ 것 같아요",func:"A soft guess or gentle opinion — 'I think it'll…' or 'it looks like…'. This is the everyday, all-purpose way to make what you say sound less certain and a bit softer.",formTable:[{when:"Stem ends in a vowel (verb or adjective)",add:"stem + -ㄹ 것 같아요",ex:"오다 → 올 것 같아요 (it looks like it'll rain)"},{when:"Stem ends in a consonant (verb or adjective)",add:"stem + -을 것 같아요",ex:"먹다 → 먹을 것 같아요 (I think I'll eat it)"},{when:"Stem ends in ㄹ",add:"the ㄹ drops, then add -ㄹ 것 같아요 (so it looks unchanged)",ex:"살다 → 살 것 같아요 (it seems they'll live/stay)"},{when:"Guess about the past",add:"stem + -았/었을 것 같아요",ex:"가다 → 갔을 것 같아요 (I think they already left)"}],examples:[{ko:"오늘 비가 올 것 같아요.",romanization:"oneul biga ol geot gatayo.",en:"I think it'll rain today.",note:"A classic guess from looking at the sky."},{ko:"이 영화 재미있을 것 같아요.",romanization:"i yeonghwa jaemiisseul geot gatayo.",en:"This movie looks like it'll be fun.",note:"재미있다 → 재미있을 것 같아요; a guess about something you haven't seen yet."},{ko:"친구가 집에 없을 것 같아요.",romanization:"chinguga jibe eopseul geot gatayo.",en:"I don't think my friend is home.",note:"없다 → 없을 것 같아요; softens a guess about right now."},{ko:"내일은 시간이 있을 것 같아요.",romanization:"naeireun sigani isseul geot gatayo.",en:"I think I'll have time tomorrow.",note:"있다 → 있을 것 같아요; a gentle 'probably yes' about your own plans."}],keyPoint:{label:"-(으)ㄹ 것 같아요 vs. -는/(으)ㄴ 것 같아요",body:"Use -(으)ㄹ 것 같아요 for the future or something you haven't checked yet (비가 올 것 같아요 = you're looking at the clouds). Use -는 것 같아요 / -(으)ㄴ 것 같아요 for something happening right now or already done that you can sense (비가 오는 것 같아요 = you can hear the rain). The ㄹ form is more of a hunch; the 는/ㄴ form is closer to what you're actually noticing."},pronunciation:"것 같아요 sounds like [걷 까타요]: the final ㅅ of 것 turns into a [t] stop, which tenses the next ㄱ into [ㄲ], so you hear 'geot-kkatayo'.",drill:{instruction:"Make a soft guess with A/V-(으)ㄹ 것 같아요.",model:"비가 오다 → 비가 올 것 같아요.",items:["이 책 재미있다 → ____","내일 친구가 오다 → ____","지금 학교에 사람이 없다 → ____"]},englishSpeakerPitfall:{wrong:"비가 올 것 생각해요.",right:"비가 올 것 같아요.",explanation:"English 'I think' makes you want to grab 생각하다, but for a guess or impression Korean uses the set phrase -(으)ㄹ 것 같아요 ('it seems like'). 생각하다 is for an opinion you actually hold, and it doesn't attach to -(으)ㄹ 것 like this."}},{title:"V/A-나 봐요 / -(으)ㄴ가 봐요",func:"A guess based on something you can see or hear — 'it seems like (because of what I notice)'. Unlike -(으)ㄹ 것 같아요, this one always means you're reading some clue in front of you.",formTable:[{when:"Verb stem (and 있다/없다)",add:"stem + -나 봐요",ex:"오다 → 오나 봐요 (looks like someone's coming)"},{when:"Adjective stem ending in a vowel",add:"stem + -ㄴ가 봐요",ex:"바쁘다 → 바쁜가 봐요 (she seems busy)"},{when:"Adjective stem ending in a consonant",add:"stem + -은가 봐요",ex:"좋다 → 좋은가 봐요 (it seems good)"},{when:"Past tense (verb and adjective)",add:"stem + -았/었나 봐요",ex:"가다 → 갔나 봐요 (looks like they left)"}],examples:[{ko:"친구가 밥을 다 먹었나 봐요.",romanization:"chinguga babeul da meogeonna bwayo.",en:"Looks like my friend finished eating.",note:"먹었 + 나 봐요; you see the empty bowl — a guess from a clue."},{ko:"밖에 비가 오나 봐요.",romanization:"bakke biga ona bwayo.",en:"Looks like it's raining outside.",note:"오다 → 오나 봐요; you hear the sound or see wet umbrellas."},{ko:"선생님이 바쁜가 봐요.",romanization:"seonsaengnimi bappeunga bwayo.",en:"The teacher seems busy.",note:"바쁘다 → 바쁜가 봐요; you can see them rushing around."},{ko:"이 식당 음식이 맛있나 봐요. 사람이 많아요.",romanization:"i sikdang eumsigi masinna bwayo. sarami manayo.",en:"The food here must be good — it's so crowded.",note:"맛있다 takes -나 봐요 like a verb → 맛있나 봐요; the crowd is the clue."}],keyPoint:{label:"-나 봐요 vs. -(으)ㄹ 것 같아요",body:"-나 봐요 needs a real clue and is usually about other people or the world around you, not your own feelings — you wouldn't say 제가 배고프나 봐요 about yourself. -(으)ㄹ 것 같아요 can be a pure hunch with no clue and can be about you too (저 배고플 것 같아요). If you can point to something you noticed, -나 봐요 sounds more natural."},pronunciation:"Past forms like 먹었나 봐요 blend across the seam: 먹었나 comes out as [머건나] (the ㅆ becomes [n] before 나), so you hear 'meo-geon-na bwayo'.",drill:{instruction:"Look at the clue and guess with V/A-나 봐요 / -(으)ㄴ가 봐요.",model:"(우산이 젖었어요) 비가 오다 → 비가 오나 봐요.",items:["(불이 꺼졌어요) 친구가 자다 → ____","(사람이 많아요) 그 영화가 재미있다 → ____","(밥이 없어요) 동생이 다 먹었다 → ____"]},englishSpeakerPitfall:{wrong:"저는 피곤하나 봐요.",right:"저는 피곤한 것 같아요.",explanation:"English 'I guess I'm tired' tempts you to use -나 봐요 about yourself, but this pattern is for guessing about others from an outside clue — you can't 'observe' your own feeling that way. For yourself, use -(으)ㄹ/은 것 같아요 instead."}},{title:"A/V-(으)ㄹ지도 몰라요",func:"Says something 'might' or 'may' happen — a real but uncertain possibility, often one you want the other person to keep in mind, like 'it might rain, so just in case…'.",formTable:[{when:"Stem ends in a vowel (verb or adjective)",add:"stem + -ㄹ지도 몰라요",ex:"오다 → 올지도 몰라요 (it might rain)"},{when:"Stem ends in a consonant (verb or adjective)",add:"stem + -을지도 몰라요",ex:"먹다 → 먹을지도 몰라요 (he might eat)"},{when:"Stem ends in ㄹ",add:"the ㄹ drops, then add -ㄹ지도 몰라요",ex:"멀다 → 멀지도 몰라요 (it might be far)"},{when:"Possibility about the past",add:"stem + -았/었을지도 몰라요",ex:"가다 → 갔을지도 몰라요 (they might have already left)"}],examples:[{ko:"내일 친구가 안 올지도 몰라요.",romanization:"naeil chinguga an oljido mollayo.",en:"My friend might not come tomorrow.",note:"오다 → 올지도; raises a possibility to keep in mind."},{ko:"지금 가면 시간이 없을지도 몰라요.",romanization:"jigeum gamyeon sigani eopseuljido mollayo.",en:"If we go now, we might not have time.",note:"없다 → 없을지도; a heads-up about a risk."},{ko:"그 식당은 벌써 문을 닫았을지도 몰라요.",romanization:"geu sikdangeun beolsseo muneul dadasseuljido mollayo.",en:"That restaurant might have closed already.",note:"닫았 + 을지도 몰라요; a guess about something that may already be true."},{ko:"이 책은 좀 어려울지도 몰라요.",romanization:"i chaegeun jom eoryeouljido mollayo.",en:"This book might be a bit hard.",note:"어렵다 (ㅂ-irregular) → 어려울지도; a gentle heads-up."}],keyPoint:{label:"-(으)ㄹ지도 몰라요 vs. -(으)ㄹ 것 같아요",body:"-(으)ㄹ 것 같아요 leans toward 'probably' — you think it's fairly likely. -(으)ㄹ지도 몰라요 means 'it's just a possibility' — less likely, often flagged as something to watch out for just in case (비가 올 것 같아요 = I expect rain; 비가 올지도 몰라요 = it might rain, so bring an umbrella to be safe)."},pronunciation:"-지도 몰라요 keeps a clear [지도]. 몰라요 comes from 모르다 (모르 + 아요 → 몰라요), said [몰라요] with a strong double ㄹ.",drill:{instruction:"Raise a possibility with A/V-(으)ㄹ지도 몰라요.",model:"내일 비가 오다 → 내일 비가 올지도 몰라요.",items:["친구가 집에 없다 → ____","그 일이 어렵다 → ____","시간이 없다 → ____"]},englishSpeakerPitfall:{wrong:"비가 올 모르다.",right:"비가 올지도 몰라요.",explanation:"몰라요 means 'don't know', so learners try to slot in a bare 모르다 ('비가 올 모르다'). But this is a fixed ending: you need -(으)ㄹ지도 right before 몰라요. And even though 몰라요 is in there, the whole thing is a statement of possibility, not a question — 비가 올지도 몰라요 means 'it might rain', not 'do you know if it'll rain?'"}}],z=[{title:"V-고 있다 — an action in progress",func:"Add -고 있다 to a verb stem to say an action is happening right now. It is the closest match to English 'be -ing' (am/is/are doing).",formTable:[{when:"Any verb stem (vowel or consonant): drop -다, add -고 있다",add:"-고 있다",ex:"먹다 → 먹고 있다 (eating), 보다 → 보고 있다 (watching)"},{when:"Polite present (talking now)",add:"-고 있어요",ex:"읽다 → 읽고 있어요 (am reading)"},{when:"Past — 'was -ing'",add:"-고 있었어요",ex:"자다 → 자고 있었어요 (was sleeping)"}],examples:[{ko:"지금 밥을 먹고 있어요.",romanization:"jigeum babeul meokgo isseoyo.",en:"I'm eating right now.",note:"지금 + -고 있어요 is the go-to pair for something happening this very moment."},{ko:"친구가 책을 읽고 있어요.",romanization:"chinguga chaegeul ikko isseoyo.",en:"My friend is reading a book.",note:"Other people work the same way; just change the subject to 친구가."},{ko:"동생이 영화를 보고 있어요.",romanization:"dongsaengi yeonghwareul bogo isseoyo.",en:"My little brother is watching a movie.",note:"보다 ends in a vowel and still just takes -고 있어요 — the rule never changes."},{ko:"아까 한국어를 공부하고 있었어요.",romanization:"akka hangugeoreul gongbuhago isseosseoyo.",en:"I was studying Korean a little while ago.",note:"-고 있었어요 is the past version: 'was doing.'"}],keyPoint:{label:"-고 있어요 vs. plain -아요/-어요",body:"먹어요 can mean 'I eat (usually)' or even 'I'll eat.' 먹고 있어요 pins it down to 'I'm eating right now.' Reach for -고 있어요 when you want to make clear the action is happening as you speak."},pronunciation:"있어요 runs together as [이써요], and -고 tenses to [꼬] after ㄱ, so 먹고 있어요 sounds like [먹꼬 이써요].",drill:{instruction:"Say what each person is doing right now with -고 있어요.",model:"학생 / 공부하다 → 학생이 공부하고 있어요.",items:["엄마 / 요리하다 → ____","친구 / 물을 마시다 → ____","아빠 / 신문을 보다 → ____"]},englishSpeakerPitfall:{wrong:"Feeling and knowledge verbs can never take -고 있다.",right:"한국어를 좋아해요. / 그 사실을 알고 있어요.",explanation:"For a stable preference, the plain present is usually the natural default: 한국어를 좋아해요. But -고 있다 is not banned with state-like verbs. 알고 있어요 is extremely common, and 좋아하고 있어요 or 사랑하고 있어요 can describe a continuing or developing state when the context calls for it. Choose by meaning, not by a blanket rule."}},{title:"V-는 중이에요 / N 중이에요 — in the middle of",func:"중 means 'the middle of.' Add -는 중이에요 to a verb stem, or just 중이에요 to a noun, to say you're 'in the middle of' something right now.",formTable:[{when:"Verb stem + -는 중이에요 (vowel or consonant stem)",add:"-는 중이에요",ex:"먹다 → 먹는 중이에요 (in the middle of eating)"},{when:"ㄹ-stem verb: drop ㄹ, then add -는 중이에요",add:"-는 중이에요",ex:"만들다 → 만드는 중이에요 (in the middle of making)"},{when:"Noun + 중이에요 (no 을/를)",add:" 중이에요",ex:"회의 → 회의 중이에요 (in a meeting), 공부 → 공부 중이에요"}],examples:[{ko:"지금 밥을 먹는 중이에요.",romanization:"jigeum babeul meongneun jungieyo.",en:"I'm in the middle of eating right now.",note:"-는 중이에요 plays up that you're partway through it, not done."},{ko:"친구를 기다리는 중이에요.",romanization:"chingureul gidarineun jungieyo.",en:"I'm waiting for my friend.",note:"기다리다 ends in a vowel and just takes -는 중이에요."},{ko:"지금 공부 중이에요.",romanization:"jigeum gongbu jungieyo.",en:"I'm studying right now.",note:"With a noun like 공부, drop the verb and say just 'noun + 중이에요' — no 을/를."},{ko:"엄마가 전화 중이에요.",romanization:"eommaga jeonhwa jungieyo.",en:"Mom is on the phone.",note:"전화 중이에요 is the set phrase for 'on the phone.'"}],keyPoint:{label:"-는 중이에요 vs. -고 있어요",body:"Both mean 'be doing.' -는 중이에요 foregrounds an activity or situation as a current phase and is especially natural with bounded actions such as eating or waiting. 한국에 살고 있어요 is the neutral way to say 'I live in Korea'; 한국에 사는 중이에요 is also possible when the speaker deliberately frames living there as a current or temporary stage."},pronunciation:"먹는 → ㄱ before ㄴ turns into [ㅇ] (nasal), so 먹는 sounds like [멍는]: [멍는 중이에요].",drill:{instruction:"Answer '지금 뭐 해요?' saying you're right in the middle of it, with -는 중이에요 or N 중이에요.",model:"밥을 먹다 → 밥을 먹는 중이에요.",items:["책을 읽다 → ____","친구를 만나다 → ____","공부 (noun) → ____"]},englishSpeakerPitfall:{wrong:"밥을 먹는 중에요.",right:"밥을 먹는 중이에요.",explanation:"중 is a noun, so it needs 이에요 after it: 중이에요, not 중에요. Learners drop the 이 because it goes by fast when spoken, but the full form keeps 중 + 이에요."}},{title:"V-는 동안 — while / during",func:"Add -는 동안 to a verb stem to present a time interval in which the main event occurs. The main event may fill all of that interval or occur at some point within it; context determines the amount of overlap.",formTable:[{when:"Verb stem + -는 동안 (vowel or consonant stem)",add:"-는 동안",ex:"먹다 → 먹는 동안 (while eating), 자다 → 자는 동안 (while sleeping)"},{when:"ㄹ-stem verb: drop ㄹ, then add -는 동안",add:"-는 동안",ex:"살다 → 사는 동안 (while living)"},{when:"Noun + 동안 ('for / during' a stretch of time)",add:" 동안",ex:"한 시간 → 한 시간 동안 (for one hour), 방학 → 방학 동안 (during vacation)"}],examples:[{ko:"제가 요리하는 동안 친구는 청소했어요.",romanization:"jega yorihaneun dongan chinguneun cheongsohaesseoyo.",en:"While I cooked, my friend cleaned.",note:"Two people, same time: I cook, my friend cleans."},{ko:"동생이 자는 동안 저는 책을 읽었어요.",romanization:"dongsaengi janeun dongan jeoneun chaegeul ilgeosseoyo.",en:"While my little brother was sleeping, I read a book.",note:"자다 → 자는 동안. The main verb (past) tells you when it all happened."},{ko:"밥을 먹는 동안 영화를 봤어요.",romanization:"babeul meongneun dongan yeonghwareul bwasseoyo.",en:"I watched a movie while I ate.",note:"One person doing both at once is fine too."},{ko:"방학 동안 한국어를 공부할 거예요.",romanization:"banghak dongan hangugeoreul gongbuhal geoyeyo.",en:"I'll study Korean during the vacation.",note:"With a noun like 방학, use just 'noun + 동안' for 'during / for' that time."}],keyPoint:{label:"-는 동안 (always 는) vs. -(으)ㄹ 때",body:"-는 동안 always keeps -는, no matter the tense, because it marks an interval. 때 ('when') can point to a moment or occasion, while 동안 foregrounds the containing stretch of time. The main event may fill the interval or happen at a point within it."},pronunciation:"먹는 동안 → 먹는 nasalizes to [멍는] (ㄱ+ㄴ → ㅇ+ㄴ), so it's [멍는 동안].",drill:{instruction:"Join the two halves with -는 동안 to mean 'while ___, ___.'",model:"제가 자다 / 엄마가 요리하다 → 제가 자는 동안 엄마가 요리했어요.",items:["친구가 전화하다 / 저는 밥을 먹다 → ____","제가 공부하다 / 동생이 게임하다 → ____","비가 오다 / 우리는 집에 있다 → ____"]},englishSpeakerPitfall:{wrong:"밥을 먹었는 동안 영화를 봤어요.",right:"밥을 먹는 동안 영화를 봤어요.",explanation:"English puts 'while' on a past verb ('while I ate'), so learners add 었 before 동안. In Korean, -는 동안 stays in the -는 form no matter the tense — only the main clause shows past."}}],T=[{title:"V-고 나서 — after finishing, then",func:'V-고 나서 means "after doing V (and finishing it)." It tells the listener that the first action is done before the next one starts. Usually the same person does both actions.',formTable:[{when:"Verb stem ending in a vowel",add:"-고 나서",ex:"보다 → 보고 나서, 자다 → 자고 나서"},{when:"Verb stem ending in a consonant",add:"-고 나서",ex:"먹다 → 먹고 나서, 씻다 → 씻고 나서"},{when:"ㄹ-final stems (nothing drops here)",add:"-고 나서",ex:"놀다 → 놀고 나서, 만들다 → 만들고 나서"},{when:"Never put past tense on this verb",add:'keep the stem plain — 나서 already means "after"',ex:"먹었고 나서 (X) → 먹고 나서 (O)"}],examples:[{ko:"밥을 먹고 나서 이를 닦아요.",romanization:"bap-eul meokgo naseo i-reul dakkayo.",en:"After I eat, I brush my teeth.",note:"Eating finishes first, then the next thing starts."},{ko:"숙제를 하고 나서 친구를 만났어요.",romanization:"sukje-reul hago naseo chingu-reul mannasseoyo.",en:"After I did my homework, I met a friend.",note:"The past tense goes only on the last verb (만났어요), not on 하다."},{ko:"손을 씻고 나서 밥을 먹어요.",romanization:"son-eul ssitgo naseo bap-eul meogeoyo.",en:"After I wash my hands, I eat.",note:"Same person does both — the usual case for -고 나서."},{ko:"이 책을 읽고 나서 영화를 볼 거예요.",romanization:"i chaek-eul ilkko naseo yeonghwa-reul bol geoyeyo.",en:"After I finish this book, I'm going to watch a movie.",note:"Works for plans too. 읽고 sounds like [일꼬]. The reading has to finish first."}],keyPoint:{label:"-고 나서 vs. plain -고",body:`Plain -고 just links two actions like "and": 밥을 먹고 이를 닦아요 (I eat and brush my teeth). Adding 나서 puts the spotlight on finishing the first one before starting the next. Reach for -고 나서 when you want "after I'm done with this, then that."`},pronunciation:"You hear it as [고 나서]. Note that 고 tenses after a stem ending in a stop sound: 먹고 나서 sounds like [먹꼬 나서], 받고 나서 like [받꼬 나서]. After a vowel (보고 나서) it stays soft. Keep 나서 light so it links right on.",drill:{instruction:"Join the two actions into one sentence with V-고 나서, in the 해요 form.",model:"손을 씻다 + 밥을 먹다 → 손을 씻고 나서 밥을 먹어요.",items:["운동하다 + 샤워하다 → ____","책을 읽다 + 자다 → ____","청소하다 + 친구를 만나다 → ____"]},englishSpeakerPitfall:{wrong:"밥을 먹었고 나서 이를 닦아요.",right:"밥을 먹고 나서 이를 닦아요.",explanation:'"After I ate" feels past in English, so people add -었- to the first verb. But 나서 already carries "after finishing," so the first verb stays a plain stem. Only the last verb shows the real tense.'}},{title:"V-자마자 — as soon as",func:'V-자마자 means "as soon as / the moment V happens." The second thing comes right after the first, with no time in between. The two halves can have the same person or different ones.',formTable:[{when:"Verb stem ending in a vowel",add:"-자마자",ex:"오다 → 오자마자, 보다 → 보자마자"},{when:"Verb stem ending in a consonant",add:"-자마자",ex:"듣다 → 듣자마자, 끝나다 → 끝나자마자"},{when:"ㄹ-final stems (nothing drops here)",add:"-자마자",ex:"열다 → 열자마자, 울다 → 울자마자"},{when:"Never put past tense on this verb",add:"keep the stem plain — tense goes on the second half only",ex:"왔자마자 (X) → 오자마자 (O)"}],examples:[{ko:"집에 오자마자 손을 씻어요.",romanization:"jib-e ojamaja son-eul ssiseoyo.",en:"As soon as I get home, I wash my hands.",note:"No gap — the washing happens the instant you walk in."},{ko:"영화가 끝나자마자 집에 갔어요.",romanization:"yeonghwa-ga kkeunnajamaja jib-e gasseoyo.",en:"As soon as the movie ended, I went home.",note:"Here the two halves have different subjects (the movie / I)."},{ko:"학교에 도착하자마자 친구한테 전화했어요.",romanization:"hakgyo-e dochakajamaja chingu-hante jeonhwahaesseoyo.",en:"As soon as I got to school, I called my friend.",note:"Past tense shows up only on the second verb (전화했어요)."},{ko:"침대에 눕자마자 잤어요.",romanization:"chimdae-e nupjamaja jasseoyo.",en:"As soon as I lay down, I fell asleep.",note:"An immediate, almost automatic reaction with no delay."}],keyPoint:{label:"-자마자 vs. -고 나서",body:`Both put one action before another, but the timing is different. -고 나서 is "after finishing," and a pause is fine: 밥을 먹고 나서 좀 쉬었어요 (I ate, then rested a bit). -자마자 is "the very moment," no gap at all: 집에 오자마자 잤어요 (got home and went straight to sleep). Use -자마자 only when there's truly no time in between.`},pronunciation:"You hear it as [자마자], three even, light beats. After a stem ending in a stop sound it tenses a little: 듣자마자 sounds like [듣짜마자], 눕자마자 like [눕짜마자]. After a vowel (오자마자) it stays soft. No pause before it.",drill:{instruction:"Join the two actions into one sentence with V-자마자.",model:"집에 오다 + 손을 씻다 → 집에 오자마자 손을 씻어요.",items:["일어나다 + 물을 마시다 → ____","수업이 끝나다 + 집에 가다 → ____","친구를 보다 + 웃다 → ____"]},englishSpeakerPitfall:{wrong:"집에 왔자마자 손을 씻었어요.",right:"집에 오자마자 손을 씻었어요.",explanation:'"As soon as I came home" is past in English, so people add -았/었- to the first verb. In Korean, 자마자 sticks to the plain stem (오-), never a past form. Put the past tense only on the second verb (씻었어요).'}}],P=[{title:"V-다가 — break off one action to do another",func:"V-다가 says you were in the middle of one action when you stopped partway and switched to (or got interrupted by) a second one. The first action does not finish — you break off from it. When both clauses describe intentional actions, their subject is normally the same; an unplanned event can instead be the second-clause subject (밥을 먹다가 전화가 왔어요).",formTable:[{when:"Add straight to the plain verb stem (no vowel change, same after vowel or consonant)",add:"-다가",ex:"가다 → 가다가, 먹다 → 먹다가, 자다 → 자다가"},{when:"Often cut to just -다 in everyday speech",add:"-다",ex:"집에 가다가 → 집에 가다 (친구를 만났어요)"},{when:"Past stem -았/었다가 = first action was finished, then undone or reversed",add:"-았다가 / -었다가",ex:"앉다 → 앉았다가 (일어났어요), 사다 → 샀다가 (환불했어요)"}],examples:[{ko:"학교에 가다가 친구를 만났어요.",romanization:"hakgyoe gadaga chingureul mannasseoyo.",en:"I was on my way to school and ran into a friend.",note:"The going gets cut off partway by something you didn't plan."},{ko:"숙제를 하다가 잠이 들었어요.",romanization:"sukjereul hadaga jami deureosseoyo.",en:"I was doing my homework and fell asleep.",note:"You stop the homework because the second thing happens to you."},{ko:"밥을 먹다가 전화를 받았어요.",romanization:"babeul meokdaga jeonhwareul badasseoyo.",en:"I was eating and then took a phone call.",note:"Same person breaks off from eating to do the next thing."},{ko:"이 책을 샀다가 환불했어요.",romanization:"i chaegeul satdaga hwanbulhaesseoyo.",en:"I bought this book and then returned it.",note:"-았다가 shows the buying was finished, then reversed."}],keyPoint:{label:"V-다가 vs. V-고 나서",body:"V-고 나서 means you finish the first thing all the way, then do the next (밥을 먹고 나서 = after you're done eating). V-다가 means the first thing gets cut off in the middle and you switch (밥을 먹다가 = you were still eating and then stopped to...). 다가 = broke off; 고 나서 = finished."},pronunciation:"다가 is said plainly as [다가]. In -았다가/-었다가 the ㅆ makes the ㄷ tense, so 샀다가 sounds like [삳따가].",drill:{instruction:"Join the two actions into one sentence with V-다가, so the first action gets interrupted by the second.",model:"집에 가다 / 친구를 만나다 → 집에 가다가 친구를 만났어요.",items:["텔레비전을 보다 / 자다 → ___","음악을 듣다 / 친구한테서 전화가 오다 → ___","공부를 하다 / 배가 고프다 → ___"]},englishSpeakerPitfall:{wrong:"숙제를 하고 잠이 들었어요. (meant: I fell asleep WHILE doing homework)",right:"숙제를 하다가 잠이 들었어요.",explanation:'English "and then" hides whether action 1 finished. -고 just lists things in order and sounds like you finished the homework. To say you broke off in the middle of it, you need -다가.'}},{title:"V-아/어 있다 — a state that stays after the action",func:"V-아/어 있다 describes the state that is left over after an action is done. The action already happened, and the subject stays in that result (앉아 있다 = is sitting, having sat down). It goes with verbs that leave a state behind, like 앉다, 서다, 오다, 열리다.",formTable:[{when:"Stem vowel is ㅏ or ㅗ",add:"-아 있다",ex:"앉다 → 앉아 있다, 오다 → 와 있다"},{when:"Any other stem vowel",add:"-어 있다",ex:"서다 → 서 있다, 열리다 → 열려 있다"},{when:"Passive / result verbs work too (the door opens, the light comes on)",add:"-아/어 있다",ex:"켜지다 → 켜져 있다, 쓰이다 → 쓰여 있다"}],examples:[{ko:"친구가 의자에 앉아 있어요.",romanization:"chinguga uijae anja isseoyo.",en:"My friend is sitting on the chair.",note:"They sat down earlier and are still in the seated state now."},{ko:"문이 열려 있어요.",romanization:"muni yeollyeo isseoyo.",en:"The door is open.",note:"Someone opened it before and it stays open — a lasting result. Note 열리다 (opens), not 열다 (open it)."},{ko:"칠판에 이름이 쓰여 있어요.",romanization:"chilpane ireumi sseuyeo isseoyo.",en:"A name is written on the board.",note:"Someone wrote it earlier; the result (the name being there) stays. Use the passive 쓰이다 → 쓰여 있다."},{ko:"동생이 아직 학교에 가 있어요.",romanization:"dongsaengi ajik hakgyoe ga isseoyo.",en:"My younger sibling is still at school (went and is there).",note:"가 있다 = went and is staying there, not the act of going."}],keyPoint:{label:"V-아/어 있다 vs. V-고 있다",body:"V-고 있다 = an action happening right now (앉고 있어요 = is in the middle of sitting down). V-아/어 있다 = the state after it's done (앉아 있어요 = is already seated and staying that way). Use -아/어 있다 for the leftover result, -고 있다 for the action in progress."},pronunciation:"앉아 있어요 links across the words — the ㅈ carries over, so it sounds like [안자 이써요]. 열려 있어요 sounds like [열려 이써요].",drill:{instruction:"Answer that the subject is right now in the result state, using V-아/어 있다.",model:"의자에 앉다 → 의자에 앉아 있어요.",items:["창문이 열리다 → ___","친구가 집에 오다 → ___","학생들이 서다 → ___"]},englishSpeakerPitfall:{wrong:"문이 열고 있어요. (meant: The door is open)",right:"문이 열려 있어요.",explanation:'English "is open" looks like a -ing form, which tempts -고 있다. But -고 있다 means the action is happening now. A door just staying open is a result state, so you need -아/어 있다 — and with the intransitive 열리다 (opens), not 열다 (open it).'}}],S=[{title:"V/A-아서/어서 — because, so",func:`Use -아서/어서 to link a reason to its result: the first part is the cause, the second is what comes from it. It's the everyday, neutral way to say "because" or "so."`,formTable:[{when:"Stem vowel is ㅏ or ㅗ",add:"-아서",ex:"가다 → 가서, 좋다 → 좋아서"},{when:"Any other stem vowel",add:"-어서",ex:"먹다 → 먹어서, 없다 → 없어서"},{when:"하다 verbs/adjectives",add:"→ 해서",ex:"공부하다 → 공부해서, 피곤하다 → 피곤해서"},{when:"Noun + 이다",add:"-라서/이라서",ex:"학생이다 → 학생이라서, 친구다 → 친구라서"}],examples:[{ko:"배가 고파서 밥을 먹었어요.",romanization:"bae-ga go-pa-seo bap-eul meo-geo-sseo-yo.",en:"I was hungry, so I ate.",note:"고프다 (hungry) is the cause; eating is the result."},{ko:"시간이 없어서 못 갔어요.",romanization:"si-gan-i eop-seo-seo mot ga-sseo-yo.",en:"I had no time, so I couldn't go.",note:"A reason for not doing something — a very common pattern."},{ko:"친구를 만나서 영화를 봤어요.",romanization:"chin-gu-reul man-na-seo yeong-hwa-reul bwa-sseo-yo.",en:"I met my friend and (we) watched a movie.",note:"Here -아서 instead links two connected actions in order, not cause and result. Same form, different job."},{ko:"한국어가 재미있어서 매일 공부해요.",romanization:"han-gu-geo-ga jae-mi-i-sseo-seo mae-il gong-bu-hae-yo.",en:"Korean is fun, so I study it every day.",note:"An adjective as the reason; the result is a habit."}],keyPoint:{label:"Tense goes on the last verb only",body:"Don't put past tense before -아서/어서. Say 고파서 먹었어요 (not 고팠어서). The part before -아서/어서 stays plain, and when something happened is shown only on the final verb."},pronunciation:"없어서 is read [업써서]: the ㅄ batchim links over, so ㅅ moves to the next syllable and tenses to [써].",drill:{instruction:"Join the two ideas with -아서/어서 to show reason → result.",model:"비가 오다 / 집에 있었어요 → 비가 와서 집에 있었어요.",items:["배가 아프다 / 병원에 갔어요 → ____","날씨가 좋다 / 산책했어요 → ____","돈이 없다 / 못 샀어요 → ____"]},englishSpeakerPitfall:{wrong:"어제 바빴어서 못 왔어요.",right:"어제 바빠서 못 왔어요.",explanation:`English puts past tense on the "because" part ("because I was busy"), but Korean doesn't add past tense before -아서/어서. The tense shows up once, on the final verb.`}},{title:"V-는 바람에 — because of (something unexpected)",func:'Use -는 바람에 when an unplanned or unwanted event causes a result — usually a bad one. It carries the feeling of "and because of that, things went wrong."',formTable:[{when:"Verb stem (any)",add:"-는 바람에",ex:"늦다 → 늦는 바람에, 오다 → 오는 바람에"},{when:"Stem ending in ㄹ (drop the ㄹ)",add:"-는 바람에",ex:"울다 → 우는 바람에, 놀다 → 노는 바람에"},{when:"Result part",add:"usually past tense",ex:"늦잠을 자는 바람에 학교에 늦었어요."},{when:"Adjectives / nouns",add:"not used",ex:"(use 때문에 instead)"}],examples:[{ko:"늦잠을 자는 바람에 학교에 늦었어요.",romanization:"neut-jam-eul ja-neun ba-ram-e hak-gyo-e neu-jeo-sseo-yo.",en:"I overslept, so I was late for school.",note:"Oversleeping is an unintended event with a bad result."},{ko:"비가 오는 바람에 옷이 다 젖었어요.",romanization:"bi-ga o-neun ba-ram-e o-si da jeo-jeo-sseo-yo.",en:"It started raining, so my clothes got all wet.",note:"Sudden rain disrupts things — a classic 바람에 use."},{ko:"친구가 전화하는 바람에 잠을 못 잤어요.",romanization:"chin-gu-ga jeon-hwa-ha-neun ba-ram-e ja-meul mot ja-sseo-yo.",en:"My friend called, so I couldn't sleep.",note:"Someone else's action disrupts the speaker; the result is negative."},{ko:"버스를 놓치는 바람에 약속에 늦었어요.",romanization:"beo-seu-reul no-chi-neun ba-ram-e yak-sok-e neu-jeo-sseo-yo.",en:"I missed the bus, so I was late for the meet-up.",note:"Unexpected cause + unwanted result, both verbs."}],keyPoint:{label:"-는 바람에 vs -아서/어서",body:`-아서/어서 is neutral and works for any reason. -는 바람에 adds the feeling "and this unexpected thing messed things up," so the result is almost always bad and in the past. Don't use 바람에 for a planned action or a good outcome: say 열심히 공부해서 합격했어요 (not 공부하는 바람에).`},pronunciation:"늦는 is read [는는]: the ㅈ batchim is realized as [ㄷ] in coda position, then nasalizes to [ㄴ] before the ㄴ of 는. Read 늦는 바람에 as [는는 바라메].",drill:{instruction:"Connect the unexpected cause to its bad result with -는 바람에.",model:"길이 막히다 / 약속에 늦었어요 → 길이 막히는 바람에 약속에 늦었어요.",items:["갑자기 비가 오다 / 우산을 샀어요 → ____","동생이 울다 / 공부를 못 했어요 → ____","지하철이 고장 나다 / 학교에 늦었어요 → ____"]},englishSpeakerPitfall:{wrong:"열심히 공부하는 바람에 시험을 잘 봤어요.",right:"열심히 공부해서 시험을 잘 봤어요.",explanation:"-는 바람에 is only for unwanted disruptions, so it clashes with a good result like doing well on a test. For an intended cause and a good outcome, use -아서/어서."}},{title:"N 때문에 — because of (a noun)",func:'Use a noun + 때문에 to point to a person, thing, or situation as the cause. It means "because of ~" and is followed by a result.',formTable:[{when:"Noun + 때문에",add:"때문에",ex:"비 → 비 때문에, 일 → 일 때문에"},{when:"Noun ends in any sound",add:"no 이/가 added",ex:"친구 → 친구 때문에, 돈 → 돈 때문에"},{when:"Person as the cause",add:"때문에",ex:"동생 → 동생 때문에"},{when:'"because it is / I am ~"',add:"(이)라서 or (이)기 때문에",ex:"주말이라서, 학생이기 때문에"}],examples:[{ko:"비 때문에 학교에 못 갔어요.",romanization:"bi ttae-mu-ne hak-gyo-e mot ga-sseo-yo.",en:"Because of the rain, I couldn't go to school.",note:"비 (a noun) is the cause; 때문에 attaches straight to it."},{ko:"일 때문에 친구를 못 만났어요.",romanization:"il ttae-mu-ne chin-gu-reul mot man-na-sseo-yo.",en:"Because of work, I couldn't meet my friend.",note:"An everyday noun cause with a negative result."},{ko:"동생 때문에 화가 났어요.",romanization:"dong-saeng ttae-mu-ne hwa-ga na-sseo-yo.",en:"I got mad because of my little brother.",note:"A person as the cause — often blame or trouble."},{ko:"돈 때문에 여행을 못 가요.",romanization:"don ttae-mu-ne yeo-haeng-eul mot ga-yo.",en:"Because of money, I can't go on a trip.",note:"때문에 takes a bare noun, with no verb on the cause."}],keyPoint:{label:"때문에 vs 아서/어서",body:"때문에 follows a NOUN (비 때문에), while -아서/어서 follows a VERB or ADJECTIVE (비가 와서). Same meaning, just attached to a different kind of word. So if you have a noun, reach for 때문에; if you have a verb or adjective, use -아서/어서."},pronunciation:"때 starts with the tense consonant ㄸ — say it hard and tight, not as a soft [대].",drill:{instruction:"Use N + 때문에 to give the reason for each result.",model:"(눈) 길이 미끄러웠어요 → 눈 때문에 길이 미끄러웠어요.",items:["(시험) 어제 잠을 못 잤어요 → ____","(돈) 여행을 못 가요 → ____","(친구) 영화를 늦게 봤어요 → ____"]},englishSpeakerPitfall:{wrong:"비가 오다 때문에 못 갔어요.",right:"비 때문에 못 갔어요. / 비가 와서 못 갔어요.",explanation:"때문에 attaches to a noun, not a verb. Use the bare noun (비 때문에), or switch to the verb form with -아서/어서 (비가 와서). Don't stick a verb directly in front of 때문에."}}],A=[{title:"V-기 위해서 / N을 위해서 — in order to, for the sake of",func:'Shows purpose. The goal comes first, then the action you take to reach it. Use V-기 위해서 with a verb ("in order to do X") and N을/를 위해서 with a noun ("for N").',formTable:[{when:"Any verb stem",add:"-기 위해서",ex:"먹다 → 먹기 위해서 / 사다 → 사기 위해서"},{when:"Noun ending in a consonant",add:"을 위해서",ex:"건강 → 건강을 위해서"},{when:"Noun ending in a vowel",add:"를 위해서",ex:"친구 → 친구를 위해서"},{when:"Shorter form (writing or quick speech)",add:"-기 위해 / N을 위해",ex:"건강을 위해 운동해요"}],examples:[{ko:"한국어를 배우기 위해서 한국에 왔어요.",romanization:"hangugeoreul baeugi wihaeseo hanguge wasseoyo.",en:"I came to Korea to learn Korean.",note:"-기 위해서 goes on the verb 배우다 to give the reason for coming."},{ko:"돈을 모으기 위해서 아르바이트를 해요.",romanization:"doneul moeugi wihaeseo areubaiteureul haeyo.",en:"I work a part-time job to save money.",note:"The goal (saving money) comes first, the action (working) second."},{ko:"가족을 위해서 매일 열심히 일해요.",romanization:"gajogeul wihaeseo maeil yeolsimhi ilhaeyo.",en:"I work hard every day for my family.",note:"가족 is a noun, so it takes 을 위해서, not 기 위해서."},{ko:"건강을 위해서 물을 많이 마셔요.",romanization:"geongangeul wihaeseo mureul mani masyeoyo.",en:"I drink a lot of water for my health.",note:"건강 ends in a consonant, so it takes 을 위해서."}],keyPoint:{label:"Verb goal vs. noun goal",body:`For a verb goal, use V-기 위해서 (배우기 위해서 = in order to learn). For a noun goal, use N을/를 위해서 (가족을 위해서 = for my family). Keep the particle 을/를 before 위해서 with a noun — don't drop it. Later you'll meet V-(으)려고, a more casual "in order to" that only works with verbs.`},pronunciation:"위해서 is often shortened to 위해 in writing and quick speech; both sound natural. 모으기 keeps each syllable clear: [모으기].",drill:{instruction:"Join the goal and the action into one sentence using V-기 위해서 or N을 위해서.",model:"한국 친구를 사귀다 + 한국어를 공부해요 → 한국 친구를 사귀기 위해서 한국어를 공부해요.",items:["시험을 잘 보다 + 매일 공부해요 → 시험을 잘 보___ ___ 매일 공부해요.","부모님 + 선물을 샀어요 → 부모님___ ___ 선물을 샀어요.","살을 빼다 + 운동을 시작했어요 → 살을 빼___ ___ 운동을 시작했어요."]},englishSpeakerPitfall:{wrong:"가족 위해서 일해요 / 건강 배우기 위해서",right:"가족을 위해서 일해요 / 건강을 위해서",explanation:'English uses "for" with both nouns and the "-ing" form, so learners mix them up. Korean splits them: a verb takes -기 위해서, a noun takes 을/를 위해서. Keep the particle 을/를 before 위해서 with a noun, and never put -기 on a noun.'}},{title:"N 동안 — for / during N (a length of time)",func:'Goes right onto a time-span noun to mean "for" or "during" that period. It tells you how long something lasts.',formTable:[{when:"Number + counter",add:"동안 (no particle)",ex:"세 시간 → 세 시간 동안"},{when:"Period noun",add:"동안",ex:"방학 → 방학 동안 / 일주일 → 일주일 동안"},{when:'"the whole ~" (stronger)',add:"내내",ex:"하루 종일 / 일 년 내내"},{when:'"how long"',add:"얼마 동안",ex:"얼마 동안 한국에 살았어요?"}],examples:[{ko:"세 시간 동안 공부했어요.",romanization:"se sigan dongan gongbuhaesseoyo.",en:"I studied for three hours.",note:"동안 goes straight onto the duration 세 시간 with no extra particle."},{ko:"방학 동안 부모님 집에 있었어요.",romanization:"banghak dongan bumonim jibe isseosseoyo.",en:"I stayed at my parents' house during the vacation.",note:'방학 is a period, so N 동안 means "during" the whole break.'},{ko:"일주일 동안 한국어를 배웠어요.",romanization:"iljuil dongan hangugeoreul baewosseoyo.",en:"I learned Korean for one week.",note:"일주일 (one week) is a span, so 동안 gives its length."},{ko:"얼마 동안 한국에 살았어요?",romanization:"eolma dongan hanguge sarasseoyo?",en:"How long did you live in Korea?",note:"얼마 동안 asks about length of time, not a clock time."}],keyPoint:{label:"동안 vs. 에 vs. 까지",body:"N 동안 = how long something lasts (세 시간 동안 = for three hours). N 에 = a point in time (세 시에 = at three). N 까지 = a deadline (세 시까지 = by three). Use 동안 only for a stretch of time, never a single moment."},pronunciation:"동안 is [동안]. 일주일 is [일쭈일]; in careful speech say [일쭈일 동안]. Some speakers may tense 동안 to [똥안] in connected speech, but this is not liaison of final ㄹ.",drill:{instruction:"Add the time noun + 동안 to finish each sentence.",model:"(한 시간) ___ 친구를 기다렸어요. → 한 시간 동안 친구를 기다렸어요.",items:["(이틀) ___ 비가 왔어요. → 이틀 ___ 비가 왔어요.","(방학) ___ 여행을 갔어요. → 방학 ___ 여행을 갔어요.","(얼마) ___ 한국에서 살았어요? → 얼마 ___ 한국에서 살았어요?"]},englishSpeakerPitfall:{wrong:"세 시간에 공부했어요 / 세 시간을 공부했어요",right:"세 시간 동안 공부했어요",explanation:'English says "for" with durations, but learners often reach for 에 or 을/를 out of habit. For "how long," use 동안 with no particle on the time span. Save 에 for a clock time (세 시에 = at 3:00).'}},{title:"V-는 동안 — while V is happening",func:'Goes on a verb to mean "while (someone) is doing X." It marks a stretch of time set by one ongoing action, during which something else happens.',formTable:[{when:"Action verb stem",add:"-는 동안",ex:"먹다 → 먹는 동안 / 자다 → 자는 동안"},{when:"Stem ending in ㄹ",add:"ㄹ 탈락 + -는 동안",ex:"살다 → 사는 동안 / 만들다 → 만드는 동안"},{when:"Two different subjects (common)",add:"A가 V-는 동안 B가 …",ex:"엄마가 자는 동안 청소했어요"},{when:"Same subject (also fine)",add:"V-는 동안 …",ex:"밥을 먹는 동안 텔레비전을 봤어요"}],examples:[{ko:"제가 요리하는 동안 친구가 청소했어요.",romanization:"jega yorihaneun dongan chinguga cheongsohaesseoyo.",en:"While I cooked, my friend cleaned.",note:"-는 동안 on 요리하다 sets the time frame; the two subjects (제가 / 친구가) are different."},{ko:"아기가 자는 동안 책을 읽었어요.",romanization:"agiga janeun dongan chaegeul ilgeosseoyo.",en:"While the baby was sleeping, I read a book.",note:"자다 → 자는 동안; one action (sleeping) frames the other (reading)."},{ko:"제가 한국에 사는 동안 친구를 많이 사귀었어요.",romanization:"jega hanguge saneun dongan chingureul mani sagwieosseoyo.",en:"While I lived in Korea, I made a lot of friends.",note:"살다 drops ㄹ before -는: 살다 → 사는 동안."},{ko:"밥을 먹는 동안 텔레비전을 봤어요.",romanization:"babeul meongneun dongan tellebijeoneul bwasseoyo.",en:"While I ate, I watched TV.",note:"Same subject is fine too; 먹다 → 먹는 동안 frames both actions in one time span."}],keyPoint:{label:"V-는 동안 vs. N 동안",body:"Same word 동안, two ways to attach it. N 동안 takes a time noun (방학 동안 = during vacation). V-는 동안 takes a verb in the -는 form (밥을 먹는 동안 = while eating). If a verb names the time span, you must use -는 동안 — never put 동안 onto the dictionary form."},pronunciation:"먹는 동안 → [멍는 동안] (ㄱ before ㄴ turns into ㅇ). 사는 동안 has no cluster and stays smooth.",drill:{instruction:"Change the verb to V-는 동안 and finish the sentence.",model:"(제가 샤워하다) ___ 전화가 왔어요. → 제가 샤워하는 동안 전화가 왔어요.",items:["(아기가 자다) ___ 책을 읽었어요. → 아기가 ___ 책을 읽었어요.","(엄마가 요리하다) ___ 저는 상을 차렸어요. → 엄마가 ___ 저는 상을 차렸어요.","(제가 한국에 살다) ___ 한국어를 배웠어요. → 제가 한국에 ___ 한국어를 배웠어요."]},englishSpeakerPitfall:{wrong:"먹다 동안 / 먹었는 동안 텔레비전을 봤어요",right:"먹는 동안 텔레비전을 봤어요",explanation:`"While" describes an ongoing action, so Korean uses the present -는 form even about the past — the past tense stays on the final verb only. Don't put 동안 on the dictionary form (먹다 동안), and don't make the 동안 clause past (먹었는 동안).`}}],N=[{title:"V-기로 했어요 — decided to V",func:"Used to say you have decided or made up your mind to do something. Often the decision was made after thinking it over or agreeing with other people.",formTable:[{when:"Verb stem ending in a vowel",add:"stem + 기로 했어요",ex:"가다 → 가기로 했어요 (decided to go)"},{when:"Verb stem ending in a consonant",add:"stem + 기로 했어요",ex:"먹다 → 먹기로 했어요 (decided to eat)"},{when:"Decided NOT to do it",add:"안 + V-기로 했어요 (or stem + 지 않기로 했어요)",ex:"마시다 → 안 마시기로 했어요 (decided not to drink)"}],examples:[{ko:"내일부터 한국어를 공부하기로 했어요.",romanization:"naeil-buteo hangugeo-reul gongbuhagiro haesseoyo.",en:"I decided to study Korean starting tomorrow.",note:"공부하다 → 공부하기로 했어요; an everyday verb plus a personal decision."},{ko:"친구하고 같이 영화를 보기로 했어요.",romanization:"chinguhago gachi yeonghwa-reul bogiro haesseoyo.",en:"My friend and I decided to watch a movie together.",note:"보다 → 보기로 했어요; a decision made together with someone (친구하고)."},{ko:"오늘부터 물을 많이 마시기로 했어요.",romanization:"oneul-buteo mul-eul mani masigiro haesseoyo.",en:"I decided to drink a lot of water from today.",note:"마시다 → 마시기로 했어요; a simple self-improvement plan."},{ko:"저녁에는 밥을 안 먹기로 했어요.",romanization:"jeonyeog-eneun bab-eul an meokgiro haesseoyo.",en:"I decided not to eat dinner.",note:"Negative: 안 먹기로 했어요, for deciding NOT to do something."}],keyPoint:{label:"-기로 했어요 (a decision) vs. -(으)ㄹ 거예요 (a plan)",body:"-기로 했어요 stresses that you reached a decision, often after thinking or agreeing with others. -(으)ㄹ 거예요 just says what you are going to do. 했어요 is past because the deciding already happened, even though the action itself is still coming up. (The negative -지 않기로 했어요 comes later.)"},pronunciation:"먹기로 sounds like [먹끼로] (meok-kkiro): after the ㄱ at the end of 먹, the next ㄱ becomes a tense [ㄲ].",drill:{instruction:"Turn each cue into a sentence saying you decided to do it, using V-기로 했어요.",model:"한국어를 공부하다 → 한국어를 공부하기로 했어요.",items:["매일 운동하다 → ____________","친구를 만나다 → ____________","커피를 안 마시다 → ____________"]},englishSpeakerPitfall:{wrong:"공부하기로 해요.",right:"공부하기로 했어요.",explanation:"The decision was already made, so 하다 stays past (했어요), not present (해요). English 'I decided' is past, and Korean keeps it past too."}},{title:"V-게 됐어요 — ended up V-ing / came to V",func:"Used when something happens because of circumstances rather than your own choice. It shows a change or a result that came about, often through other people or how things worked out.",formTable:[{when:"Verb stem ending in a vowel",add:"stem + 게 됐어요",ex:"가다 → 가게 됐어요 (ended up going)"},{when:"Verb stem ending in a consonant",add:"stem + 게 됐어요",ex:"살다 → 살게 됐어요 (ended up living)"},{when:"With a negative (못/안)",add:"못/안 + V-게 됐어요",ex:"먹다 → 못 먹게 됐어요 (ended up not being able to eat)"}],examples:[{ko:"일 때문에 한국에 살게 됐어요.",romanization:"il ttaemune hanguge salge dwaesseoyo.",en:"I ended up living in Korea because of work.",note:"살다 → 살게 됐어요; 일 때문에 shows an outside reason, not a personal choice."},{ko:"친구 덕분에 한국 영화를 좋아하게 됐어요.",romanization:"chingu deokbune hanguk yeonghwa-reul joahage dwaesseoyo.",en:"Thanks to my friend, I came to like Korean movies.",note:"좋아하다 → 좋아하게 됐어요; a feeling that changed because of someone else."},{ko:"시간이 없어서 밥을 못 먹게 됐어요.",romanization:"sigani eopseoseo bab-eul mot meokge dwaesseoyo.",en:"I ended up not being able to eat because I had no time.",note:"못 먹다 → 못 먹게 됐어요; the situation (시간이 없어서) caused the result."},{ko:"그 학교에 다니게 됐어요.",romanization:"geu hakgyoe danige dwaesseoyo.",en:"I ended up going to that school.",note:"다니다 → 다니게 됐어요; announces a new situation that came about, often happy news."}],keyPoint:{label:"-기로 했어요 (my choice) vs. -게 됐어요 (not my choice)",body:"-기로 했어요 means 'I decided' — the will is yours. -게 됐어요 means 'it came about' — the result is from circumstances or other people. Koreans often use -게 됐어요 to sound modest, even with good news (for example, 결혼하게 됐어요, 'I'm getting married')."},pronunciation:"좋아하게 sounds like [조아하게] (jo-a-ha-ge): the ㅎ in 좋 goes silent before the vowel, so 좋아 links smoothly.",drill:{instruction:"Rewrite each cue to say it came about by circumstances, using V-게 됐어요.",model:"한국에 살다 → 한국에 살게 됐어요.",items:["한국어를 배우다 → ____________","그 회사에서 일하다 → ____________","그 사람을 만나다 → ____________"]},englishSpeakerPitfall:{wrong:"한국에 살게 해요.",right:"한국에 살게 됐어요.",explanation:"Don't mix up 되다 (to become / come about) with 하다. For 'I ended up living,' use 되다 → 됐어요. 살게 해요 means 'make someone live' — a different grammar point."}},{title:"A-아/어졌어요 — became / got (a change of state)",func:"Added to adjectives to say a state changed — something 'became' or 'got' a certain way. It turns a description (is ~) into a change (became ~).",formTable:[{when:"Stem vowel is ㅏ or ㅗ",add:"stem + 아졌어요",ex:"좋다 → 좋아졌어요 (got better); 많다 → 많아졌어요 (became more)"},{when:"Other stem vowels",add:"stem + 어졌어요",ex:"크다 → 커졌어요 (got bigger)"},{when:"하다 adjectives",add:"stem + 해졌어요",ex:"편하다 → 편해졌어요 (became comfortable)"}],examples:[{ko:"한국어 공부가 점점 재미있어졌어요.",romanization:"hangugeo gongbuga jeomjeom jaemiisseojyeosseoyo.",en:"Studying Korean has gradually gotten fun.",note:"재미있다 → 재미있어졌어요; 점점 (gradually) goes naturally with a change of state."},{ko:"날씨가 따뜻해졌어요.",romanization:"nalssiga ttatteuthaejyeosseoyo.",en:"The weather has gotten warm.",note:"따뜻하다 (a 하다 adjective) → 따뜻해졌어요; the change has already happened (past)."},{ko:"친구가 많아졌어요.",romanization:"chinguga manajyeosseoyo.",en:"I have more friends now.",note:"많다 → 많아졌어요; the ㅏ stem takes 아졌어요, showing things increased."},{ko:"운동을 해서 몸이 건강해졌어요.",romanization:"undong-eul haeseo mom-i geonganghaejyeosseoyo.",en:"I exercised, so I got healthier.",note:"건강하다 → 건강해졌어요; the change comes from a cause (운동을 해서)."}],keyPoint:{label:"좋다 (a state) vs. 좋아졌어요 (a change of state)",body:"좋다 means 'is good' — it just describes. 좋아졌어요 means 'got/became good' — it shows a change. Use -아/어졌어요 whenever English would say 'became,' 'got,' or 'grew' plus an adjective. (For ㅡ-vowel stems like 크다, the ㅡ drops: 크 → 커졌어요 — more on those later.)"},pronunciation:"많아졌어요 sounds like [마나져써요] (ma-na-jyeo-sseo-yo): the ㅎ in 많 is silent and the ㄴ links to the next vowel.",drill:{instruction:"Change each adjective into a 'became/got' statement using A-아/어졌어요.",model:"날씨가 따뜻하다 → 날씨가 따뜻해졌어요.",items:["한국어가 쉽다 → ____________","방이 깨끗하다 → ____________","값이 비싸다 → ____________"]},englishSpeakerPitfall:{wrong:"날씨가 따뜻했어요. (meaning 'the weather got warm')",right:"날씨가 따뜻해졌어요.",explanation:"따뜻했어요 just means 'it was warm' — a past state, no change. To say it CHANGED and 'became' warm, add -아/어지다 → 따뜻해졌어요. English 'got warm' means it changed, so keep the 졌어요."}}],V=[{title:"V-(스)ㅂ니다 — the formal polite ending (합니다체)",func:"This is the formal polite ending for statements. It sounds more formal than the everyday -아요/-어요 (해요체) ending, so you hear it in announcements, at work, in the news, and when you first meet someone.",formTable:[{when:"Stem ends in a vowel (no 받침)",add:"stem + ㅂ니다",ex:"가다 → 갑니다 / 오다 → 옵니다 / 크다 → 큽니다"},{when:"Stem ends in a consonant (has 받침)",add:"stem + 습니다",ex:"먹다 → 먹습니다 / 읽다 → 읽습니다 / 작다 → 작습니다"},{when:"Stem ends in ㄹ (the ㄹ drops)",add:"drop ㄹ, then + ㅂ니다",ex:"살다 → 삽니다 / 만들다 → 만듭니다 / 알다 → 압니다"},{when:"이다 (to be), after a noun",add:"noun + 입니다",ex:"학생이다 → 학생입니다 / 친구이다 → 친구입니다"},{when:"Question form",add:"-(스)ㅂ니까?",ex:"가다 → 갑니까? / 먹다 → 먹습니까?"}],examples:[{ko:"저는 학생입니다.",romanization:"jeo-neun hak-saeng-im-ni-da.",en:"I'm a student.",note:"이다 attaches to the noun 학생 as 입니다 — the standard way to introduce yourself."},{ko:"아침마다 밥을 먹습니다.",romanization:"a-chim-ma-da ba-beul meok-seum-ni-da.",en:"I eat every morning.",note:'먹다 has a 받침 (ㄱ), so it takes 습니다 → 먹습니다. 밥을 먹다 just means "to eat (a meal)".'},{ko:"지금 학교에 갑니다.",romanization:"ji-geum hak-gyo-e gam-ni-da.",en:"I'm going to school now.",note:"가다 ends in a vowel, so it takes ㅂ니다 → 갑니다."},{ko:"부산에 삽니까?",romanization:"bu-san-e sam-ni-kka?",en:"Do you live in Busan?",note:"살다 ends in ㄹ, which drops before ㅂ; the question ending -ㅂ니까? makes it 삽니까?"}],keyPoint:{label:"받침 decides ㅂ니다 vs 습니다",body:"No 받침 → add ㅂ니다 (가 → 갑니다). Has 받침 → add 습니다 (먹 → 먹습니다). The one exception is ㄹ stems: the ㄹ drops and you use ㅂ니다 (살 → 삽니다), so they act like vowel stems."},pronunciation:"The ㅂ in -ㅂ니다 sounds like [m] before ㄴ: 갑니다 sounds like [감니다], 입니다 like [임니다], and 습니다 like [슴니다].",drill:{instruction:"Change each dictionary-form verb into the formal 합니다체 statement (V-(스)ㅂ니다).",model:"읽다 → 읽습니다",items:["오다 → ____","만들다 → ____","작다 → ____"]},englishSpeakerPitfall:{wrong:"먹읍니다 / 가습니다",right:"먹습니다 / 갑니다",explanation:"The ending depends on the last letter of the stem, not the meaning. A stem ending in a consonant like 먹 takes 습니다 (not ㅂ니다), and a stem ending in a vowel like 가 takes ㅂ니다 (not 습니다). Check the stem's last letter first."}},{title:"Choosing the style — 해요체 vs 합니다체 vs 반말",func:"Korean changes the verb ending depending on who you're talking to. The three everyday styles are 해요체 (polite, all-purpose), 합니다체 (formal polite), and 반말 (casual, no -요). The listener and the situation pick the ending — not the meaning of the sentence — so the wrong choice can sound rude or oddly stiff.",formTable:[{when:"해요체 — polite, the default for daily life",add:"stem + -아요/-어요/-해요",ex:"가다 → 가요 / 먹다 → 먹어요 / 공부하다 → 공부해요"},{when:"합니다체 — formal polite (work, announcements, first meeting)",add:"stem + -(스)ㅂ니다",ex:"가다 → 갑니다 / 먹다 → 먹습니다"},{when:"반말 — casual (close friends, younger people, family)",add:"해요체 minus 요",ex:"가요 → 가 / 먹어요 → 먹어 / 공부해요 → 공부해"},{when:"Same sentence, three styles (먹다)",add:"먹습니다 / 먹어요 / 먹어",ex:'all mean "(I) eat", from most formal to most casual'}],examples:[{ko:"안녕하세요? 저는 한국 사람이에요.",romanization:"an-nyeong-ha-se-yo? jeo-neun han-guk sa-ram-i-e-yo.",en:"Hello. I'm Korean.",note:"해요체 — the safe, friendly default for people you don't know well."},{ko:"안녕하십니까? 만나서 반갑습니다.",romanization:"an-nyeong-ha-sim-ni-kka? man-na-seo ban-gap-seum-ni-da.",en:"Hello. Nice to meet you.",note:"합니다체 — a formal first greeting; you'd hear this in business and formal settings."},{ko:"야, 너 지금 어디 가?",romanization:"ya, neo ji-geum eo-di ga?",en:"Hey, where are you going right now?",note:"반말 — 가요 drops 요 to become 가; used with a close friend the same age. 너 (you) also marks 반말."},{ko:"엄마, 나 배고파.",romanization:"eom-ma, na bae-go-pa.",en:"Mom, I'm hungry.",note:'반말 — used at home with family; 배고파요 drops 요 to 배고파, and 나 (casual "I") fits the casual style.'}],keyPoint:{label:"The listener, not the meaning, picks the ending",body:"합니다체 = formal/distant (work, strangers, announcements). 해요체 = polite all-purpose (the safe everyday choice). 반말 = casual, only with close friends, younger people, or family. When unsure in ordinary conversation, 해요체 is usually the safest polite default; wording, tone, and highly formal settings still matter."},pronunciation:"For plain 반말 pairs such as 가./가?, spelling stays the same and rising pitch distinguishes the question. Other casual question endings, including -니? and -(으)ㄹ까?, also exist.",drill:{instruction:"Rewrite each 해요체 sentence in the style named in brackets (합니다체 = formal, 반말 = casual).",model:"가요. [반말] → 가.",items:["먹어요. [합니다체] → ____","와요. [반말] → ____","공부해요. [합니다체] → ____"]},englishSpeakerPitfall:{wrong:"(to your boss) 야, 밥 먹었어?",right:"(to your boss) 식사하셨어요? / 점심 드셨어요?",explanation:"English has one neutral register, so learners drop 요 to sound casual and friendly — but 반말 can be disrespectful to someone older or senior. Default to 해요체 with anyone you aren't clearly close to, and switch to 반말 only once the relationship plainly allows it."}},{title:"반말 4형 — casual statements, questions, commands, and let's",func:`반말 is the casual style used with close friends, younger people, and some family members. For many everyday statements and questions, you can start from the 해요체 form and remove 요: 먹어요 → 먹어. Commands use the same -아/어 shape, while casual "let's" uses -자.`,formTable:[{when:"Statement / question",add:"해요체 minus 요",ex:"먹어요 → 먹어. / 먹어?; 가요 → 가. / 가?"},{when:"Command",add:"verb stem + -아/어",ex:"앉다 → 앉아!, 오다 → 와!"},{when:`Proposal / "let's"`,add:"verb stem + -자",ex:"가다 → 가자, 먹다 → 먹자"},{when:"이다 / 아니다",add:"noun + 야/이야; 아니다 → 아니야",ex:"친구야, 학생이야, 아니야"}],examples:[{ko:"나 지금 집에 가.",romanization:"na jigeum jibe ga.",en:"I'm going home now.",note:"Statement: 가요 loses 요 → 가. 나 also matches the casual style."},{ko:"너 밥 먹었어?",romanization:"neo bap meogeosseo?",en:"Did you eat?",note:"Question: 먹었어요 loses 요 → 먹었어? The rising pitch makes it a question."},{ko:"잠깐 이리 와.",romanization:"jamkkan iri wa.",en:"Come here for a second.",note:"Command: 오다 becomes 와. This is only safe when 반말 is already okay."},{ko:"지민아, 같이 가자.",romanization:"jimina, gachi gaja.",en:"Jimin, let's go together.",note:"Name + 아 calls someone with 받침; 가자 is the casual let's form."}],keyPoint:{label:"요-drop is grammar; permission is social",body:`The form is simple: remove 요 for many statements and questions, use -자 for "let's," and use 야/이야 after nouns. The hard part is social timing. Switch to 반말 only after the relationship allows it, often after someone asks 말 놔도 돼요? or suggests 우리 말 놓을까요?`},pronunciation:"In 반말 questions, spelling often stays the same as the statement and pitch does the work: 먹어. falls, 먹어? rises. With names, 지민아 flows as [지미나] because the final ㄴ links to 아.",drill:{instruction:"Change each polite sentence into natural 반말 for a close friend.",model:"같이 가요. → 같이 가.",items:["밥 먹어요? → ____","여기 앉으세요. → ____","우리 영화 봐요. → ____"]},englishSpeakerPitfall:{wrong:"반말 is just Korean slang, so it is okay with anyone if I sound friendly.",right:"반말 is a relationship signal. Use it only with close people, younger people, or when both sides have agreed.",explanation:"The form itself is not rude; the mismatch is rude. A perfect 먹어? can be warm to a close friend and very disrespectful to a teacher or stranger. Decide the relationship first, then choose the ending."}}],E=[{title:"-(으)시- — the subject honorific suffix",func:"You add -(으)시- to a verb or adjective stem to show respect toward the person doing the action or being described — usually someone older or higher than you. It raises the SUBJECT of the sentence, not the listener.",formTable:[{when:"Stem ends in a vowel",add:"+ -시-",ex:"가다 → 가시다 → 가세요"},{when:"Stem ends in a consonant",add:"+ -으시-",ex:"읽다 → 읽으시다 → 읽으세요"},{when:"Stem ends in ㄹ (ㄹ drops)",add:"drop ㄹ + -시-",ex:"살다 → 사시다 → 사세요"},{when:"Polite speech ending",add:"-(으)시- → -(으)세요",ex:"앉다 → 앉으세요 / 오다 → 오세요"}],examples:[{ko:"선생님이 책을 읽으세요.",romanization:"seonsaengnim-i chaeg-eul ilgeuseyo.",en:"The teacher is reading a book.",note:"The subject 선생님 is honored, so 읽다 takes the -으시- form (consonant stem) → 읽으세요."},{ko:"할머니가 지금 주무세요.",romanization:"halmeoni-ga jigeum jumuseyo.",en:"Grandmother is sleeping right now.",note:"주무세요 already has -시- inside it (from the special honorific 주무시다); the honored subject is 할머니."},{ko:"아버지는 매일 아침에 운동하세요.",romanization:"abeoji-neun maeil achim-e undonghaseyo.",en:"Dad exercises every morning.",note:"하다 ends in a vowel, so it just adds -시- → 하세요; the honored subject is 아버지."},{ko:"오늘 기분이 좋으세요?",romanization:"oneul gibun-i joeuseyo?",en:"Are you in a good mood today?",note:"Adjectives take -(으)시- too when they describe an honored person: 좋다 (consonant stem) → 좋으세요."}],keyPoint:{label:"-(으)시- vs. -아/어요",body:"-아/어요 is polite toward the LISTENER; -(으)시- raises the SUBJECT of the sentence. You can be polite to a friend (친구가 와요) without -시-, but to honor a teacher you add it (선생님이 오세요). Never use -시- about yourself: say 저는 가요, never 저는 가세요."},pronunciation:"읽으세요 is pronounced [일그세요] (ilgeuseyo) — the ㄱ of 읽 moves over to fill the 으 syllable.",drill:{instruction:"Make each sentence honorific by adding -(으)시- (use the -(으)세요 form).",model:"선생님이 책을 읽어요. → 선생님이 책을 읽으세요.",items:["할아버지가 신문을 봐요. → 할아버지가 신문을 ____.","아버지가 회사에 가요. → 아버지가 회사에 ____.","어머니가 집에 있어요. → 어머니가 집에 ____."]},englishSpeakerPitfall:{wrong:"저는 한국어를 공부하세요.",right:"저는 한국어를 공부해요.",explanation:"English has no grammar that raises the subject, so learners over-use -시- and end up honoring themselves. -(으)시- is only for someone you respect — never 저/나. For yourself, use the plain polite form."}},{title:"N께서 V-(으)시- — 께서 and the special honorific verbs",func:"When the subject deserves respect, the subject particle 이/가 changes to 께서, and the verb takes -(으)시-. A few very common verbs have their own honorific forms you just have to memorize, instead of adding -시-.",formTable:[{when:"Subject particle 이/가 → 께서",add:"N + 께서",ex:"선생님이 → 선생님께서 / 할머니가 → 할머니께서"},{when:"있다 (to be / stay somewhere) → special form",add:"있다 → 계시다",ex:"할아버지께서 집에 계세요."},{when:"먹다 / 마시다 (eat / drink) → special form",add:"먹다 → 드시다 (잡수시다)",ex:"아버지께서 밥을 드세요."},{when:"자다 (to sleep) → special form",add:"자다 → 주무시다",ex:"어머니께서 주무세요."}],examples:[{ko:"할아버지께서 방에 계세요.",romanization:"harabeoji-kkeseo bang-e gyeseyo.",en:"Grandfather is in the room.",note:"있다 (existence) becomes the special honorific 계시다 → 계세요, and the subject takes 께서 instead of 가."},{ko:"선생님께서 점심을 드세요.",romanization:"seonsaengnim-kkeseo jeomsim-eul deuseyo.",en:"The teacher is eating lunch.",note:"먹다 → 드시다 (everyday honorific); 잡수시다 is the more formal version. The subject takes 께서."},{ko:"부모님께서 주말에 영화를 보세요.",romanization:"bumonim-kkeseo jumar-e yeonghwa-reul boseyo.",en:"My parents watch a movie on the weekend.",note:"보다 has no special form, so it just adds -시- → 보세요, but the honored subject 부모님 still takes 께서."},{ko:"할머니께서 일찍 주무세요.",romanization:"halmeoni-kkeseo iljjik jumuseyo.",en:"Grandmother goes to sleep early.",note:"자다 → 주무시다, which already has -시- built in; pair it with 께서 for the honored subject."}],keyPoint:{label:"있다: 있으세요 vs. 계세요",body:"When 있다 means existence/being somewhere ('to be there'), the honorific is 계세요 (할아버지께서 집에 계세요). When 있다 means possession ('to have'), use 있으세요, NOT 계세요 (선생님께서 시간이 있으세요). 계세요 is only for a person being present, never for having things."},pronunciation:"계세요 is usually said [게세요] (geseyo) in everyday speech — the ㅖ softens to ㅔ after ㄱ.",drill:{instruction:"Rewrite each sentence with 께서 and the correct honorific verb (use the special form where one exists).",model:"할아버지가 집에 있어요. → 할아버지께서 집에 계세요.",items:["아버지가 밥을 먹어요. → 아버지____ 밥을 ____.","할머니가 자요. → 할머니____ ____.","선생님이 교실에 있어요. → 선생님____ 교실에 ____."]},englishSpeakerPitfall:{wrong:"할아버지께서 집에 있으세요.",right:"할아버지께서 집에 계세요.",explanation:"Learners add -으시- to 있다 and get 있으세요, but for a respected person who is present somewhere, Korean swaps in the special verb 계시다 → 계세요. 있으세요 is only for possession ('have')."}},{title:"N께 V-아/어 드리다 — honoring the person you do something for",func:"While -(으)시- honors the subject, 드리다 honors the RECIPIENT — the person you do something FOR. 주다 ('give / do for someone') becomes 드리다, and the recipient particle 에게/한테 becomes 께.",formTable:[{when:"Recipient particle 에게/한테 → 께",add:"N + 께",ex:"동생한테 → 할머니께 / 친구에게 → 부모님께"},{when:"주다 (to give) → honorific",add:"주다 → 드리다",ex:"선물을 줘요 → 선물을 드려요"},{when:"V-아/어 주다 (do for someone) → -아/어 드리다",add:"V-아/어 + 드리다",ex:"도와주다 → 도와 드리다 / 읽어 주다 → 읽어 드리다"},{when:"ㅏ/ㅗ stem → -아 드리다; other vowels → -어 드리다",add:"V-아/어 + 드리다",ex:"사다 → 사 드려요 / 만들다 → 만들어 드려요"}],examples:[{ko:"할머니께 선물을 드렸어요.",romanization:"halmeoni-kke seonmur-eul deuryeosseoyo.",en:"I gave Grandmother a present.",note:"The recipient 할머니 is honored, so 주다 → 드리다 and 에게/한테 → 께."},{ko:"제가 부모님께 밥을 사 드렸어요.",romanization:"je-ga bumonim-kke bab-eul sa deuryeosseoyo.",en:"I bought my parents a meal.",note:"사 주다 ('buy for someone') → 사 드리다 because the recipient 부모님 deserves respect."},{ko:"선생님께 책을 읽어 드릴게요.",romanization:"seonsaengnim-kke chaeg-eul ilgeo deurilgeyo.",en:"I'll read the book for the teacher.",note:"읽어 주다 → 읽어 드리다; the action is done FOR the honored recipient 선생님."},{ko:"할아버지께 길을 가르쳐 드렸어요.",romanization:"harabeoji-kke gir-eul gareuchyeo deuryeosseoyo.",en:"I showed Grandfather the way.",note:"가르쳐 주다 → 가르쳐 드리다, with 께 marking the honored recipient 할아버지."}],keyPoint:{label:"-(으)시- vs. -아/어 드리다",body:"-(으)시- raises the person DOING the action (subject); 드리다 raises the person RECEIVING it (recipient). 선생님께서 가르치세요 = the teacher (subject) teaches; 선생님께 가르쳐 드려요 = I teach FOR the teacher. The 드리다 sentence usually has 저/제가 as the (humble) subject."},pronunciation:"읽어 드려요 is pronounced [일거 드려요] (ilgeo deuryeoyo) — the ㄹㄱ of 읽 links into the next syllable.",drill:{instruction:"Rewrite with 께 and 드리다 (or -아/어 드리다) to honor the recipient.",model:"친구에게 선물을 줬어요. → 부모님께 선물을 드렸어요.",items:["동생한테 책을 사 줬어요. → 할머니____ 책을 사 ____.","친구에게 밥을 만들어 줬어요. → 부모님____ 밥을 만들어 ____.","동생한테 길을 가르쳐 줬어요. → 선생님____ 길을 가르쳐 ____."]},englishSpeakerPitfall:{wrong:"할머니께 선물을 주세요. (meaning 'I gave Grandmother a gift')",right:"할머니께 선물을 드렸어요.",explanation:"Learners reach for 주다 with -시- (주세요) to sound polite, but -(으)시- honors the subject (the giver), not the recipient. To honor the person RECEIVING, you change the verb itself to 드리다. (주세요 only works as a request: 'please give.')"}}],K=[{title:"V/A-(으)ㄴ/는데 — Giving Background Before Your Point",func:'Use -(으)ㄴ/는데 to give a piece of background first, then say what you really mean (a question, a suggestion, or a request) in the next clause. It loosely links two ideas, a bit like English "so..." or "and...".',formTable:[{when:"Action verb stem",add:"-는데",ex:"먹다 → 먹는데, 가다 → 가는데"},{when:"Adjective stem ending in a vowel/ㄹ",add:"-ㄴ데",ex:"바쁘다 → 바쁜데, 멀다 → 먼데 (ㄹ drops)"},{when:"Adjective stem ending in a consonant",add:"-은데",ex:"작다 → 작은데, 좋다 → 좋은데"},{when:"Noun + 이다 / past tense",add:"인데 / -았/었는데",ex:"학생이다 → 학생인데, 먹다 → 먹었는데"}],examples:[{ko:"시간이 없는데 택시 탈까요?",romanization:"sigani eomneunde taeksi talkkayo?",en:"We don't have time, so should we take a taxi?",note:"The background (no time) sets up the suggestion that follows."},{ko:"이 책이 좀 어려운데 같이 읽어요.",romanization:"i chaegi jom eoryeounde gachi ilgeoyo.",en:"This book is a bit hard, so let's read it together.",note:"어렵다 has an irregular ㅂ, so it becomes 어려운데, not 어렵은데."},{ko:"지금 밥 먹는데 이따가 전화할게요.",romanization:"jigeum bap meongneunde ittaga jeonhwahalgeyo.",en:"I'm eating right now, so I'll call you later.",note:"Action verb 먹다 takes -는데 no matter the final sound."},{ko:"제 친구가 학생인데 한국어를 정말 잘해요.",romanization:"je chinguga haksaeginde hangugeoreul jeongmal jalhaeyo.",en:"My friend is a student, and she speaks Korean really well.",note:"Noun + 이다 becomes 인데; here it just adds info, not contrast."}],keyPoint:{label:"-는데 vs. -아서/어서",body:"-아서/어서 ties a clause as a tight cause ('because A, B'). -(으)ㄴ/는데 just sets the scene ('A, and now...') and feels softer. Only -는데 can lead naturally into a -ㄹ까요? or -ㄹ래요? question. The full contrast use of -는데 comes later."},pronunciation:"는데 sounds like [는데] with no change, but after a ㄷ/ㅅ/ㅈ-final stem like 받다, 받는데 becomes [반는데] (the ㄷ turns into ㄴ before 는).",drill:{instruction:"Attach -(으)ㄴ/는데 to the cue verb to give background, then read the whole sentence aloud.",model:"(시간이 없다) → 시간이 없는데 택시 탈까요?",items:["(돈이 없다) ___ 다음에 살게요.","(이 영화 재미있다) ___ 같이 볼래요?","(지금 집에 가다) ___ 내일 만나요."]},englishSpeakerPitfall:{wrong:"시간이 없어서 택시 탈까요?",right:"시간이 없는데 택시 탈까요?",explanation:"English speakers grab -아서/어서 ('because') to lead into a suggestion, but -아서/어서 can't come before a -ㄹ까요?/-ㄹ래요? ending. Use -는데 to set up the background first."}},{title:"V/A-잖아요 — Reminding Someone of What You Both Know",func:'Use -잖아요 to remind the listener of something you both already know, or to point out something obvious as your reason. It carries the feeling of "you know..." or "remember...".',formTable:[{when:"Any verb/adjective stem (present)",add:"-잖아요",ex:"비싸다 → 비싸잖아요, 가다 → 가잖아요"},{when:"Past tense",add:"-았/었잖아요",ex:"먹다 → 먹었잖아요, 보다 → 봤잖아요"},{when:"Noun + 이다",add:"-(이)잖아요",ex:"일요일이다 → 일요일이잖아요, 친구다 → 친구잖아요"},{when:"Casual (반말)",add:"-잖아",ex:"비싸잖아, 먹었잖아"}],examples:[{ko:"그 식당은 비싸잖아요. 다른 데 가요.",romanization:"geu sikdangeun bissajanayo. dareun de gayo.",en:"That restaurant is expensive, you know. Let's go somewhere else.",note:"Reminds the listener of a shared fact (it's expensive) as the reason."},{ko:"오늘 일요일이잖아요. 학교 안 가요.",romanization:"oneul iryoirijanayo. hakgyo an gayo.",en:"It's Sunday today, remember? We don't have school.",note:"Noun + 이다 → 일요일이잖아요; pointing out an obvious fact."},{ko:"어제 같이 밥 먹었잖아요. 벌써 잊었어요?",romanization:"eoje gachi bap meogeotjanayo. beolsseo ijeosseoyo?",en:"We ate together yesterday, remember? Did you forget already?",note:"Past tense -었잖아요 brings back a shared experience."},{ko:"민수 씨가 한국어 잘하잖아요. 민수 씨한테 물어봐요.",romanization:"minsu ssiga hangugeo jalhajanayo. minsu ssihante mureobwayo.",en:"Minsu is good at Korean, you know. Ask him.",note:"Uses a known fact about Minsu to back up the suggestion."}],keyPoint:{label:"-잖아요 vs. -거든요",body:"-잖아요 points to OLD information the listener already knows ('you know that...'). -거든요 gives NEW information they don't know yet. Using -잖아요 for brand-new facts sounds odd, like 'you should have known this already'."},pronunciation:"잖아요 links across the syllable and sounds like [자나요], with the ㅈ and ㅇ flowing together. Don't break it into [잗-아요].",drill:{instruction:"Turn each known fact into a reminder with -잖아요.",model:"(그 식당은 비싸다) → 그 식당은 비싸잖아요.",items:["(오늘은 토요일이다) → ___","(우리 어제 그 영화 봤다) → ___","(지금 비가 오다) → ___"]},englishSpeakerPitfall:{wrong:"저 처음 보죠? 제 이름은 민수잖아요.",right:"저 처음 보죠? 제 이름은 민수거든요.",explanation:"Don't use -잖아요 for information that's new to the listener — it sounds like you're saying they should already know it, which can feel like a scolding. For brand-new info, use -거든요."}},{title:"V/A-지요/죠 — Checking Shared Understanding",func:`Use -지요? or its spoken contraction -죠? when you think you already know the answer and want the listener to confirm or agree. It is softer than a plain information question because it sounds like "right?" or "you know, don't you?" In everyday speech, -죠 is more common than the full -지요.`,formTable:[{when:"Verb/adjective stem",add:"-지요? / -죠?",ex:"덥다 → 덥지요? / 덥죠?, 재미있다 → 재미있죠?"},{when:"Past tense",add:"-았/었지요? / -았/었죠?",ex:"봤다 → 봤지요? / 봤죠?, 먹었다 → 먹었죠?"},{when:"Noun + 이다",add:"-(이)지요? / -(이)죠?",ex:"학생이다 → 학생이지요? / 학생이죠?, 친구다 → 친구죠?"},{when:"Casual",add:"-지?",ex:"덥지?, 맞지?"}],examples:[{ko:"오늘 정말 덥죠?",romanization:"oneul jeongmal deopjyo?",en:"It's really hot today, isn't it?",note:"Weather small talk: the speaker expects agreement, not new information."},{ko:"민수 씨는 학생이지요?",romanization:"minsu ssineun haksaengijiyo?",en:"Minsu is a student, right?",note:"Noun + 이다 becomes 학생이지요; the speaker is confirming something they think is true."},{ko:"한국어는 재미있죠.",romanization:"hangugeoneun jaemiitjyo.",en:"Korean is fun, you know.",note:"As a statement, -죠 invites agreement and creates a shared feeling."},{ko:"내일 시험이죠? 맞죠?",romanization:"naeil siheomijyo? matjyo?",en:"The test is tomorrow, right? That's right, isn't it?",note:"A gentle self-check; 맞죠? is a common quick confirmation."}],keyPoint:{label:"-아요? asks; -지요?/죠? confirms",body:"Use -아요? when you do not know and need information. Use -지요?/죠? when you already have an idea and want confirmation, agreement, or shared footing. If you truly have no idea, plain -아요? is safer."},pronunciation:"The contracted 죠 is one quick syllable. After a stop consonant like the ㅂ in 덥죠, the ㅈ is always pronounced tense, so 덥죠 sounds like [덥쬬] at any speed — but keep the spelling 덥죠, not 덥쬬.",drill:{instruction:"Change each plain question into a confirmation question with -죠?",model:"오늘 추워요? → 오늘 춥죠?",items:["내일 시간 있어요? → ____","이 영화 재미있어요? → ____","민수 씨는 선생님이에요? → ____"]},englishSpeakerPitfall:{wrong:"이름이 뭐죠? (when you truly do not know and are asking a stranger)",right:"이름이 뭐예요? / 성함이 어떻게 되세요?",explanation:"English tag questions are flexible, so learners overuse -죠 for ordinary questions. But -죠 suggests you expected or half-knew the answer. For new information, use a normal question; save -죠 for confirmation or shared facts."}},{title:"V/A-거든요 — Adding a Reason They Didn't Know",func:`Use -거든요 to give the listener new information — usually a reason or background fact they didn't know — often answering a spoken or silent "why?". It feels like "...you see" at the end.`,formTable:[{when:"Any verb/adjective stem (present)",add:"-거든요",ex:"바쁘다 → 바쁘거든요, 가다 → 가거든요"},{when:"Past tense",add:"-았/었거든요",ex:"먹다 → 먹었거든요, 자다 → 잤거든요"},{when:"Noun + 이다",add:"-(이)거든요",ex:"학생이다 → 학생이거든요, 친구다 → 친구거든요"},{when:"Casual (반말)",add:"-거든",ex:"바쁘거든, 먹었거든"}],examples:[{ko:"오늘은 못 만나요. 할 일이 많거든요.",romanization:"oneureun mot mannayo. hal iri mankeodeunyo.",en:"I can't meet today. I have a lot to do, you see.",note:"Gives a reason the listener didn't know."},{ko:"저 요즘 한국어 배워요. 한국 친구가 많거든요.",romanization:"jeo yojeum hangugeo baewoyo. hanguk chinguga mankeodeunyo.",en:"I'm learning Korean these days. I have a lot of Korean friends, you see.",note:"Adds fresh background that explains the first sentence."},{ko:"어제 일찍 잤어요. 너무 피곤했거든요.",romanization:"eoje iljjik jasseoyo. neomu pigonhaetgeodeunyo.",en:"I went to bed early yesterday. I was so tired, you see.",note:"Past tense -었거든요 gives the reason for a past action."},{ko:"오늘 우산 가져왔어요. 비가 온다고 했거든요.",romanization:"oneul usan gajyeowasseoyo. biga ondago haetgeodeunyo.",en:"I brought an umbrella today. They said it would rain, you see.",note:"Introduces a new fact that explains the action."}],keyPoint:{label:"-거든요 vs. -아서/어서",body:"Both can give a reason, but -아서/어서 joins two clauses inside one sentence ('A여서 B'). -거든요 ends the sentence and tacks the reason on afterward as a fresh follow-up — it signals 'here's something you didn't know'. -아서/어서 doesn't carry that 'news' feeling."},pronunciation:"거든요 keeps each syllable clear: [거든뇨] in fast speech as the ㄴ and ㅛ glide together. Don't soften it to [거더요].",drill:{instruction:"Add a reason the listener doesn't know yet, using -거든요.",model:"(못 만나요 / 할 일이 많다) → 못 만나요. 할 일이 많거든요.",items:["(오늘 집에 일찍 가요 / 부모님이 오시다) → ___","(물을 많이 마셔요 / 날씨가 덥다) → ___","(그 영화 봤어요 / 친구가 추천했다) → ___"]},englishSpeakerPitfall:{wrong:"일이 많거든요 못 만나요.",right:"오늘은 못 만나요. 일이 많거든요.",explanation:"-거든요 goes at the END of a sentence, not in the middle like English 'because'. Say your main point first, then add the reason as a separate sentence ending in -거든요."}},{title:"V/A-는데요 — A Soft, Trailing Ending",func:"Use sentence-final -는데요 to leave your statement gently open, inviting the other person to react or softening a reply. It often hints at an unspoken 'but...', which makes answers and mild objections sound polite instead of blunt.",formTable:[{when:"Action verb (present)",add:"-는데요",ex:"가다 → 가는데요, 먹다 → 먹는데요"},{when:"Adjective (present)",add:"-(으)ㄴ데요",ex:"바쁘다 → 바쁜데요, 작다 → 작은데요"},{when:"Past tense",add:"-았/었는데요",ex:"가다 → 갔는데요, 좋다 → 좋았는데요"},{when:"Noun + 이다",add:"인데요",ex:"학생이다 → 학생인데요"}],examples:[{ko:"지금 좀 바쁜데요.",romanization:"jigeum jom bappeunde-yo.",en:"I'm a little busy right now... (so maybe later?)",note:"Trails off softly instead of a flat 'no', leaving room for the other person."},{ko:"그건 잘 모르는데요.",romanization:"geugeon jal moreunde-yo.",en:"Hmm, I don't really know that...",note:"A gentle way to admit you don't know, softer than 몰라요."},{ko:"저는 벌써 다 먹었는데요.",romanization:"jeoneun beolsseo da meogeonneunde-yo.",en:"But I already finished eating...",note:"Past tense -었는데요 here carries a mild 'but', a soft pushback."},{ko:"여기 자리 있는데요.",romanization:"yeogi jari inneunde-yo.",en:"Um, someone's sitting here...",note:"Softly tells someone a seat is taken without sounding harsh."}],keyPoint:{label:"-는데 vs. -는데요",body:"-는데 in the middle of a sentence sets up background for a following clause. -는데요 stands at the very END as a soft, open finish. Same shape, but here it's a complete reply that trails off, not a connector. The honorific 요 is what makes it a polite stand-alone ending."},pronunciation:"는데요 sounds like [는데요]; after a ㄷ/ㅅ/ㅈ-final stem the ㄴ-change still applies (먹었는데요 → [머건는데요]). Let the final 요 drift up slightly to keep the soft, open feel.",drill:{instruction:"Answer each prompt with a soft, trailing -는데요 ending.",model:"(지금 바쁘다) → 지금 좀 바쁜데요.",items:["(그건 잘 모르다) → ___","(저는 벌써 먹었다) → ___","(여기 자리 있다) → ___"]},englishSpeakerPitfall:{wrong:"지금 바빠요. (flat, can sound blunt when declining)",right:"지금 좀 바쁜데요.",explanation:"English speakers end a refusal with a plain -아요/어요, which can land too direct in Korean. Adding -는데요 leaves the sentence softly open, so a 'no' feels gentler and more polite."}}],q=[{title:"V/A-더라고요 — reporting what I noticed firsthand",func:'Use -더라고요 to report something you personally saw, heard, or felt in the past, usually with a touch of mild surprise or fresh discovery. It means "I noticed / it turned out that..." — the information comes from your own direct experience, not from what someone else told you.',formTable:[{when:"Verb stem (any ending)",add:"-더라고요",ex:"가다 → 가더라고요 / 먹다 → 먹더라고요"},{when:"Adjective stem (any ending)",add:"-더라고요",ex:"춥다 → 춥더라고요 / 좋다 → 좋더라고요"},{when:"Noun + 이다 / 아니다",add:"-더라고요",ex:"학생이다 → 학생이더라고요 / 아니다 → 아니더라고요"},{when:"Past tense (-았/었-)",add:"-더라고요",ex:"갔다 → 갔더라고요 / 끝났다 → 끝났더라고요"}],examples:[{ko:"그 영화 정말 재미있더라고요.",romanization:"geu yeonghwa jeongmal jaemiitdeoragoyo.",en:"That movie was really fun (I saw for myself).",note:"You watched it yourself, so you report your own impression with -더라고요."},{ko:"어제 밖에 나갔는데 생각보다 춥더라고요.",romanization:"eoje bakke nagannneunde saenggakboda chupdeoragoyo.",en:"I went outside yesterday, and it was colder than I thought.",note:"-더라고요 carries the 'I felt it firsthand' nuance — perfect for weather you experienced."},{ko:"민수 씨가 한국어를 정말 잘하더라고요.",romanization:"minsu ssiga hangugeoreul jeongmal jalhadeoragoyo.",en:"Minsu speaks Korean really well (I noticed).",note:"You observed his ability directly, so the slight surprise is built in."},{ko:"그 식당에 가 봤는데 사람이 정말 많더라고요.",romanization:"geu sikdange ga bwanneunde sarami jeongmal mandeoragoyo.",en:"I tried that restaurant, and there were a lot of people.",note:"Reporting a scene you saw with your own eyes — a classic -더라고요 use."}],keyPoint:{label:"-더라고요 vs. plain -았/었어요",body:"Both talk about the past, but -았/었어요 just states a fact, while -더라고요 frames it as something YOU personally witnessed and are now reporting, often with mild surprise. '비가 왔어요' = it rained (fact); '비가 오더라고요' = I saw that it was raining."},pronunciation:"In casual speech -더라고요 is often written informally as -더라구요, but -더라고요 is the standard spelling. In 많더라고요, ㄶ combines with the following ㄷ and makes an aspirated ㅌ sound: [만터라고요].",drill:{instruction:"Report something you personally noticed, using -더라고요.",model:"그 카페 / 조용하다 → 그 카페가 조용하더라고요.",items:["친구 집 / 멀다 → ____","그 책 / 어렵다 → ____","오늘 날씨 / 좋다 → ____"]},englishSpeakerPitfall:{wrong:"제가 어제 피곤하더라고요.",right:"제가 어제 피곤했어요. / (친구를 보고) 친구가 피곤해 보이더라고요.",explanation:"-더라고요 usually reports what you observe about OTHER people or the outside world, not your own feeling as you have it. For your own past feelings, use plain -았/었어요. (Your own feelings take -더라고요 only when you look back and 'notice' them as a discovery.)"}},{title:"V/A-더니 — I saw X happen, and then Y followed",func:"Use -더니 to link two things you personally watched: 'I noticed X (in the past), and then Y happened.' The second part is often a change, a result, or a contrast that grows out of the first. The subject of the first part is usually someone else, not you.",formTable:[{when:"Verb stem (any ending)",add:"-더니",ex:"울다 → 울더니 / 먹다 → 먹더니"},{when:"Adjective stem (any ending)",add:"-더니",ex:"덥다 → 덥더니 / 좋다 → 좋더니"},{when:"Noun + 이다",add:"-더니",ex:"학생이다 → 학생이더니"},{when:"After a completed first action (-았/었-), often I-subject",add:"-더니",ex:"먹었다 → 먹었더니 / 갔다 → 갔더니"}],examples:[{ko:"동생이 아까 울더니 지금은 잘 놀아요.",romanization:"dongsaengi akka uldeoni jigeumeun jal norayo.",en:"My little brother was crying earlier, and now he's playing happily.",note:"You watched the change yourself; -더니 links 'was crying' to the new state 'now playing.'"},{ko:"아침에는 비가 오더니 오후에는 날씨가 좋아요.",romanization:"achimeneun biga odeoni ohueneun nalssiga joayo.",en:"It was raining in the morning, but in the afternoon the weather is nice.",note:"Here -더니 marks a contrast between two states you saw one after the other."},{ko:"친구가 밥을 너무 많이 먹더니 배가 아프대요.",romanization:"chinguga babeul neomu mani meokdeoni baega apeudaeyo.",en:"My friend ate way too much, and now says his stomach hurts.",note:"The watched first part causes the second — a natural cause and effect with -더니."},{ko:"동생이 열심히 공부하더니 시험을 잘 봤어요.",romanization:"dongsaengi yeolsimhi gongbuhadeoni siheomeul jal bwasseoyo.",en:"My brother studied hard, and so he did well on the test.",note:"-더니 shows the result naturally following the effort you witnessed."}],keyPoint:{label:"-더니 vs. -았/었더니",body:"Plain -더니 reports what you watched someone else (or the world) do, then a follow-up. -았/었더니 usually has 'I' as the subject who finished an action, leading to a result you then found: '제가 밥을 먹었더니 졸려요' (I ate, and now I'm sleepy). Rule of thumb: 더니 → 'they...', 았/었더니 → 'I did..., and then...'."},pronunciation:"In -더니 the 더 is said clearly as [더], with no blending into the next part. With past -었더니, 었더 sounds like [얻떠] with a light tense ㄷ.",drill:{instruction:"Link a first event you watched to its result, using -더니.",model:"비가 오다 / 길이 막히다 → 비가 오더니 길이 막혀요.",items:["동생이 많이 먹다 / 배가 아프다 → ____","친구가 매일 운동하다 / 건강해지다 → ____","아까는 덥다 / 지금은 시원하다 → ____"]},englishSpeakerPitfall:{wrong:"제가 친구를 만나더니 기분이 좋았어요.",right:"제가 친구를 만났더니 기분이 좋았어요. / 친구가 저를 만나더니 반가워했어요.",explanation:"When 'I' am the one who finished the first action, use -았/었더니, not plain -더니. Plain -더니 is for watching someone else (or the world), so its first subject is usually NOT 'I.'"}}],W=[{title:"V/A-다고 했어요 — Reporting what someone said",func:'Use -다고 했어요 to report a statement someone made, like English "said that …". You report the meaning, not the exact words, so you drop the original ending (요/-어) and attach -다고 to the plain stem.',formTable:[{when:"Action verb, present — stem ends in a vowel",add:"-ㄴ다고 했어요",ex:"가다 → 간다고 했어요"},{when:"Action verb, present — stem ends in a 받침",add:"-는다고 했어요",ex:"먹다 → 먹는다고 했어요"},{when:"Adjective, present",add:"-다고 했어요",ex:"바쁘다 → 바쁘다고 했어요 / 좋다 → 좋다고 했어요"},{when:"Any verb/adjective, past",add:"-았/었다고 했어요",ex:"먹었다 → 먹었다고 했어요 / 갔다 → 갔다고 했어요"},{when:"Noun + 이다",add:"N(이)라고 했어요",ex:"학생 → 학생이라고 했어요 / 친구 → 친구라고 했어요"}],examples:[{ko:"친구가 내일 학교에 안 온다고 했어요.",romanization:"chinguga naeil hakgyoe an ondago haesseoyo.",en:"My friend said he won't come to school tomorrow.",note:"오다 is an action verb, so present is 온다고, not 오다고."},{ko:"엄마가 밥을 다 먹었다고 했어요.",romanization:"eommaga babeul da meogeottago haesseoyo.",en:"Mom said she finished eating.",note:"Past tense: keep 먹었- and add -다고. The past never takes -ㄴ다고/-는다고."},{ko:"선생님이 한국어가 안 어렵다고 했어요.",romanization:"seonsaengnimi hangugeoga an eoryeoptago haesseoyo.",en:"The teacher said Korean isn't hard.",note:"어렵다 is an adjective, so just -다고 — no -ㄴ-/-는-."},{ko:"그 사람이 제 친구라고 했어요.",romanization:"geu sarami je chingurago haesseoyo.",en:"He said he's my friend.",note:"Noun + 이다 becomes (이)라고. 친구 ends in a vowel, so 친구라고."}],keyPoint:{label:"Verbs vs. adjectives in the present",body:"Only action verbs add -ㄴ다고/-는다고 (간다고, 먹는다고). Adjectives, and all past forms, just add -다고 (바쁘다고, 먹었다고). The common slips are 먹다고 (should be 먹는다고) and 바쁜다고 (should be 바쁘다고)."},pronunciation:"In 먹는다고 the ㄱ before ㄴ turns into an ㅇ sound, so it comes out [멍는다고].",drill:{instruction:"Report what each person said using -다고 했어요. Watch verb vs. adjective and tense.",model:'민수: "시간이 없어요." → 민수가 시간이 없다고 했어요.',items:['수지: "집에 가요." → 수지가 ___ .','아빠: "어제 영화를 봤어요." → 아빠가 ___ .','친구: "이 책이 재미있어요." → 친구가 ___ .']},englishSpeakerPitfall:{wrong:"친구가 학교에 안 오다고 했어요.",right:"친구가 학교에 안 온다고 했어요.",explanation:`In English you just add "that," so it's tempting to glue -다고 onto the dictionary form 오다. But present-tense action verbs need -ㄴ다고/-는다고: 오다 → 온다고.`}},{title:"V/A-냐고 물어봤어요 — Reporting a question",func:'Use -냐고 물어봤어요 (or 물었어요) to report a question someone asked — "someone asked whether/what …". The reported part ends in -냐고 no matter how polite the original question was.',formTable:[{when:"Verb or adjective, present",add:"-냐고 물어봤어요",ex:"가다 → 가냐고 / 좋다 → 좋냐고 물어봤어요"},{when:"Any verb/adjective, past",add:"-았/었냐고 물어봤어요",ex:"먹었다 → 먹었냐고 / 갔다 → 갔냐고 물어봤어요"},{when:"Noun + 이다",add:"N(이)냐고 물어봤어요",ex:"학생 → 학생이냐고 / 친구 → 친구냐고 물어봤어요"},{when:"With a question word (누구/언제/어디 …)",add:"keep the question word + -냐고",ex:"어디 가다 → 어디 가냐고 물어봤어요"}],examples:[{ko:"친구가 저한테 밥 먹었냐고 물어봤어요.",romanization:"chinguga jeohante bap meogeonnyago mureobwasseoyo.",en:"My friend asked me whether I'd eaten.",note:"Past yes/no question → -었냐고. 한테 marks the person who was asked."},{ko:"선생님이 학생들한테 시간이 있냐고 물어봤어요.",romanization:"seonsaengnimi haksaengdeulhante sigani innyago mureobwasseoyo.",en:"The teacher asked the students whether they had time.",note:"있다 → 있냐고. A yes/no question with no question word."},{ko:"엄마가 어디 가냐고 물어봤어요.",romanization:"eommaga eodi ganyago mureobwasseoyo.",en:"Mom asked where I was going.",note:"The question word 어디 stays where it is — Korean doesn't move it to the front."},{ko:"그 사람이 제가 한국 사람이냐고 물어봤어요.",romanization:"geu sarami jega hanguk saraminyago mureobwasseoyo.",en:"That person asked whether I was Korean.",note:"Noun + 이다 → 이냐고. The subject inside the quote takes 가/이 (제가), not 는."}],keyPoint:{label:"-다고 vs. -냐고",body:"Statements use -다고 했어요; questions use -냐고 물어봤어요. The following verb is your clue: 했어요/말했어요 (said) for statements, 물어봤어요/물었어요 (asked) for questions."},pronunciation:"In 먹었냐고 the ㅆ받침 before ㄴ becomes an ㄴ sound, so it links as [머건냐고].",drill:{instruction:"Report each question with -냐고 물어봤어요. Keep any question word in place.",model:'엄마: "숙제 다 했어?" → 엄마가 숙제 다 했냐고 물어봤어요.',items:['친구: "내일 시간 있어?" → 친구가 ___ .','선생님: "어디 살아요?" → 선생님이 ___ .','동생: "이거 누구 책이야?" → 동생이 ___ .']},englishSpeakerPitfall:{wrong:"친구가 밥 먹었다고 물어봤어요.",right:"친구가 밥 먹었냐고 물어봤어요.",explanation:"Learners reuse the statement ending -다고 with 물어봤어요. But a reported question has to end in -냐고; -다고 only goes with 했어요/말했어요."}},{title:'V-는지 / A-(으)ㄴ지 / N인지 — "whether / what / where …" inside a sentence',func:`Use -는지/-(으)ㄴ지/-인지 to tuck a question inside a bigger sentence — "I don't know whether/what/where …", "Do you know if …?". It turns the question into a clause that then connects to verbs like 알다, 모르다, 궁금하다.`,formTable:[{when:"Action verb, present",add:"-는지",ex:"가다 → 가는지 / 먹다 → 먹는지 모르겠어요"},{when:"Adjective, present",add:"-(으)ㄴ지",ex:"좋다 → 좋은지 / 바쁘다 → 바쁜지 모르겠어요"},{when:"Any verb/adjective, past",add:"-았/었는지",ex:"먹었다 → 먹었는지 / 갔다 → 갔는지 모르겠어요"},{when:"Noun + 이다",add:"N인지",ex:"학생 → 학생인지 / 누구 → 누구인지 모르겠어요"}],examples:[{ko:"친구가 어디 사는지 몰라요.",romanization:"chinguga eodi saneunji mollayo.",en:"I don't know where my friend lives.",note:"살다 drops the ㄹ before -는지 → 사는지. 어디 stays inside the clause."},{ko:"이 영화가 재미있는지 궁금해요.",romanization:"i yeonghwaga jaemiinneunji gunggumhaeyo.",en:"I wonder whether this movie is good.",note:"재미있다 takes -는지 (not -(으)ㄴ지) because of the 있다 part."},{ko:"밥을 다 먹었는지 모르겠어요.",romanization:"babeul da meogeonneunji moreugesseoyo.",en:"I'm not sure whether he finished eating.",note:`Past → -었는지. 모르겠어요 sounds softer than 몰라요, more like "I'm not sure."`},{ko:"저 사람이 누구인지 아세요?",romanization:"jeo sarami nuguinji aseyo?",en:"Do you know who that person is?",note:"누구 + 이다 → 누구인지. It pairs naturally with 알다/아세요."}],keyPoint:{label:"Adjective -(으)ㄴ지 vs. verb -는지",body:"In the present, adjectives take -(으)ㄴ지 (좋은지, 바쁜지) and action verbs take -는지 (가는지, 먹는지). In the past, both use -았/었는지 (좋았는지, 갔는지), so the split only matters in the present."},pronunciation:"먹는지 comes out [멍는지] (ㄱ → ㅇ before ㄴ); in 좋은지 the ㅎ drops, so it sounds like [조은지].",drill:{instruction:"Finish each sentence with -는지/-(으)ㄴ지/-인지. Watch verb vs. adjective and tense.",model:"(친구가 오다) 친구가 ___ 모르겠어요. → 친구가 오는지 모르겠어요.",items:["(이 책이 좋다) 이 책이 ___ 모르겠어요.","(어제 비가 오다) 어제 비가 ___ 모르겠어요.","(저분이 선생님이다) 저분이 ___ 아세요?"]},englishSpeakerPitfall:{wrong:"이 영화가 재미있은지 궁금해요.",right:"이 영화가 재미있는지 궁금해요.",explanation:"재미있다/맛있다/없다 look like adjectives, but the 있/없 part acts like a verb and takes -는지, not -(으)ㄴ지. So it's 재미있는지, 맛있는지, 없는지."}}],U=[{title:"Stacked Noun Modifiers: Packing a Clause Before a Noun",func:'In Korean a whole clause can describe a noun, but it always comes BEFORE the noun, and the verb changes into a modifier form ending in -ㄴ/-은/-는/-(으)ㄹ. So "the book my friend gave me yesterday" becomes 어제 친구가 준 책 — everything piles up in front of 책.',formTable:[{when:"Past action (verb)",add:"-(으)ㄴ",ex:"읽다 → 읽은 (책) / 주다 → 친구가 준 (선물)"},{when:"Present / ongoing (verb)",add:"-는",ex:"먹다 → 먹는 (사람) / 보다 → 내가 보는 (영화)"},{when:"Future / not-yet (verb)",add:"-(으)ㄹ",ex:"가다 → 갈 (곳) / 만나다 → 내일 만날 (친구)"},{when:"Adjective describing a noun",add:"-(으)ㄴ",ex:"예쁘다 → 예쁜 (꽃) / 비싸다 → 비싼 (가방)"}],examples:[{ko:"어제 친구가 준 책을 다 읽었어요.",romanization:"eoje chinguga jun chaegeul da ilgeosseoyo.",en:"I finished reading the book my friend gave me yesterday.",note:'준 (past modifier of 주다) packs "my friend gave" in front of 책.'},{ko:"제가 자주 가는 카페가 문을 닫았어요.",romanization:"jega jaju ganeun kapega muneul dadasseoyo.",en:"The cafe I often go to closed down.",note:"가는 (present modifier of 가다) shows an ongoing, habitual action before 카페. 문을 닫다 = to close down."},{ko:"내일 만날 사람한테 전화했어요.",romanization:"naeil mannal saramhante jeonhwahaesseoyo.",en:"I called the person I'm going to meet tomorrow.",note:"만날 (future modifier of 만나다) marks an action that hasn't happened yet."},{ko:"한국어를 배우는 학생이 많아요.",romanization:"hangugeoreul baeuneun haksaengi manayo.",en:"There are a lot of students who study Korean.",note:"배우는 (present modifier of 배우다) turns a whole clause into one big descriptor for 학생."}],keyPoint:{label:"Past vs. present vs. future modifier",body:"The modifier ending carries the TIME, so the final verb of the sentence can stay simple: 친구가 준 책 (already gave), 친구가 주는 책 (is giving), 친구가 줄 책 (will give). Pick the wrong one and the meaning of the whole noun phrase changes."},pronunciation:"읽은 sounds like [일근] — the ㄺ cluster splits and ㄱ links to 은. 많아요 sounds like [마나요], with the ㅎ in ㄶ dropping out.",drill:{instruction:"Combine the two ideas into one noun phrase using the correct past/present/future modifier, then finish the sentence.",model:"친구가 책을 줬어요 + 그 책 → 친구가 준 책을 읽었어요.",items:["제가 영화를 봐요 + 그 영화 → 제가 ___ 영화가 재미있어요.","어제 밥을 먹었어요 + 그 식당 → 어제 ___ 식당이 좋았어요.","내일 학교에 가요 + 그 친구 → 내일 학교에서 ___ 친구를 만나요."]},englishSpeakerPitfall:{wrong:"책 친구가 어제 준",right:"어제 친구가 준 책",explanation:'English puts the describing clause AFTER the noun ("the book that my friend gave"), so learners often leave 책 first. In Korean the whole clause comes before the noun, and the verb must take a modifier ending — never a sentence-ending form like 줬어요 right in front of the noun.'}},{title:"Passive Verbs (이/히/리/기): Focusing on What Happens, Not the Doer",func:"Passive verbs describe what HAPPENS to something without saying who did it — the focus moves to the result or the affected thing. You build them by adding -이-, -히-, -리-, or -기- inside certain action verbs: 열다 (to open) → 열리다 (to be opened / to open on its own).",formTable:[{when:"add -이-",add:"보다→보이다, 놓다→놓이다, 쌓다→쌓이다",ex:"산이 보여요. (You can see the mountain.)"},{when:"add -히-",add:"닫다→닫히다, 막다→막히다, 잡다→잡히다",ex:"문이 닫혔어요. (The door got closed.)"},{when:"add -리-",add:"열다→열리다, 듣다→들리다, 팔다→팔리다",ex:"음악이 들려요. (You can hear music.)"},{when:"add -기-",add:"끊다→끊기다, 쫓다→쫓기다, 안다→안기다",ex:"전화가 끊겼어요. (The call got cut off.)"}],examples:[{ko:"문이 갑자기 닫혔어요.",romanization:"muni gapjagi dachyeosseoyo.",en:"The door suddenly closed.",note:"닫히다 (passive of 닫다) — nobody is named as the one closing it; we just see the result."},{ko:"여기에서 바다가 잘 보여요.",romanization:"yeogieseo badaga jal boyeoyo.",en:"You can see the sea well from here.",note:'보이다 (passive of 보다) means "is visible," focusing on what shows up, not who looks.'},{ko:"옆방에서 음악이 들려요.",romanization:"yeopbangeseo eumagi deullyeoyo.",en:"I can hear music from the next room.",note:'들리다 (passive of 듣다) = "is heard"; the sound reaches you on its own.'},{ko:"이 책이 요즘 많이 팔려요.",romanization:"i chaegi yojeum mani pallyeoyo.",en:"This book is selling a lot these days.",note:"팔리다 (passive of 팔다) puts the book, not the seller, in the subject spot."}],keyPoint:{label:"Active vs. passive subject marking",body:"In an active sentence the doer takes 이/가 and the thing takes 을/를: 제가 문을 열었어요. In the passive, the affected thing becomes the 이/가 subject and the doer usually drops out: 문이 열렸어요. If you do keep the doer, it takes 에 or 한테/에게: 문이 바람에 열렸어요 (The door opened from the wind)."},pronunciation:"닫히다 sounds like [다치다] — ㄷ and ㅎ blend into ㅊ. 막히다 sounds like [마키다], where ㄱ and ㅎ blend into ㅋ.",drill:{instruction:"Rewrite each active sentence as a passive one: drop the doer and move the thing into subject position.",model:"제가 문을 열었어요. → 문이 열렸어요.",items:["제가 창문을 닫았어요. → 창문이 ___.","사람들이 그 책을 많이 사요. → 그 책이 많이 ___.","제가 산을 봐요. → 여기에서 산이 ___."]},englishSpeakerPitfall:{wrong:"문이 닫아졌어요 (over-using -아/어지다 for everything)",right:"문이 닫혔어요",explanation:`English has one passive ("be + past participle"), so learners reach for -아/어지다 every time. But verbs in the 이/히/리/기 group already have their own passive form, and that is the natural choice. Save -아/어지다 mainly for verbs that don't have such a form.`}},{title:"Causative Verbs (이/히/리/기/우): Making or Helping Someone Do Something",func:"Causative verbs say that the subject CAUSES another person or thing to do or undergo the action. You build them by adding -이-, -히-, -리-, -기-, or -우- inside the verb: 먹다 (to eat) → 먹이다 (to feed = make someone eat).",formTable:[{when:"add -이-",add:"먹다→먹이다, 보다→보이다, 죽다→죽이다",ex:"아기에게 밥을 먹여요. (I feed the baby rice.)"},{when:"add -히-",add:"입다→입히다, 앉다→앉히다, 읽다→읽히다",ex:"아이에게 옷을 입혀요. (I dress the child.)"},{when:"add -리-",add:"울다→울리다, 살다→살리다, 알다→알리다",ex:"동생을 울렸어요. (I made my sibling cry.)"},{when:"add -기-/-우-",add:"웃다→웃기다, 자다→재우다, 타다→태우다",ex:"아기를 재웠어요. (I put the baby to sleep.)"}],examples:[{ko:"엄마가 아기에게 밥을 먹여요.",romanization:"eommaga agiege babeul meogyeoyo.",en:"The mom feeds the baby rice.",note:"먹이다 (causative of 먹다) = make the baby eat; the eater takes 에게/한테."},{ko:"아이에게 따뜻한 옷을 입혔어요.",romanization:"aiege ttatteutan oseul iphyeosseoyo.",en:"I dressed the child in warm clothes.",note:"입히다 (causative of 입다) — the parent makes the child wear the clothes."},{ko:"동생을 울려서 엄마한테 혼났어요.",romanization:"dongsaengeul ullyeoseo eommahante honnasseoyo.",en:"I made my little brother cry, so Mom scolded me.",note:"울리다 (causative of 울다) = make cry; the one crying becomes the 을/를 object."},{ko:"아기를 일찍 재웠어요.",romanization:"agireul iljjik jaewosseoyo.",en:"I put the baby to sleep early.",note:"재우다 (causative of 자다, with -우-) = make sleep; very common in daily life."}],keyPoint:{label:"Causative vs. plain verb — who acts",body:"Plain 자다 means the subject sleeps (아기가 자요 = the baby sleeps). Causative 재우다 means the subject makes someone else sleep (엄마가 아기를 재워요 = Mom puts the baby to sleep). The original doer (the baby) moves from the 이/가 subject to a 을/를 (or 에게) slot — the new subject is the cause."},pronunciation:"입히다 sounds like [이피다] — ㅂ and ㅎ blend into ㅍ. 읽히다 sounds like [일키다], where the ㄱ in the ㄺ cluster joins ㅎ to make ㅋ.",drill:{instruction:'Turn the plain action into a causative — "someone makes the subject do it" — and complete the sentence.',model:"아기가 자요. (엄마) → 엄마가 아기를 재워요.",items:["아기가 밥을 먹어요. (엄마) → 엄마가 아기에게 밥을 ___.","아이가 옷을 입어요. (아빠) → 아빠가 아이에게 옷을 ___.","동생이 울어요. (내가) → 내가 동생을 ___."]},englishSpeakerPitfall:{wrong:"엄마가 아기를 먹게 해요 (always using -게 하다)",right:"엄마가 아기에게 밥을 먹여요",explanation:'English forces "make/let someone do" with a separate verb, so learners default to -게 하다 for everything. When a verb HAS a built-in causative (먹이다, 입히다, 재우다), that one-word form sounds far more natural for concrete, physical actions like feeding, dressing, and putting to sleep.'}}],B=[{title:"V-(으)ㄹ 수밖에 없다 — to have no choice but to",func:`Use this to say there's no other option, so you end up doing the action whether you want to or not. It often sounds a little reluctant: "There's nothing else I can do, so I just do this."`,formTable:[{when:"Verb stem ends in a consonant (받침 O)",add:"-을 수밖에 없다",ex:"먹다 → 먹을 수밖에 없다 (have no choice but to eat)"},{when:"Verb stem ends in a vowel (받침 X)",add:"-ㄹ 수밖에 없다",ex:"가다 → 갈 수밖에 없다 (have no choice but to go)"},{when:"Verb stem ends in ㄹ (ㄹ stays, just add 수밖에 없다)",add:"-ㄹ 수밖에 없다",ex:"살다 → 살 수밖에 없다 (have no choice but to live)"},{when:"Adjectives work too (= it can only be / it's bound to be)",add:"-(으)ㄹ 수밖에 없다",ex:"비싸다 → 비쌀 수밖에 없다 (it's bound to be expensive)"}],examples:[{ko:"버스가 없어서 걸어갈 수밖에 없었어요.",romanization:"beoseu-ga eopseoseo georeogal su-bakke eopseosseoyo.",en:"There was no bus, so I had no choice but to walk.",note:"A reason clause (없어서) plus this pattern is the most common shape: cause, then forced result."},{ko:"시간이 없어서 택시를 탈 수밖에 없어요.",romanization:"sigani eopseoseo taeksi-reul tal su-bakke eopseoyo.",en:"I don't have time, so I have no choice but to take a taxi.",note:"탈 from 타다 (vowel stem) just adds -ㄹ. Shows the everyday 'I'm forced into it' feeling."},{ko:"친구가 약속을 안 지켜서 화가 날 수밖에 없었어요.",romanization:"chinguga yaksogeul an jikyeoseo hwaga nal su-bakke eopseosseoyo.",en:"My friend broke our plans, so I couldn't help getting angry.",note:"With feelings it means 'can't help but'. Getting angry was the only natural reaction."},{ko:"이 식당은 음식이 맛있어서 사람이 많을 수밖에 없어요.",romanization:"i sikdangeun eumsigi masisseoseo sarami manheul su-bakke eopseoyo.",en:"This place's food is so good, of course it's packed.",note:"With an adjective (많다) it means 'it's bound to be'. A natural, can't-be-otherwise conclusion."}],keyPoint:{label:"수밖에 없다 vs. -아/어야 하다",body:"-아/어야 하다 means you 'have to / should' do something (a duty, but other choices might still exist). V-(으)ㄹ 수밖에 없다 means every other option is gone, so you do it even if you'd rather not. '공부해야 해요' = I should study; '공부할 수밖에 없어요' = I've got no other choice but to study. (You'll meet -아/어야 하다 in its own lesson.)"},pronunciation:"수밖에 sounds like [수바께]: the ㄲ of 밖 links into 에 and stays tense. So 수밖에 없다 comes out as [수바께 업따].",drill:{instruction:"Because of the reason, only one thing is left to do. Answer with V-(으)ㄹ 수밖에 없어요.",model:"비가 와요. (집에 있다) → 비가 와서 집에 있을 수밖에 없어요.",items:["돈이 없어요. (집에서 밥을 먹다) → 돈이 없어서 집에서 밥을 ____.","길이 막혀요. (지하철을 타다) → 길이 막혀서 지하철을 ____.","숙제가 많아요. (집에 늦게까지 있다) → 숙제가 많아서 집에 늦게까지 ____."]},englishSpeakerPitfall:{wrong:"걸어갈 수밖에 있어요.",right:"걸어갈 수밖에 없어요.",explanation:"밖에 ('other than / except') always pairs with a negative, so the ending is always 없다, never 있다. 'There's nothing other than walking' = 없다. Saying 있어요 here flips the meaning and just sounds broken to a Korean ear."}},{title:"V-(으)ㄹ 리가 없다 — there's no way that's true",func:`Use this to say you really don't believe something: you're sure it can't be the case because it makes no sense. It's the Korean way of saying "There's no way…" or "It can't possibly be that…"`,formTable:[{when:"Verb/Adjective stem ends in a consonant (받침 O)",add:"-을 리가 없다",ex:"먹다 → 먹을 리가 없다 (there's no way he'd eat it)"},{when:"Verb/Adjective stem ends in a vowel (받침 X)",add:"-ㄹ 리가 없다",ex:"오다 → 올 리가 없다 (there's no way it'll come / he'll come)"},{when:"Past meaning (it already happened)",add:"-았/었을 리가 없다",ex:"가다 → 갔을 리가 없다 (there's no way he went)"},{when:"Noun + 이다",add:"일 리가 없다",ex:"학생 → 학생일 리가 없다 (there's no way he's a student)"}],examples:[{ko:"그 친구가 거짓말을 했을 리가 없어요.",romanization:"geu chinguga geojinmareul haesseul liga eopseoyo.",en:"There's no way that friend lied.",note:"Past form 했을 리가 없다 rejects that a past action happened. Very common with 거짓말."},{ko:"지금 밤 12시인데 학생들이 학교에 있을 리가 없어요.",romanization:"jigeum bam yeoldu-si-inde haksaengdeuri hakgyo-e isseul liga eopseoyo.",en:"It's midnight now, so there's no way the students are at school.",note:"A known fact (it's the middle of the night) makes the idea impossible. The typical 'fact + 리가 없다' shape."},{ko:"한국어를 배운 지 일주일밖에 안 됐는데 잘할 리가 없어요.",romanization:"hangugeo-reul baeun ji iljuilbakke an dwaenneunde jalhal liga eopseoyo.",en:"He's only been learning Korean for a week, so there's no way he's good at it.",note:"Often follows a reason clause with -는데. Uses 잘하다, an everyday verb."},{ko:"이 책이 만 원이라고요? 그렇게 쌀 리가 없어요.",romanization:"i chaegi man wonira-goyo? geureoke ssal liga eopseoyo.",en:"This book is 10,000 won? There's no way it's that cheap.",note:"Adjective 싸다 works too. The speaker rejects the claim as impossible, not just unlikely."}],keyPoint:{label:"-(으)ㄹ 리가 없다 vs. -(으)ㄹ 수 없다",body:"-(으)ㄹ 수 없다 is about real ability: 'can't do it' (갈 수 없어요 = I'm not able to go). -(으)ㄹ 리가 없다 is about your certainty that a claim is false: 'there's no way that's true' (갔을 리가 없어요 = no way he went). The first is about being able; the second is about believing."},pronunciation:"없어요 sounds like [업써요]: the ㅅ of the 없- cluster slides onto the next syllable and goes tense, while ㅂ stays as a stop. So 리가 없어요 comes out as [리가 업써요].",drill:{instruction:"You don't believe the statement. Reject it with V-(으)ㄹ 리가 없어요.",model:"민수가 시험에 떨어졌어요. → 민수가 시험에 떨어졌을 리가 없어요.",items:["저 사람이 한국 사람이에요. → 저 사람이 한국 사람일 리가 ____.","동생이 벌써 집에 갔어요. → 동생이 벌써 집에 ____ 리가 없어요.","이 영화가 재미없어요. → 이 영화가 재미____ 리가 없어요."]},englishSpeakerPitfall:{wrong:"저는 오늘 갈 리가 없어요. (meaning: I can't go today)",right:"저는 오늘 못 가요. / 갈 수 없어요.",explanation:"English 'there's no way' covers both 'I'm unable to' and 'I don't believe it.' But 리가 없다 only means disbelief about a fact, and it sounds odd about your own plans. For 'I can't go,' use 못 가요 or 갈 수 없어요. Save 갈 리가 없어요 for 'there's no way he'd go.'"}},{title:"V-(으)ㄹ 뿐이다 / N뿐이다 — only, nothing more",func:"Use this to limit things to just one: 'that's all there is, nothing else.' With verbs/adjectives it means 'only does / is only'; attached straight to a noun, 뿐이다 means 'only that, and nothing else.'",formTable:[{when:"Verb/Adjective stem + 받침 O",add:"-을 뿐이다",ex:"믿다 → 믿을 뿐이다 (I just believe it, that's all)"},{when:"Verb/Adjective stem + 받침 X",add:"-ㄹ 뿐이다",ex:"기다리다 → 기다릴 뿐이다 (I'm only waiting)"},{when:"Past meaning",add:"-았/었을 뿐이다",ex:"하다 → 했을 뿐이다 (I just did it, nothing more)"},{when:"Noun (no -(으)ㄹ; 뿐 attaches straight to the noun)",add:"N + 뿐이다",ex:"물 → 물뿐이다 (there's only water)"}],examples:[{ko:"저는 사실대로 말했을 뿐이에요.",romanization:"jeoneun sasildaero malhaesseul ppunieyo.",en:"I only told the truth, that's all.",note:"Past 말했을 뿐이다 is the classic 'I just did X, so don't blame me' use."},{ko:"그냥 농담했을 뿐이에요. 화내지 마세요.",romanization:"geunyang nongdamhaesseul ppunieyo. hwanaeji maseyo.",en:"I was just joking, nothing more. Don't be mad.",note:"그냥 ('just') goes naturally with 뿐이다 to play an action down."},{ko:"지금 냉장고에 물뿐이에요.",romanization:"jigeum naengjango-e mulppunieyo.",en:"Right now there's only water in the fridge.",note:"Noun case: 뿐 attaches straight to 물 (no -(으)ㄹ). Means 'water and nothing else.'"},{ko:"이 동네에서 제 친구는 민수뿐이에요.",romanization:"i dongne-eseo je chinguneun minsu-ppunieyo.",en:"In this neighborhood, Minsu is my only friend.",note:"N뿐이다 with a person noun (민수) = 'only him, no one else.' Very common in speech."}],keyPoint:{label:"-(으)ㄹ 뿐이다, N뿐이다, and N일 뿐이다",body:"After a verb or adjective, use the -(으)ㄹ form: 기다릴 뿐이에요. N뿐이다 means 'only N / N is all there is': 물뿐이에요. N일 뿐이다 is also grammatical, but it classifies or plays down the noun: 물일 뿐이에요 = 'it is merely water.' The two noun patterns answer different questions, so do not treat either one as universally wrong."},pronunciation:"뿐이에요 links smoothly as [뿌니에요]: the ㄴ of 뿐 slides onto 이. With a noun like 물, 물뿐이에요 sounds like [물뿌니에요].",drill:{instruction:"Say it's only this, nothing more. Answer with -(으)ㄹ 뿐이에요 for verbs/adjectives, or N뿐이에요 for nouns.",model:"(그냥 / 기다리다) → 그냥 기다릴 뿐이에요.",items:["(사실대로 / 말하다, 과거) → 저는 사실대로 ____ 뿐이에요.","(냉장고에 / 물) → 냉장고에 ____이에요.","(제 친구 / 민수) → 제 친구는 ____이에요."]},englishSpeakerPitfall:{wrong:"물뿐이에요 and 물일 뿐이에요 always mean exactly the same thing.",right:"냉장고에는 물뿐이에요. (Only water is there.) / 이건 물일 뿐이에요. (This is merely water.)",explanation:"N뿐이다 limits what exists or is available. N일 뿐이다 says that something is merely N and nothing more. Both are grammatical; choose the structure that matches the intended message."}}],O=Object.assign({"../../data/chapters/chapter-01.json":e,"../../data/chapters/chapter-02.json":o,"../../data/chapters/chapter-03.json":n,"../../data/chapters/chapter-04.json":t,"../../data/chapters/chapter-05.json":a,"../../data/chapters/chapter-06.json":s,"../../data/chapters/chapter-07.json":i,"../../data/chapters/chapter-08.json":r,"../../data/chapters/chapter-09.json":h,"../../data/chapters/chapter-10.json":l,"../../data/chapters/chapter-11.json":d,"../../data/chapters/chapter-12.json":u,"../../data/chapters/chapter-13.json":m,"../../data/chapters/chapter-14.json":c,"../../data/chapters/chapter-15.json":g,"../../data/chapters/chapter-16.json":y,"../../data/chapters/chapter-17.json":w,"../../data/chapters/chapter-18.json":p,"../../data/chapters/chapter-19.json":f,"../../data/chapters/chapter-20.json":b,"../../data/chapters/chapter-21.json":k,"../../data/chapters/chapter-22.json":_,"../../data/chapters/chapter-23.json":v,"../../data/chapters/chapter-24.json":j,"../../data/chapters/chapter-25.json":x,"../../data/chapters/chapter-26.json":I,"../../data/chapters/chapter-27.json":z,"../../data/chapters/chapter-28.json":T,"../../data/chapters/chapter-29.json":P,"../../data/chapters/chapter-30.json":S,"../../data/chapters/chapter-31.json":A,"../../data/chapters/chapter-32.json":N,"../../data/chapters/chapter-33.json":V,"../../data/chapters/chapter-34.json":E,"../../data/chapters/chapter-35.json":K,"../../data/chapters/chapter-36.json":q,"../../data/chapters/chapter-37.json":W,"../../data/chapters/chapter-38.json":U,"../../data/chapters/chapter-39.json":B});export{O as notes};
